      fetchWithAuth(`${API_URL}/api/tracker`)
        .then(r => r.ok ? r.json() : null)
        .then(data => {
          if (Array.isArray(data)) {
            setCompletedChapters(data.map((item: {chapterId: string}) => item.chapterId));
