  const saveHighlight = async (color: string) => {
    const rawText = selectedText || selectionRange?.toString().trim() || '';
    console.log('[THEOLOGICA-HL] saveHighlight invoked:', {
      color,
      rawText,
      selectionVerse,
      endVerseNumber,
