                const isTouch = typeof window !== 'undefined' && ('ontouchstart' in window || (typeof navigator !== 'undefined' && navigator.maxTouchPoints > 0) || winWidth <= 768);
                const toolbarHalfWidth = winWidth <= 640 ? 155 : 195;
