"use client";

import { useState, useEffect } from 'react';
import { X, Share, PlusSquare } from 'lucide-react';

export default function PWAInstallPrompt() {
  const [isIOS, setIsIOS] = useState(false);
  const [isStandalone, setIsStandalone] = useState(true);
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null); // eslint-disable-line @typescript-eslint/no-explicit-any
  const [showPrompt, setShowPrompt] = useState(false);
  const [theme, setTheme] = useState('dark');

  useEffect(() => {
    const currentTheme = localStorage.getItem('theme') || (document.documentElement.getAttribute('data-theme') === 'light' ? 'light' : 'dark');
    setTheme(currentTheme);
    // Check if running in standalone mode (already installed)
    const checkStandalone = window.matchMedia('(display-mode: standalone)').matches || 
                            (window.navigator as any).standalone === true; // eslint-disable-line @typescript-eslint/no-explicit-any
    setTimeout(() => setIsStandalone(checkStandalone), 0);

    if (checkStandalone) return;

    // Detect iOS Safari
    const ua = window.navigator.userAgent;
    const isIPad = !!ua.match(/iPad/i);
    const isIPhone = !!ua.match(/iPhone/i);
    const isWebKit = !!ua.match(/WebKit/i);
    const isSafari = isWebKit && !ua.match(/CriOS/i); // Not Chrome on iOS

    if ((isIPad || isIPhone) && isSafari) {
      setTimeout(() => setIsIOS(true), 0);
      // Show iOS prompt slightly delayed
      setTimeout(() => setShowPrompt(true), 2000);
    }

    // Android / Chrome
    const handleBeforeInstallPrompt = (e: any) => { // eslint-disable-line @typescript-eslint/no-explicit-any
      e.preventDefault();
      setDeferredPrompt(e);
      setShowPrompt(true);
    };

    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);

    return () => {
      window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
    };
  }, []);

  const handleInstallClick = async () => {
    if (deferredPrompt) {
      deferredPrompt.prompt();
      const { outcome } = await deferredPrompt.userChoice;
      if (outcome === 'accepted') {
        setShowPrompt(false);
      }
      setDeferredPrompt(null);
    }
  };

  if (!showPrompt || isStandalone) return null;

  if (isIOS) {
    return (
      <div className="fixed bottom-[calc(52px+max(calc(env(safe-area-inset-bottom,0px)-28px),4px))] left-3 right-3 sm:left-4 sm:right-4 bg-[#30302e] border border-[#4d4c48] rounded-[20px] p-3.5 sm:p-4 shadow-2xl z-[100] animate-in slide-in-from-bottom-5 fade-in duration-500" style={{ paddingBottom: 'max(env(safe-area-inset-bottom, 0px), 12px)' }}>
        <button onClick={() => setShowPrompt(false)} className="absolute top-3 right-3 text-[#87867f] hover:text-[#faf9f5]">
          <X size={18} />
        </button>
        <div className="flex items-start gap-4">
          <div className="w-12 h-12 bg-[#141413] rounded-xl flex items-center justify-center shrink-0 shadow-inner">
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img src={(theme === 'light' || theme === 'sepia') ? '/logo-light.png' : '/logo-dark.png'} className="w-10 h-10 object-contain" alt="Theologica" />
          </div>
          <div>
            <h3 className="text-[15px] font-semibold text-[#faf9f5] mb-1">Install Theologica</h3>
            <p className="text-[13px] text-[#b0aea5] leading-relaxed">
              Install this app on your iPhone: tap <Share size={14} className="inline mx-1" /> and then <strong className="text-[#faf9f5]">&quot;Add to Home Screen&quot;</strong> <PlusSquare size={14} className="inline mx-1" />.
            </p>
          </div>
        </div>
      </div>
    );
  }

  // Android/Chrome Banner
  return (
    <div className="fixed bottom-[calc(52px+max(calc(env(safe-area-inset-bottom,0px)-28px),4px))] left-3 right-3 sm:left-4 sm:right-4 bg-[#30302e] border border-[#4d4c48] rounded-[20px] p-3.5 sm:p-4 shadow-2xl z-[100] animate-in slide-in-from-bottom-5 fade-in duration-500 flex items-center justify-between">
      <div className="flex items-center gap-3">
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img src={(theme === 'light' || theme === 'sepia') ? '/logo-light.png' : '/logo-dark.png'} className="w-12 h-12 object-contain drop-shadow" alt="Theologica" />
        <div>
          <h3 className="text-[14px] font-semibold text-[#faf9f5]">Install App</h3>
          <p className="text-[12px] text-[#87867f]">Add to your home screen</p>
        </div>
      </div>
      <div className="flex items-center gap-2">
        <button onClick={handleInstallClick} className="bg-[#c96442] hover:bg-[#b5583b] text-white text-[13px] font-medium px-4 py-2 rounded-xl transition-colors">
          Install
        </button>
        <button onClick={() => setShowPrompt(false)} className="p-2 text-[#87867f] hover:text-[#faf9f5]">
          <X size={18} />
        </button>
      </div>
    </div>
  );
}

import { NextRequest, NextResponse } from 'next/server';
import { recordAnalyticsEvent } from '@/lib/analyticsService';
import { auth } from '@clerk/nextjs/server';
import crypto from 'crypto';

import { checkRateLimit, getClientIp } from '@/lib/rateLimit';

export async function POST(req: NextRequest) {
  try {
    const ip = getClientIp(req);
    const rateLimit = await checkRateLimit(`analytics:${ip}`, {
      windowMs: 60 * 1000,
      maxRequests: 60,
    });
    if (!rateLimit.success) {
      return NextResponse.json(
        { error: 'Rate limit exceeded' },
        { status: 429, headers: { 'Retry-After': String(rateLimit.resetSeconds) } }
      );
    }

    let body: any = {};
    const contentType = req.headers.get('content-type') || '';
    if (contentType.includes('application/json')) {
      try {
        body = await req.json();
      } catch {
        body = {};
      }
    } else {
      try {
        const text = await req.text();
        body = text ? JSON.parse(text) : {};
      } catch {
        body = {};
      }
    }

    const eventType = typeof body.eventType === 'string' ? body.eventType.trim() : '';
    if (!eventType) {
      return NextResponse.json({ error: 'Missing eventType' }, { status: 400 });
    }

    // 1. Check Clerk server-side auth (only trusted source for authenticated identity)
    let clerkUserId: string | null = null;
    try {
      const clerkAuth = await auth();
      clerkUserId = clerkAuth.userId;
    } catch {
      // Unauthenticated
    }

    // 2. Check persistent first-party cookie
    let visitorCookie = req.cookies.get('th_vid')?.value;
    let shouldSetCookie = false;

    // 4. Check client-passed anonymousId
    const clientAnonId = typeof body.anonymousId === 'string' && body.anonymousId.length > 5 ? body.anonymousId : null;

    if (!visitorCookie) {
      if (clientAnonId) {
        visitorCookie = clientAnonId;
      } else {
        // Fallback to deterministic IP + User-Agent hash
        const forwarded = req.headers.get('x-forwarded-for')?.split(',')[0]?.trim();
        const ip = forwarded || req.headers.get('x-real-ip') || '127.0.0.1';
        const ua = req.headers.get('user-agent') || 'default-agent';
        visitorCookie = 'vid_' + crypto.createHash('sha256').update(ip + ua).digest('hex').substring(0, 16);
      }
      shouldSetCookie = true;
    }

    // Priority for deterministic visitor identifier:
    // Clerk User ID (logged-in account) > Visitor Cookie > Client ID
    const rawId = clerkUserId || visitorCookie || clientAnonId || 'guest_visitor';

    await recordAnalyticsEvent(eventType, rawId, body.metadata);

    const response = NextResponse.json({ success: true }, { status: 200 });

    if (shouldSetCookie && visitorCookie) {
      response.cookies.set({
        name: 'th_vid',
        value: visitorCookie,
        path: '/',
        maxAge: 60 * 60 * 24 * 365, // 1 year
        sameSite: 'lax',
      });
    }

    return response;
  } catch (err: any) {
    return NextResponse.json({ error: 'Telemetry logging error' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import fs from 'fs';
import path from 'path';
import { findCanonicalBook } from '@/lib/bibleCanon';
import {
  BibleChapter,
  BibleVerse,
} from '@/types/bible';
import { getTranslation } from '@/lib/bibleTranslations';
import { checkRateLimit, getClientIp } from '@/lib/rateLimit';

function cleanVerseText(raw: string): string {
  if (!raw) return '';
  return raw
    .replace(/<S>\d+<\/S>/gi, '')
    .replace(/<[^>]*>/g, '')
    .replace(/\[\d+\]/g, '')
    .replace(/([a-zA-Z,.;:!?’'"]+)\d+/g, '$1')
    .replace(/\s+/g, ' ')
    .trim();
}

export async function GET(
  req: Request,
  { params }: { params: Promise<{ version: string; book: string; chapter: string }> }
) {
  try {
    const ip = getClientIp(req);
    const rateLimit = await checkRateLimit(`bible_passage:${ip}`, {
      windowMs: 60 * 1000,
      maxRequests: 120,
    });
    if (!rateLimit.success) {
      return NextResponse.json(
        { error: 'Rate limit exceeded. Please wait a moment before requesting another chapter.' },
        { status: 429, headers: { 'Retry-After': String(rateLimit.resetSeconds) } }
      );
    }

    const { version, book, chapter } = await params;
    const versionKey = (version || 'bsb').toLowerCase().trim();
    const chapterNum = parseInt(chapter, 10);

    if (!/^\d+$/.test(chapter) || !Number.isSafeInteger(chapterNum) || chapterNum < 1) {
      return NextResponse.json({ error: 'Invalid chapter number' }, { status: 400 });
    }

    const bookMeta = findCanonicalBook(book);
    if (!bookMeta) {
      return NextResponse.json({ error: `Unknown Bible book: ${book}` }, { status: 404 });
    }

    if (chapterNum > bookMeta.chapters) {
      return NextResponse.json(
        { error: `${bookMeta.name} only has ${bookMeta.chapters} chapters.` },
        { status: 400 }
      );
    }

    const transDef = getTranslation(versionKey);
    const defaultCopyright = transDef?.copyrightNotice || '';

    // 1. Local packaged translation source
    if (transDef?.source.type === 'local' || ['bsb', 'web', 'kjv'].includes(versionKey)) {
      try {
        const localDir = transDef?.source.type === 'local' ? transDef.source.dir : versionKey;
        const localPath = path.join(
          process.cwd(),
          'public',
          'bibles',
          localDir,
          `${bookMeta.code}.json`
        );
        if (fs.existsSync(localPath)) {
          const raw = fs.readFileSync(localPath, 'utf-8');
          const data = JSON.parse(raw);
          const verses: BibleVerse[] = data.chapters[String(chapterNum)] || [];

          const responsePayload: BibleChapter = {
            book: bookMeta.code,
            bookName: bookMeta.name,
            chapter: chapterNum,
            translation: (transDef?.abbreviation || versionKey).toUpperCase(),
            verses,
            copyright: defaultCopyright,
          };

          return NextResponse.json(responsePayload, {
            headers: {
              'Cache-Control': 'public, max-age=86400, s-maxage=604800, stale-while-revalidate=86400',
            },
          });
        }
      } catch (localErr) {
        console.warn(`Local file read failed for ${versionKey} ${bookMeta.code}, falling back:`, localErr);
      }
    }

    // 2. Dynamic Fallback: Open Translations via Bolls Life
    const bollsKey = transDef?.source.type === 'bolls' ? transDef.source.key : (versionKey === 'asv' ? 'ASV' : versionKey === 'ylt' ? 'YLT' : null);
    if (bollsKey) {
      const bollsUrl = `https://bolls.life/get-chapter/${bollsKey}/${bookMeta.number}/${chapterNum}/`;

      const res = await fetch(bollsUrl, {
        headers: { Accept: 'application/json' },
        next: { revalidate: 86400 }, // Next.js fetch cache 24h
      });

      if (!res.ok) {
        throw new Error(`Bolls API error: ${res.status} ${res.statusText}`);
      }

      const bollsData = await res.json();
      if (!Array.isArray(bollsData)) {
        throw new Error('Invalid format returned from Bolls API');
      }

      const verses: BibleVerse[] = bollsData.map((v: any) => ({
        verse: Number(v.verse),
        text: cleanVerseText(v.text),
      }));

      const responsePayload: BibleChapter = {
        book: bookMeta.code,
        bookName: bookMeta.name,
        chapter: chapterNum,
        translation: (transDef?.abbreviation || versionKey).toUpperCase(),
        verses,
        copyright: defaultCopyright,
      };

      return NextResponse.json(responsePayload, {
        headers: {
          'Cache-Control': 'public, max-age=86400, s-maxage=604800, stale-while-revalidate=86400',
        },
      });
    }

    // 3. Dynamic Fallback: Copyrighted translations via API.Bible
    const bibleApiKey = process.env.BIBLE_API_KEY || process.env.API_BIBLE_KEY;
    const bibleId = transDef?.source.type === 'api.bible' ? transDef.source.bibleId : null;

    if (bibleId) {
      if (!bibleApiKey) {
        return NextResponse.json(
          {
            error: 'BIBLE_API_KEY_REQUIRED',
            message: `Translation '${(transDef?.abbreviation || versionKey).toUpperCase()}' is copyrighted and requires a valid BIBLE_API_KEY environment variable.`,
            translation: (transDef?.abbreviation || versionKey).toUpperCase(),
          },
          { status: 403 }
        );
      }

      // Fetch from API.Bible
      const chapterId = `${bookMeta.code}.${chapterNum}`;
      const apiBibleUrl = `https://api.scripture.api.bible/v1/bibles/${bibleId}/chapters/${chapterId}?include-verse-numbers=true&content-type=json`;

      const apiBibleRes = await fetch(apiBibleUrl, {
        headers: {
          'api-key': bibleApiKey,
          Accept: 'application/json',
        },
        next: { revalidate: 86400 },
      });

      if (!apiBibleRes.ok) {
        return NextResponse.json(
          {
            error: `API.Bible returned status ${apiBibleRes.status}`,
            translation: versionKey.toUpperCase(),
          },
          { status: apiBibleRes.status }
        );
      }

      const apiBibleData = await apiBibleRes.json();
      // Extract verse contents from API.Bible JSON AST
      const contentList = apiBibleData.data?.content || [];
      const verses: BibleVerse[] = [];
      let currentVerse = 0;
      let currentText = '';

      function walkAst(nodes: any[]) {
        for (const node of nodes) {
          if (node.name === 'verse') {
            if (currentVerse > 0 && currentText.trim()) {
              verses.push({ verse: currentVerse, text: cleanVerseText(currentText) });
              currentText = '';
            }
            const num = parseInt(node.attrs?.number || '', 10);
            if (!isNaN(num)) currentVerse = num;
          } else if (typeof node.text === 'string') {
            currentText += ' ' + node.text;
          }
          if (Array.isArray(node.items)) {
            walkAst(node.items);
          }
        }
      }

      const defaultCopyright = transDef?.copyrightNotice || '';

      walkAst(contentList);
      if (currentVerse > 0 && currentText.trim()) {
        verses.push({ verse: currentVerse, text: cleanVerseText(currentText) });
      }

      const officialCopyright = apiBibleData.data?.copyright || defaultCopyright;
      const fumsToken = apiBibleData.meta?.fumsToken || undefined;

      const responsePayload: BibleChapter = {
        book: bookMeta.code,
        bookName: bookMeta.name,
        chapter: chapterNum,
        translation: versionKey.toUpperCase(),
        verses: verses.length > 0 ? verses : [{ verse: 1, text: apiBibleData.data?.content || 'Text unavailable.' }],
        copyright: officialCopyright,
        fumsToken,
      };

      return NextResponse.json(responsePayload, {
        headers: {
          'Cache-Control': 'public, max-age=86400, s-maxage=604800, stale-while-revalidate=86400',
        },
      });
    }

    return NextResponse.json(
      { error: `Translation '${version}' is not supported.` },
      { status: 400 }
    );
  } catch (err: any) {
    console.error('Bible passage lookup API error:', err);
    return NextResponse.json(
      { error: 'Failed to retrieve scripture passage', details: err.message },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import fs from 'fs';
import path from 'path';
import { checkRateLimit, getClientIp } from '@/lib/rateLimit';

export interface LexiconWordPayload {
  id: string;
  lemma: string;
  transliteration: string;
  strongs: string;
  language: 'Hebrew' | 'Aramaic' | 'Greek';
  partOfSpeech: string;
  pronunciation: string;
  gloss: string;
  derivation: string;
  definition: string;
  outline?: string;
  occurrences: number;
  testament: 'OT' | 'NT';
  keyVerses: string[];
  kjvDef?: string;
}

// In-memory server cache
let HEBREW_DATA: Record<string, any> | null = null;
let GREEK_DATA: Record<string, any> | null = null;
let REVERSE_INDEX: { OT: Record<string, string[]>; NT: Record<string, string[]> } | null = null;

function loadLexiconData() {
  if (HEBREW_DATA && GREEK_DATA && REVERSE_INDEX) return;
  try {
    const dataDir = path.join(process.cwd(), 'public/data/lexicon');
    const hebPath = path.join(dataDir, 'strongs-hebrew.json');
    const grkPath = path.join(dataDir, 'strongs-greek.json');
    const idxPath = path.join(dataDir, 'strongs-reverse-index.json');

    if (fs.existsSync(hebPath)) {
      HEBREW_DATA = JSON.parse(fs.readFileSync(hebPath, 'utf8'));
    }
    if (fs.existsSync(grkPath)) {
      GREEK_DATA = JSON.parse(fs.readFileSync(grkPath, 'utf8'));
    }
    if (fs.existsSync(idxPath)) {
      REVERSE_INDEX = JSON.parse(fs.readFileSync(idxPath, 'utf8'));
    }
  } catch (err) {
    console.error('Failed to load server lexicon data:', err);
  }
}

export async function GET(req: NextRequest) {
  const ip = getClientIp(req);
  const rateLimit = await checkRateLimit(`bible_lexicon:${ip}`, {
    windowMs: 60 * 1000,
    maxRequests: 1200,
  });
  if (!rateLimit.success) {
    return NextResponse.json(
      { error: 'Rate limit exceeded. Please wait a moment before requesting more lexicon entries.' },
      { status: 429, headers: { 'Retry-After': String(rateLimit.resetSeconds) } }
    );
  }

  loadLexiconData();

  const { searchParams } = new URL(req.url);
  const id = searchParams.get('id')?.trim().toUpperCase();
  const word = searchParams.get('word')?.trim();
  const testament = searchParams.get('testament')?.toUpperCase() as 'OT' | 'NT' | undefined;
  const verseRef = searchParams.get('verseRef')?.trim();

  // 1. Batch Strong's IDs Lookup (e.g. ?ids=H1,H5862,H3157)
  const idsParam = searchParams.get('ids')?.trim().toUpperCase();
  if (idsParam) {
    const requestedIds = idsParam.split(',').map((s) => s.trim()).filter(Boolean);
    const words: Record<string, LexiconWordPayload> = {};
    for (const rawId of requestedIds) {
      let rawEntry: any = null;
      if (rawId.startsWith('H') && HEBREW_DATA) {
        rawEntry = HEBREW_DATA[rawId];
      } else if (rawId.startsWith('G') && GREEK_DATA) {
        rawEntry = GREEK_DATA[rawId];
      }
      if (rawEntry) {
        words[rawId] = {
          ...rawEntry,
          keyVerses: verseRef ? [verseRef] : [],
        };
      }
    }
    return NextResponse.json(
      { success: true, words },
      {
        headers: {
          'Cache-Control': 'public, max-age=31536000, immutable',
        },
      }
    );
  }

  // 2. Direct Strong's ID Lookup (e.g. H3157 or G3056)
  if (id) {
    let rawEntry: any = null;
    if (id.startsWith('H') && HEBREW_DATA) {
      rawEntry = HEBREW_DATA[id];
    } else if (id.startsWith('G') && GREEK_DATA) {
      rawEntry = GREEK_DATA[id];
    }

    if (rawEntry) {
      const payload: LexiconWordPayload = {
        ...rawEntry,
        keyVerses: verseRef ? [verseRef] : []
      };
      return NextResponse.json({ success: true, word: payload }, {
        headers: {
          'Cache-Control': 'public, max-age=31536000, immutable'
        }
      });
    }

    return NextResponse.json({ success: false, error: `Strong's ID ${id} not found` }, { status: 404 });
  }

  // 2. English word / lemma reverse lookup
  if (word && REVERSE_INDEX) {
    const clean = word.toLowerCase().replace(/[^a-z]/g, '');
    const candidates: string[] = [clean];

    if (clean.endsWith('ed')) {
      candidates.push(clean.slice(0, -1)); // created -> create, loved -> love
      candidates.push(clean.slice(0, -2)); // walked -> walk
    }
    if (clean.endsWith('ing')) {
      candidates.push(clean.slice(0, -3));
      candidates.push(clean.slice(0, -3) + 'e'); // loving -> love, creating -> create
    }
    if (clean.endsWith('eth') || clean.endsWith('est')) {
      candidates.push(clean.slice(0, -3));
      candidates.push(clean.slice(0, -3) + 'e'); // maketh -> make, giveth -> give
    }
    if (clean.endsWith('es')) {
      candidates.push(clean.slice(0, -2)); // churches -> church
      candidates.push(clean.slice(0, -1)); // gives -> give
    } else if (clean.endsWith('s') && !clean.endsWith('ss')) {
      candidates.push(clean.slice(0, -1)); // heavens -> heaven, words -> word
    }

    const irregulars: Record<string, string> = {
      spake: 'speak', dwelt: 'dwell', begat: 'beget', smote: 'smite',
      saw: 'see', went: 'go', came: 'come', said: 'say', knew: 'know',
      stood: 'stand', sent: 'send', gave: 'give', took: 'take',
      found: 'find', made: 'make', built: 'build', heavens: 'heaven',
      brethren: 'brother', children: 'child', men: 'man', women: 'woman',
      feet: 'foot', eyes: 'eye', hearts: 'heart', holy: 'holy',
      righteousness: 'righteous', faith: 'faith', spirit: 'spirit'
    };
    if (irregulars[clean]) {
      candidates.push(irregulars[clean]);
    }

    let matchedId: string | undefined;

    // Search preferred testament first
    for (const c of candidates) {
      if (testament === 'OT' && REVERSE_INDEX.OT[c]?.[0]) {
        matchedId = REVERSE_INDEX.OT[c][0];
        break;
      }
      if (testament === 'NT' && REVERSE_INDEX.NT[c]?.[0]) {
        matchedId = REVERSE_INDEX.NT[c][0];
        break;
      }
    }

    // Fallback to either testament
    if (!matchedId) {
      for (const c of candidates) {
        matchedId = testament === 'OT'
          ? REVERSE_INDEX.OT[c]?.[0] || REVERSE_INDEX.NT[c]?.[0]
          : REVERSE_INDEX.NT[c]?.[0] || REVERSE_INDEX.OT[c]?.[0];
        if (matchedId) break;
      }
    }

    if (matchedId) {
      const isHebrew = matchedId.startsWith('H');
      const rawEntry = isHebrew ? HEBREW_DATA?.[matchedId] : GREEK_DATA?.[matchedId];
      if (rawEntry) {
        const payload: LexiconWordPayload = {
          ...rawEntry,
          keyVerses: verseRef ? [verseRef] : []
        };
        return NextResponse.json({ success: true, word: payload }, {
          headers: {
            'Cache-Control': 'public, max-age=31536000, immutable'
          }
        });
      }
    }
  }

  return NextResponse.json({ success: false, error: 'Word not found in biblical lexicon' }, { status: 404 });
}

export async function POST(req: NextRequest) {
  const ip = getClientIp(req);
  const rateLimit = await checkRateLimit(`bible_lexicon_post:${ip}`, {
    windowMs: 60 * 1000,
    maxRequests: 300,
  });
  if (!rateLimit.success) {
    return NextResponse.json(
      { error: 'Rate limit exceeded. Please wait a moment.' },
      { status: 429, headers: { 'Retry-After': String(rateLimit.resetSeconds) } }
    );
  }

  loadLexiconData();

  try {
    const body = await req.json();
    const { ids, verseRef } = body;
    if (Array.isArray(ids)) {
      const sliceIds = ids.slice(0, 100);
      const words: Record<string, LexiconWordPayload> = {};
      for (const rawId of sliceIds) {
        const uId = String(rawId).trim().toUpperCase();
        let rawEntry: any = null;
        if (uId.startsWith('H') && HEBREW_DATA) {
          rawEntry = HEBREW_DATA[uId];
        } else if (uId.startsWith('G') && GREEK_DATA) {
          rawEntry = GREEK_DATA[uId];
        }
        if (rawEntry) {
          words[uId] = {
            ...rawEntry,
            keyVerses: verseRef ? [verseRef] : [],
          };
        }
      }
      return NextResponse.json({ success: true, words });
    }
    return NextResponse.json({ error: 'ids array required' }, { status: 400 });
  } catch (err) {
    return NextResponse.json({ error: 'Failed to process request' }, { status: 500 });
  }
}

