Connect these sequentially with descriptive edge labels (e.g. "Occasion for", "Builds Premise", "Exegetical Pivot", "Yields Command").
` : ''}

${theologicalLens && theologicalLens !== 'canonical' ? `
THEOLOGICAL LENS APPLIED (${theologicalLens.toUpperCase()}):
Draw specifically upon the hermeneutics, historical citations, and theological emphasis of the ${theologicalLens} tradition.
` : ''}

USER INSTRUCTION:
"${prompt}"

INSTRUCTIONS:
1. Return a STRICT JSON object with no wrapping outside the JSON.
2. Provide a "boardTitle": A concise, descriptive, memorable title for the canvas board (3-6 words, e.g. "Romans 8: The Golden Chain", "The Abrahamic Covenant", "Beatitudes & Kingdom Ethics", "Messianic Types in Exodus").
3. If the user wants to generate or expand a knowledge graph (e.g. topic, passage, expanding a node):
   - Provide high quality, substantive markdown content for each card. Include scripture references and rich formatting (bullet points, quotes, bold).
   - Return an array of "nodes" with:
     - "title": concise clear title
     - "content": markdown content (1-4 concise paragraphs with quotes/bullets)
     - "category": one of ["scripture", "theological_point", "historical_context", "illustration", "application", "general"]
   - Return an array of "edges" showing theological or narrative flow:
     - "sourceIndex": index of source node (0-indexed) or existing node ID
     - "targetIndex": index of target node (0-indexed) or existing node ID
     - "label": brief relationship label (e.g., "Scriptural Basis", "Historic Context", "Fulfills", "Application", "Contrasts With")
4. If the user wants to synthesize or ask a question about the canvas ("synthesize_graph" or "answer"):
   - Set "action": "synthesize_graph"
   - Provide a comprehensive "synthesis" in markdown format synthesizing the nodes and ideas on the canvas.
   - You may still optionally generate summary cards.
5. Always provide an "explanation" string summarizing what you created or analyzed.
6. If the user's prompt is completely unrelated to the Bible, Christian theology, Scripture, or biblical history, return:
   {
     "action": "unrelated_topic",
     "boardTitle": "Untitled Study",
     "explanation": "Topic is not related to biblical study.",
     "error": "Please enter a topic, question, or passage related to Scripture or biblical study."
   }

JSON Format:
{
  "action": "add_nodes" | "expand_node" | "synthesize_graph" | "unrelated_topic",
  "boardTitle": "Concise Descriptive Title for Canvas Board",
  "explanation": "Summary of visual graph operations...",
  "nodes": [
    {
      "title": "...",
      "content": "...",
      "category": "scripture" | "theological_point" | "historical_context" | "illustration" | "application" | "general"
    }
  ],
  "edges": [
    {
      "sourceIndex": 0,
      "targetIndex": 1,
      "label": "..."
    }
  ],
  "synthesis": "Optional markdown text if synthesizing"
}`;

    const aiResponseText = await withModelFallback(AI_MODELS, async (model) => {
      const response = await ai.models.generateContent({
        model,
        contents: systemPrompt,
        config: {
          temperature: 0.3,
          responseMimeType: 'application/json',
          thinkingConfig: { thinkingBudget: 0 },
        },
      });
      return response.text ?? '';
    });

    if (!aiResponseText || !aiResponseText.trim()) {
      return NextResponse.json(
        { error: "Sorry, we couldn't process your request at this time. Please try again or rephrase your topic." },
        { status: 500 }
      );
    }

    let parsed: AiResponsePayload;
    try {
      let cleaned = aiResponseText.trim();
      // Match markdown json code block if present anywhere in the output
      const jsonMatch = cleaned.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
      if (jsonMatch) {
        cleaned = jsonMatch[1].trim();
      } else {
        // Fallback: extract between the first opening brace/bracket and last closing brace/bracket
        const firstBrace = cleaned.search(/[{\[]/);
        const lastBrace = Math.max(cleaned.lastIndexOf('}'), cleaned.lastIndexOf(']'));
        if (firstBrace !== -1 && lastBrace > firstBrace) {
          cleaned = cleaned.substring(firstBrace, lastBrace + 1);
        }
      }
      parsed = JSON.parse(cleaned);
    } catch (parseErr) {
      console.error('Failed to parse Theologica Canvas JSON:', parseErr, aiResponseText);
      return NextResponse.json(
        { error: "Sorry, we couldn't process your request at this time. Please try again or rephrase your topic." },
        { status: 500 }
      );
    }

    if ((parsed as any).action === 'unrelated_topic' || (parsed as any).error) {
      return NextResponse.json(
        { error: (parsed as any).error || 'Please enter a topic, question, or passage related to Scripture or biblical study.' },
        { status: 400 }
      );
    }

    // Assign collision-free spatial layout coordinates
    const createdNodes: SerializableNode[] = [];
    const createdEdges: SerializableEdge[] = [];
    const timestamp = Date.now();
    const rawNodes = parsed.nodes || [];
    const nodeIdMap: Record<number | string, string> = {};

    // Helper function to estimate card height from title and content length
    const estimateAiCardHeight = (title?: string, content?: string): number => {
      let estimated = 90; // Header, body padding, accent strip
      const t = title || '';
      const rawTitleLines = t.split('\n');
      let titleLines = 0;
      for (const tLine of rawTitleLines) {
        titleLines += Math.max(1, Math.ceil(tLine.length / 26));
      }
      if (titleLines > 1) {
        estimated += (titleLines - 1) * 22;
      }
      const c = content || '';
      if (c.trim()) {
        const rawLines = c.split('\n');
        let visualLines = 0;
        for (const line of rawLines) {
          const trimmed = line.trim();
          if (!trimmed) {
            visualLines += 0.6;
            continue;
          }
          const wrapped = Math.max(1, Math.ceil(trimmed.length / 44));
          visualLines += wrapped;
          if (trimmed.startsWith('#')) visualLines += 0.8;
          if (trimmed.startsWith('>')) visualLines += 0.6;
          if (trimmed.startsWith('- ') || trimmed.startsWith('* ') || /^\d+\./.test(trimmed)) visualLines += 0.3;
        }
        estimated += Math.round(visualLines * 22);
      } else {
        estimated += 60;
      }
      return Math.max(190, Math.min(estimated, 1800));
    };

    // Optimal handle selector: connects side-to-side across columns or top-to-bottom in same column
    const getOptimalHandles = (
      sourcePos: { x: number; y: number },
      targetPos: { x: number; y: number }
    ): { sourceHandle: string; targetHandle: string } => {
      const dx = targetPos.x - sourcePos.x;
      const dy = targetPos.y - sourcePos.y;

      // When target is to the right (standard column progression)
      if (dx >= 160) {
        return { sourceHandle: 'right-source', targetHandle: 'left-target' };
      }
      // When target is to the left
      if (dx <= -160) {
        return { sourceHandle: 'left-source', targetHandle: 'right-target' };
      }
      // When in same column and target is below
      if (dy >= 50) {
        return { sourceHandle: 'bottom-source', targetHandle: 'top-target' };
      }
      // When in same column and target is above
      if (dy <= -50) {
        return { sourceHandle: 'top-source', targetHandle: 'bottom-target' };
      }

      return { sourceHandle: 'right-source', targetHandle: 'left-target' };
    };

    // Obsidian Canvas spacious layout constants: 380px width + 320px open channel between side-to-side columns
    const CARD_WIDTH = 380;
    const HORIZONTAL_GAP = 320; // column step = 700px
    const VERTICAL_GAP = 110;
    const COL_STEP = CARD_WIDTH + HORIZONTAL_GAP; // 700px

    if (selectedNode) {
      // MODE: Expanding a selected node - fan out cleanly to the right
      const total = rawNodes.length;
      const maxRowsPerCol = total <= 4 ? total : Math.ceil(total / 2);
      const baseX = selectedNode.position.x + COL_STEP;

      // Group node indices into columns
      const cols: number[][] = [];
      rawNodes.forEach((_, index) => {
        const c = Math.floor(index / maxRowsPerCol);
        while (cols.length <= c) cols.push([]);
        cols[c].push(index);
      });

      // Position each column using cumulative dynamic heights
      cols.forEach((colIndices, colIdx) => {
        const colHeights = colIndices.map(idx => estimateAiCardHeight(rawNodes[idx].title, rawNodes[idx].content));
        const totalColH = colHeights.reduce((sum, h) => sum + h, 0) + Math.max(0, colIndices.length - 1) * VERTICAL_GAP;
        const startY = selectedNode.position.y - (totalColH / 2);

        let currentY = startY;
        colIndices.forEach((nodeIdx, r) => {
          const rawNode = rawNodes[nodeIdx];
          const uniqueId = `node-${timestamp}-${nodeIdx}-${Math.random().toString(36).substring(2, 6)}`;
          nodeIdMap[nodeIdx] = uniqueId;

          const posX = baseX + (colIdx * COL_STEP);
          const posY = currentY;
          currentY += colHeights[r] + VERTICAL_GAP;

          createdNodes.push({
            id: uniqueId,
            type: 'customCard',
            position: { x: Math.round(posX), y: Math.round(posY) },
            style: { width: CARD_WIDTH },
            data: {
              title: rawNode.title || 'Theological Insight',
              content: rawNode.content || '',
              category: rawNode.category || 'theological_point',
            },
          });
        });
      });

      // Connect parent node to all newly expanded nodes if no edges provided
      if ((!parsed.edges || parsed.edges.length === 0) && createdNodes.length > 0) {
        createdNodes.forEach((node, idx) => {
          const handles = getOptimalHandles(selectedNode.position, node.position);
          createdEdges.push({
            id: `edge-${timestamp}-conn-${idx}`,
            source: selectedNode.id,
            target: node.id,
            sourceHandle: handles.sourceHandle,
            targetHandle: handles.targetHandle,
            label: idx === 0 ? 'Expands' : 'Related Point',
            animated: true,
          });
        });
      }
    } else {
      // MODE: Generating a new knowledge graph - Organize into topological columns matching edge flow
      let baseX = 140;
      let baseY = 120;

      if (existingNodes.length > 0) {
        let maxX = -Infinity;
        for (const n of existingNodes) {
          if (n.position.x > maxX) maxX = n.position.x;
        }
        baseX = maxX + COL_STEP;
      }

      // Calculate in-degrees for topological rank from generated edges
      const inDegree: Record<number, number> = {};
      rawNodes.forEach((_, i) => { inDegree[i] = 0; });
      if (parsed.edges && Array.isArray(parsed.edges)) {
        parsed.edges.forEach((e: any) => {
          if (typeof e.targetIndex === 'number' && inDegree[e.targetIndex] !== undefined) {
            inDegree[e.targetIndex] = (inDegree[e.targetIndex] || 0) + 1;
          }
        });
      }

      const parsedEdges: any[] = (parsed.edges && Array.isArray(parsed.edges)) ? parsed.edges : [];
      const hasEdges = parsedEdges.length > 0;
      const columns: number[][] = [];

      if (hasEdges) {
        const ranks: Record<number, number> = {};
        const queue: number[] = [];

        rawNodes.forEach((_, i) => {
          if (inDegree[i] === 0) {
            ranks[i] = 0;
            queue.push(i);
          }
        });

        if (queue.length === 0 && rawNodes.length > 0) {
          ranks[0] = 0;
          queue.push(0);
        }

        while (queue.length > 0) {
          const curr = queue.shift()!;
          const currRank = ranks[curr];
          parsedEdges
            .filter((e: any) => e.sourceIndex === curr)
            .forEach((e: any) => {
              if (typeof e.targetIndex === 'number') {
                const nextRank = Math.max(ranks[e.targetIndex] || 0, currRank + 1);
                ranks[e.targetIndex] = nextRank;
                if (!queue.includes(e.targetIndex)) {
                  queue.push(e.targetIndex);
                }
              }
            });
        }

        rawNodes.forEach((rawNode, i) => {
          if (ranks[i] === undefined) {
            const cat = rawNode.category;
            if (cat === 'scripture' || cat === 'historical_context') ranks[i] = 0;
            else if (cat === 'illustration' || cat === 'application') ranks[i] = 2;
            else ranks[i] = 1;
          }
        });

        rawNodes.forEach((_, i) => {
          const r = Math.min(ranks[i] || 0, 3);
          while (columns.length <= r) columns.push([]);
          columns[r].push(i);
        });
      } else {
        const col0: number[] = [];
        const col1: number[] = [];
        const col2: number[] = [];

        rawNodes.forEach((rawNode, index) => {
          const cat = rawNode.category || 'theological_point';
          if (cat === 'scripture' || cat === 'historical_context') {
            col0.push(index);
          } else if (cat === 'illustration' || cat === 'application') {
            col2.push(index);
          } else {
            col1.push(index);
          }
        });

        [col0, col1, col2].filter(c => c.length > 0).forEach(c => columns.push(c));
      }

      if (columns.length === 0) {
        columns.push(rawNodes.map((_, i) => i));
      }

      // Compute total cumulative height per column
      const colTotalHeights: number[] = columns.map(colIndices => {
        let sum = 0;
        colIndices.forEach((idx, i) => {
          const h = estimateAiCardHeight(rawNodes[idx].title, rawNodes[idx].content);
          sum += h;
          if (i < colIndices.length - 1) sum += VERTICAL_GAP;
        });
        return sum;
      });

      const maxColHeight = Math.max(...colTotalHeights, 1);

      columns.forEach((colIndices, colIdx) => {
        const startY = baseY; // Clean, disciplined top alignment across all columns

        let currentY = startY;
        colIndices.forEach((nodeIdx) => {
          const rawNode = rawNodes[nodeIdx];
          const uniqueId = `node-${timestamp}-${nodeIdx}-${Math.random().toString(36).substring(2, 6)}`;
          nodeIdMap[nodeIdx] = uniqueId;

          const cardH = estimateAiCardHeight(rawNode.title, rawNode.content);
          const posX = baseX + (colIdx * COL_STEP);
          const posY = currentY;
          currentY += cardH + VERTICAL_GAP;

          createdNodes.push({
            id: uniqueId,
            type: 'customCard',
            position: { x: Math.round(posX), y: Math.round(posY) },
            style: { width: CARD_WIDTH },
            data: {
              title: rawNode.title || 'Theological Insight',
              content: rawNode.content || '',
              category: rawNode.category || 'theological_point',
            },
          });
        });
      });
    }

    // Map raw edges with optimal side-to-side and top-to-bottom connection handles
    if (parsed.edges && Array.isArray(parsed.edges)) {
      parsed.edges.forEach((rawEdge, edgeIndex) => {
        let sourceId: string | undefined;
        let targetId: string | undefined;

        // Check if sourceIndex is index in new nodes or existing node ID
        if (typeof rawEdge.sourceIndex === 'number' && nodeIdMap[rawEdge.sourceIndex]) {
          sourceId = nodeIdMap[rawEdge.sourceIndex];
        } else if (typeof rawEdge.sourceIndex === 'string') {
          sourceId = existingNodes.some(n => n.id === rawEdge.sourceIndex)
            ? rawEdge.sourceIndex
            : nodeIdMap[rawEdge.sourceIndex] || (selectedNode?.id);
        }

        if (typeof rawEdge.targetIndex === 'number' && nodeIdMap[rawEdge.targetIndex]) {
          targetId = nodeIdMap[rawEdge.targetIndex];
        } else if (typeof rawEdge.targetIndex === 'string') {
          targetId = existingNodes.some(n => n.id === rawEdge.targetIndex)
            ? rawEdge.targetIndex
            : nodeIdMap[rawEdge.targetIndex];
        }

        if (sourceId && targetId && sourceId !== targetId) {
          const sNode = createdNodes.find(n => n.id === sourceId) || existingNodes.find(n => n.id === sourceId);
          const tNode = createdNodes.find(n => n.id === targetId) || existingNodes.find(n => n.id === targetId);

          const handles = sNode && tNode
            ? getOptimalHandles(sNode.position, tNode.position)
            : { sourceHandle: 'right-source', targetHandle: 'left-target' };

          createdEdges.push({
            id: `edge-${timestamp}-${edgeIndex}-${Math.random().toString(36).substring(2, 6)}`,
            source: sourceId,
            target: targetId,
            sourceHandle: handles.sourceHandle,
            targetHandle: handles.targetHandle,
            label: rawEdge.label && String(rawEdge.label).trim() !== '' ? rawEdge.label : 'Relates to',
            animated: true,
          });
        }
      });
    }

    const rawAiBoardTitle = typeof parsed.boardTitle === 'string' ? parsed.boardTitle.trim() : '';
    const effectiveBoardTitle = rawAiBoardTitle || deriveFallbackBoardTitle(prompt);

    recordAnalyticsEvent('canvas_ai_generate', actorId, { feature: 'canvas', mode }).catch(() => {});

    return NextResponse.json({
      action: parsed.action || 'add_nodes',
      boardTitle: effectiveBoardTitle,
      explanation: parsed.explanation || 'Visual graph generated successfully.',
      nodes: createdNodes,
      edges: createdEdges,
      synthesis: parsed.synthesis,
    });
  } catch (error: any) {
    console.error('Error in /api/canvas/ai:', error);
    return NextResponse.json(
      { error: "Sorry, we couldn't process your request at this time. Please try again or rephrase your topic." },
      { status: 500 }
    );
  }
}

