import { NextResponse } from 'next/server';
import { auth, verifyToken } from '@clerk/nextjs/server';
import prisma from '@/lib/prisma';
import { CanvasStatePayload, SerializableNode, SerializableEdge } from '@/types/canvas';

async function getSafeUserId(req?: Request): Promise<string | null> {
  try {
    const clerkAuth = await auth();
    if (clerkAuth?.userId) {
      return clerkAuth.userId;
    }
  } catch {}

  if (req) {
    try {
      const authHeader = req.headers.get('authorization') || req.headers.get('Authorization');
      if (authHeader && authHeader.toLowerCase().startsWith('bearer ')) {
        const token = authHeader.substring(7).trim();
        if (token) {
          if (process.env.CLERK_SECRET_KEY) {
            try {
              const verified = await verifyToken(token, {
                secretKey: process.env.CLERK_SECRET_KEY,
              });
              if (verified && typeof verified.sub === 'string' && verified.sub) {
                return verified.sub;
              }
            } catch {}
          }
        }
      }
    } catch {}
  }
  return null;
}

export async function POST(req: Request) {
  try {
    const body = await req.json();
    const code = body?.code || body?.sourceBoardId;
    const rawCode = typeof code === 'string' ? code.trim() : '';

    if (!rawCode) {
      return NextResponse.json({ error: 'Share link or board code is required.' }, { status: 400 });
    }

    // Extract boardId from link or raw code (e.g., https://.../share/canvas/board-123456 -> board-123456)
    let sourceBoardId = rawCode;
    const match = rawCode.match(/(?:share\/canvas\/|board-)([a-zA-Z0-9_-]+)/);
    if (match) {
      sourceBoardId = match[0].startsWith('share/canvas/') ? match[1] : match[0];
    }

    const userId = await getSafeUserId(req);

    // 1. Look up the source board from PostgreSQL Prisma (must be public or owned by requester)
    let sourceBoard: any = null;
    try {
      sourceBoard = await prisma.canvas.findFirst({
        where: {
          boardId: sourceBoardId,
          OR: [
            { isPublic: true },
            ...(userId ? [{ userId }] : []),
          ],
        },
      });
    } catch (dbErr) {
      console.warn('Canvas Import: DB lookup failed:', dbErr);
    }

    if (!sourceBoard) {
      return NextResponse.json(
        { error: 'Canvas board not found or is not shared publicly.' },
        { status: 404 }
      );
    }

    // 2. Clone into recipient account
    const newBoardId = `board-${crypto.randomUUID()}`;
    const newTitle = sourceBoard.title || 'Imported Canvas';
    const nodes = (sourceBoard.nodes as any) || [];
    const edges = (sourceBoard.edges as any) || [];
    const viewport = (sourceBoard.viewport as any) || undefined;

    let savedBoard: any = null;
    if (userId) {
      try {
        savedBoard = await prisma.canvas.create({
          data: {
            userId,
            boardId: newBoardId,
            title: newTitle,
            nodes,
            edges,
            viewport,
          },
        });
      } catch (saveErr) {
        console.warn('Canvas Import: DB insert failed, returning cloned payload for local storage:', saveErr);
      }
    }

    const nowIso = new Date().toISOString();

    return NextResponse.json({
      success: true,
      board: {
        id: newBoardId,
        title: savedBoard?.title || newTitle,
        nodes,
        edges,
        viewport,
        nodeCount: Array.isArray(nodes) ? nodes.length : 0,
        updatedAt: savedBoard?.updatedAt?.toISOString() || nowIso,
        sourceBoardId,
      },
    });
  } catch (error: any) {
    console.error('Error in POST /api/canvas/import:', error);
    return NextResponse.json(
      { error: 'Failed to import shared canvas.' },
      { status: 500 }
    );
  }
}

import { auth, verifyToken } from '@clerk/nextjs/server';
import { NextResponse } from 'next/server';
import prisma from '@/lib/prisma';
import { CanvasStatePayload, CanvasBoardMetadata } from '@/types/canvas';

// In-memory fallback cache for anonymous sessions or transient offline resilience
const memoryCache: Record<string, { payload: CanvasStatePayload; title: string; updatedAt: string }> = {};
const memoryIndexCache: Record<string, CanvasBoardMetadata[]> = {};

async function getSafeUserId(req?: Request): Promise<string | null> {
  // 1. First try standard Clerk cookie/session auth
  try {
    const clerkAuth = await auth();
    if (clerkAuth?.userId) {
      return clerkAuth.userId;
    }
  } catch {
    // Fall through to authorization header inspection
  }

  // 2. Check Authorization Bearer header (crucial for mobile Safari, PWA, or third-party cookie restrictions)
  if (req) {
    try {
      const authHeader = req.headers.get('authorization') || req.headers.get('Authorization');
      if (authHeader && authHeader.toLowerCase().startsWith('bearer ')) {
        const token = authHeader.substring(7).trim();
        if (token) {
          // Attempt official Clerk verifyToken if secret key is available
          if (process.env.CLERK_SECRET_KEY) {
            try {
              const verified = await verifyToken(token, {
                secretKey: process.env.CLERK_SECRET_KEY,
              });
              if (verified && typeof verified.sub === 'string' && verified.sub) {
                return verified.sub;
              }
            } catch {
              return null;
            }
          }
        }
      }
    } catch {
      // Ignore header errors
    }
  }

  return null;
}

export async function GET(req: Request) {
  try {
    const userId = await getSafeUserId(req);
    const activeUserId = userId || 'anonymous_user';

    const url = new URL(req.url);
    const isList = url.searchParams.get('list') === 'true';

    // 1. Fetch Board List
    if (isList) {
      if (!userId) {
        return NextResponse.json([]);
      }

      try {
        const dbRecords = await prisma.canvas.findMany({
          where: {
            userId,
          },
          select: {
            boardId: true,
            title: true,
            updatedAt: true,
            nodes: true,
          },
          orderBy: { updatedAt: 'desc' },
        });

        const list: CanvasBoardMetadata[] = dbRecords.map((r) => ({
          id: r.boardId,
          title: r.title,
          updatedAt: r.updatedAt.toISOString(),
          nodeCount: Array.isArray(r.nodes) ? r.nodes.length : 0,
        }));

        memoryIndexCache[userId] = list;
        return NextResponse.json(list);
      } catch (dbErr) {
        console.warn('Canvas: PostgreSQL list query failed, falling back to memory:', dbErr);
      }

      const fallbackList = memoryIndexCache[userId] || [];
      return NextResponse.json(fallbackList);
    }

    // 2. Fetch Single Board
    const boardId = url.searchParams.get('id');
    if (!boardId) {
      return NextResponse.json({ error: 'Board ID is required.' }, { status: 400 });
    }

    const cacheKey = `${activeUserId}_${boardId}`;

    let dbRecord: any = null;
    let ownerLookupFailed = false;
    if (userId) {
      try {
        dbRecord = await prisma.canvas.findUnique({
          where: {
            userId_boardId: {
              userId,
              boardId,
            },
          },
        });
      } catch (dbErr) {
        ownerLookupFailed = true;
        console.warn('Canvas: PostgreSQL query failed, falling back to memory cache:', dbErr);
      }
    }

    // If not found in current user's scope, allow public retrieval for shared links only if marked public
    if (!dbRecord) {
      try {
        dbRecord = await prisma.canvas.findFirst({
          where: {
            boardId,
            isPublic: true,
          },
        });
      } catch (dbErr) {
        console.warn('Canvas: PostgreSQL global board lookup failed:', dbErr);
      }
    }

    if (dbRecord) {
      const payload: CanvasStatePayload = {
        nodes: (dbRecord.nodes as any) || [],
        edges: (dbRecord.edges as any) || [],
        viewport: (dbRecord.viewport as any) || undefined,
      };

      // Public readers must re-check sharing on every request; never cache their access.
      if (userId && dbRecord.userId === userId) {
        memoryCache[cacheKey] = {
          title: dbRecord.title,
          updatedAt: dbRecord.updatedAt.toISOString(),
          payload,
        };
      }

      return NextResponse.json({
        id: dbRecord.boardId,
        title: dbRecord.title,
        updatedAt: dbRecord.updatedAt.toISOString(),
        ...payload,
      });
    }

    // Check memory cache strictly for active user
    const cachedEntry = userId && ownerLookupFailed ? memoryCache[cacheKey] : undefined;

    if (cachedEntry) {
      return NextResponse.json({
        id: boardId,
        title: cachedEntry.title,
        updatedAt: cachedEntry.updatedAt,
        ...cachedEntry.payload,
      });
    }

    // Board not found in database or memory cache
    return NextResponse.json(
      { error: 'Canvas board not found.' },
      { status: 404 }
    );
  } catch (error: any) {
    console.error('Error in GET /api/canvas:', error);
    return NextResponse.json(
      { error: 'Failed to retrieve canvas state.' },
      { status: 500 }
    );
  }
}

export async function POST(req: Request) {
  try {
    const userId = await getSafeUserId(req);
    if (!userId) {
      return NextResponse.json({ error: 'Unauthorized. Sign in required to save canvas boards.' }, { status: 401 });
    }

    const body = await req.json();
    const { id = 'default', title = 'Untitled Canvas', nodes = [], edges = [], viewport, isPublic } = body;

    const cacheKey = `${userId}_${id}`;
    const nowIso = new Date().toISOString();

    const cleanNodes = Array.isArray(nodes) ? nodes : [];
    const cleanEdges = Array.isArray(edges) ? edges : [];

    // In-memory update
    memoryCache[cacheKey] = {
      title,
      updatedAt: nowIso,
      payload: { nodes: cleanNodes, edges: cleanEdges, viewport },
    };

    // Update in-memory index
    const index = memoryIndexCache[userId] || [];
    const metaItem: CanvasBoardMetadata = {
      id,
      title,
      updatedAt: nowIso,
      nodeCount: cleanNodes.length,
    };
    const existingIdx = index.findIndex((b) => b.id === id);
    if (existingIdx >= 0) {
      index[existingIdx] = metaItem;
    } else {
      index.unshift(metaItem);
    }
    memoryIndexCache[userId] = index;

    // Persist directly to PostgreSQL database
    try {
      const saved = await prisma.canvas.upsert({
        where: {
          userId_boardId: {
            userId,
            boardId: id,
          },
        },
        update: {
          title,
          nodes: cleanNodes,
          edges: cleanEdges,
          viewport: viewport || undefined,
          ...(typeof isPublic === 'boolean' ? { isPublic } : {}),
        },
        create: {
          userId,
          boardId: id,
          title,
          nodes: cleanNodes,
          edges: cleanEdges,
          viewport: viewport || undefined,
          isPublic: Boolean(isPublic),
        },
      });

      return NextResponse.json({
        success: true,
        id: saved.boardId,
        title: saved.title,
        updatedAt: saved.updatedAt.toISOString(),
      });
    } catch (dbErr) {
      console.error('Canvas: PostgreSQL upsert error (in-memory cached):', dbErr);
    }

    return NextResponse.json({ success: true, id, title, updatedAt: nowIso });
  } catch (error: any) {
    console.error('Error in POST /api/canvas:', error);
    return NextResponse.json(
      { error: 'Failed to persist canvas state.' },
      { status: 500 }
    );
  }
}

export async function DELETE(req: Request) {
  try {
    const userId = await getSafeUserId(req);
    if (!userId) {
      return NextResponse.json({ error: 'Authentication required to delete canvas.' }, { status: 401 });
    }

    const url = new URL(req.url);
    const id = url.searchParams.get('id');
    if (!id) {
      return NextResponse.json({ error: 'Board ID is required.' }, { status: 400 });
    }

    const cacheKey = `${userId}_${id}`;
    delete memoryCache[cacheKey];

    if (memoryIndexCache[userId]) {
      memoryIndexCache[userId] = memoryIndexCache[userId].filter((b) => b.id !== id);
    }

    // Delete from PostgreSQL database enforcing ownership
    try {
      const result = await prisma.canvas.deleteMany({
        where: {
          userId,
          boardId: id,
        },
      });
      if (result.count === 0) {
        return NextResponse.json({ error: 'Canvas board not found or unauthorized.' }, { status: 404 });
      }
    } catch (dbErr) {
      console.error('Canvas: PostgreSQL delete error:', dbErr);
    }

    return NextResponse.json({ success: true, deletedId: id });
  } catch (error: any) {
    console.error('Error in DELETE /api/canvas:', error);
    return NextResponse.json(
      { error: 'Failed to delete canvas board.' },
      { status: 500 }
    );
  }
}

export async function PATCH(req: Request) {
  try {
    const userId = await getSafeUserId(req);
    if (!userId) {
      return NextResponse.json(
        { error: 'Authentication required to update canvas sharing settings.' },
        { status: 401 }
      );
    }

    const body = await req.json();
    const { id, isPublic } = body;
    if (typeof id !== 'string' || !id.trim() || typeof isPublic !== 'boolean') {
      return NextResponse.json({ error: 'Board ID and boolean isPublic are required.' }, { status: 400 });
    }

    const updated = await prisma.canvas.updateMany({
      where: { userId, boardId: id },
      data: { isPublic: Boolean(isPublic) },
    });

    if (updated.count === 0) {
      return NextResponse.json(
        { error: 'Canvas board not found or unauthorized.' },
        { status: 404 }
      );
    }

    return NextResponse.json({ success: true, id, isPublic: Boolean(isPublic) });
  } catch (error: any) {
    console.error('Error in PATCH /api/canvas:', error);
    return NextResponse.json(
      { error: 'Failed to update canvas sharing.' },
      { status: 500 }
    );
  }
}

