import { NextResponse } from 'next/server';
import { auth } from '@clerk/nextjs/server';
import prisma from '@/lib/prisma';
import { recordAnalyticsEvent } from '@/lib/analyticsService';

import { findCanonicalBook } from '@/lib/bibleCanon';

export async function GET(request: Request) {
  const { userId } = await auth();
  if (!userId) {
    return new NextResponse('Unauthorized', { status: 401 });
  }

  const { searchParams } = new URL(request.url);
  const book = searchParams.get('book');
  const chapter = searchParams.get('chapter');

  try {
    const where: any = { userId };
    if (book) {
      const bookMeta = findCanonicalBook(book);
      const possibleBooks = bookMeta 
        ? Array.from(new Set([book, bookMeta.name, bookMeta.code, ...bookMeta.aliases]))
        : [book];
      where.OR = possibleBooks.map(b => ({
        book: {
          equals: b,
          mode: 'insensitive',
        }
      }));
    }
    if (chapter) {
      where.chapter = parseInt(chapter, 10);
    }

    const highlights = await prisma.highlight.findMany({
      where,
      orderBy: { createdAt: 'asc' }
    });
    return NextResponse.json(highlights);
  } catch (error) {
    console.error('Failed to fetch highlights:', error);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

export async function POST(request: Request) {
  const { userId } = await auth();
  if (!userId) {
    return new NextResponse('Unauthorized', { status: 401 });
  }

  try {
    const body = await request.json();
    const { book, chapter, verse, text, color } = body;

    if (!book || !chapter || !verse || !color) {
      return NextResponse.json({ error: 'Missing required fields' }, { status: 400 });
    }

    const numChapter = parseInt(chapter, 10);
    const numVerse = parseInt(verse, 10);
    const bookMeta = findCanonicalBook(book);
    const bookNames = bookMeta 
      ? Array.from(new Set([book, bookMeta.name, bookMeta.code, ...bookMeta.aliases]))
      : [book];

    // Find any existing highlights for this user on the same book, chapter, and verse
    const existing = await prisma.highlight.findMany({
      where: {
        userId,
        chapter: numChapter,
        verse: numVerse,
        OR: bookNames.map(b => ({
          book: { equals: b, mode: 'insensitive' }
        }))
      }
    });

    const newNorm = (text || '').toLowerCase().trim();

    // Clean up any existing highlights that are identical (same text) so color updates cleanly
    const toDeleteIds: number[] = [];
    for (const ex of existing) {
      const exNorm = (ex.text || '').toLowerCase().trim();
      if (exNorm === newNorm) {
        toDeleteIds.push(ex.id);
      }
    }

    if (toDeleteIds.length > 0) {
      await prisma.highlight.deleteMany({
        where: { id: { in: toDeleteIds } }
      });
    }

    const highlight = await prisma.highlight.create({
      data: {
        userId,
        book,
        chapter: numChapter,
        verse: numVerse,
        text: text || '',
        color
      }
    });

    recordAnalyticsEvent('highlight_created', userId, { feature: 'highlights', mode: color }).catch(() => {});

    return NextResponse.json(highlight, { status: 201 });
  } catch (error) {
    console.error('Failed to create highlight:', error);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

export async function DELETE(request: Request) {
  const { userId } = await auth();
  if (!userId) {
    return new NextResponse('Unauthorized', { status: 401 });
  }

  const { searchParams } = new URL(request.url);
  const id = searchParams.get('id');
  const ids = searchParams.get('ids');
  const book = searchParams.get('book');
  const chapter = searchParams.get('chapter');
  const verse = searchParams.get('verse');

  try {
    if (ids) {
      const idList = ids.split(',').map(s => parseInt(s.trim(), 10)).filter(n => !isNaN(n) && n > 0 && n <= 2147483647);
      if (idList.length > 0) {
        await prisma.highlight.deleteMany({
          where: {
            userId,
            id: { in: idList }
          }
        });
      }
      return NextResponse.json({ success: true });
    }

    if (id) {
      const parsedId = parseInt(id, 10);
      if (!isNaN(parsedId) && parsedId > 0 && parsedId <= 2147483647) {
        await prisma.highlight.deleteMany({
          where: {
            userId,
            id: parsedId
          }
        });
      }
      return NextResponse.json({ success: true });
    }

    if (book && chapter && verse) {
      const numChapter = parseInt(chapter, 10);
      const numVerse = parseInt(verse, 10);
      const bookMeta = findCanonicalBook(book);
      const possibleBooks = bookMeta 
        ? Array.from(new Set([book, bookMeta.name, bookMeta.code, ...bookMeta.aliases]))
        : [book];

      await prisma.highlight.deleteMany({
        where: {
          userId,
          chapter: numChapter,
          verse: numVerse,
          OR: possibleBooks.map(b => ({
            book: { equals: b, mode: 'insensitive' }
          }))
        }
      });
      return NextResponse.json({ success: true });
    }

    return NextResponse.json({ error: 'Missing criteria for deletion' }, { status: 400 });
  } catch (error) {
    console.error('Failed to delete highlights:', error);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

import { auth } from '@clerk/nextjs/server';
import { NextResponse } from 'next/server';
import prisma from '@/lib/prisma';
import { updateMemoryNote, deleteMemoryNote } from '@/lib/memoryNoteStore';

export async function PUT(req: Request, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  let userId: string | null = null;
  try {
    const authResult = await auth();
    userId = authResult?.userId || null;
  } catch {}

  const numId = parseInt(id, 10);
  if (!/^\d+$/.test(id) || !Number.isSafeInteger(numId) || numId < 1) {
    return NextResponse.json({ error: 'Invalid note ID' }, { status: 400 });
  }

  try {
    let body;
    try { body = await req.json(); } catch {
      return NextResponse.json({ error: 'Invalid JSON request body.' }, { status: 400 });
    }
    if (!body || typeof body !== 'object' || Array.isArray(body) ||
        (body.title !== undefined && typeof body.title !== 'string') ||
        (body.content !== undefined && typeof body.content !== 'string')) {
      return NextResponse.json({ error: 'Title and content must be strings.' }, { status: 400 });
    }
    const { title, content } = body;

    if (!userId) {
      return NextResponse.json({ error: 'Unauthorized. Sign in required to update notes.' }, { status: 401 });
    }

    if (process.env.DATABASE_URL && numId <= 2147483647) {
      try {
        const note = await prisma.note.update({
          where: { id: numId, userId },
          data: { title, content },
        });
        return NextResponse.json(note);
      } catch (dbErr: any) {
        if (dbErr?.code === 'P2025') {
          return NextResponse.json({ error: 'Note not found or unauthorized' }, { status: 404 });
        }
        console.error('Prisma updateNote error:', dbErr);
        return NextResponse.json({ error: 'Database update failed' }, { status: 500 });
      }
    }

    const updated = updateMemoryNote(userId, numId, { title, content });
    if (updated) {
      return NextResponse.json(updated);
    }
    return NextResponse.json({ error: 'Note not found or unauthorized' }, { status: 404 });
  } catch (error) {
    console.error('Failed to update note:', error);
    return NextResponse.json({ error: 'Failed to update note' }, { status: 500 });
  }
}

export async function DELETE(req: Request, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  let userId: string | null = null;
  try {
    const authResult = await auth();
    userId = authResult?.userId || null;
  } catch {}

  const numId = parseInt(id, 10);
  if (!/^\d+$/.test(id) || !Number.isSafeInteger(numId) || numId < 1) {
    return NextResponse.json({ error: 'Invalid note ID' }, { status: 400 });
  }

  try {
    if (!userId) {
      return NextResponse.json({ error: 'Unauthorized. Sign in required to delete notes.' }, { status: 401 });
    }

    if (process.env.DATABASE_URL && numId <= 2147483647) {
      try {
        await prisma.note.delete({
