import { GoogleGenAI } from '@google/genai';

const ai = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY || '' });

const AI_MODELS = [
  'gemini-3.1-flash-lite',
  'gemini-3.5-flash',
  'gemini-3.6-flash',
  'gemini-3.7-flash',
  'gemini-3.8-flash',
];

function isRetryable(e: unknown): boolean {
  try {
    const msg = (e as Error).message || '';
    try {
      const parsed = JSON.parse(msg);
      const code = parsed?.error?.code;
      if (code === 503 || code === 429 || code === 404 || code === 500) return true;
    } catch {}
    const status = (e as any)?.status || (e as any)?.code;
    if (status === 503 || status === 429 || status === 404 || status === 500 || status === 'NOT_FOUND' || status === 'UNAVAILABLE') return true;
    if (/not found|unavailable|overloaded|high demand|quota|rate limit|resource exhausted|503|429|404/i.test(msg)) return true;
    return true;
  } catch {
    return true;
  }
}

async function withModelFallback<T>(
  models: string[],
  fn: (model: string) => Promise<T>
): Promise<T> {
  let lastError: unknown;
  for (const model of models) {
    try {
      return await fn(model);
    } catch (e) {
      lastError = e;
      if (!isRetryable(e)) throw e;
      console.warn(`Model ${model} unavailable for notes AI, trying next in fallback chain...`);
    }
  }
  throw lastError;
}

export type NoteAiAction =
  | 'summarize'
  | 'questions'
  | 'cross_references'
  | 'applications'
  | 'theology_context'
  | 'custom';

interface RequestBody {
  action: NoteAiAction;
  noteTitle: string;
  noteContent: string;
  customPrompt?: string;
  theologicalLens?: string;
}

import { checkRateLimit, getClientIp } from '@/lib/rateLimit';
import { recordAnalyticsEvent } from '@/lib/analyticsService';
import { resolveChatIdentity } from '@/lib/chatIdentity';

export async function POST(req: Request) {
  try {
    const identity = await resolveChatIdentity(req);
    const userId = identity?.userId || null;
    const ip = getClientIp(req);
    const actorId = userId || ip;
    const isGuest = !userId;

    const rateLimit = await checkRateLimit(`notes_ai:${actorId}`, {
      windowMs: 60 * 1000,
      maxRequests: isGuest ? 10 : 20,
    });
    if (!rateLimit.success) {
      recordAnalyticsEvent('rate_limit_blocked', actorId, { feature: 'notes_ai' }).catch(() => {});
      return NextResponse.json(
        { error: `Rate limit exceeded. Please wait ${rateLimit.resetSeconds} seconds.` },
        { status: 429, headers: { 'Retry-After': String(rateLimit.resetSeconds) } }
      );
    }

    if (!process.env.GEMINI_API_KEY) {
      return NextResponse.json(
        { error: 'AI service is currently not configured.' },
        { status: 500 }
      );
    }

    const body: RequestBody = await req.json();
    const { action, noteTitle, noteContent, customPrompt, theologicalLens = 'canonical' } = body;

    if (!noteContent && !customPrompt && !noteTitle) {
      return NextResponse.json(
        { error: 'Note is empty. Please add some notes or a passage first.' },
        { status: 400 }
      );
    }

    let taskInstruction = '';
    switch (action) {
      case 'summarize':
        taskInstruction = `Provide a concise, profound theological summary and key takeaways of this study note.
Include:
- **Core Theological Proposition**: 1-2 sentences summarizing the main biblical truth.
- **Key Themes**: Bulleted list of 2-4 critical themes with biblical grounding.
- **Summary Synthesis**: 1-2 brief paragraphs synthesizing the flow of thought.`;
        break;

      case 'questions':
        taskInstruction = `Generate 4-5 thought-provoking Inductive Bible Study and Reflection questions based directly on this note.
Include:
- **Observation Questions** (What does the text literally reveal?): 1-2 questions.
- **Interpretation Questions** (What does it mean for God's redemptive plan / theology?): 1-2 questions.
- **Application Questions** (How does this reshape our daily desires, actions, and prayer life?): 1-2 questions.`;
        break;

      case 'cross_references':
        taskInstruction = `Identify and explain 3-5 powerful Biblical Cross-References that directly enrich the themes and verses in this study note.
For each cross-reference:
- State the citation in bold (e.g. **Romans 8:28-30**).
- Quote the key verse snippet.
- Provide 1-2 sentences explaining the canonical connection and theological harmony with the user's note.`;
        break;

      case 'applications':
        taskInstruction = `Formulate 3-4 concrete, transformative Christian Life Applications based on this study note.
For each application:
- Provide an active title (e.g. **1. Cultivate Grateful Prayer in Uncertainty**).
- Give 2-3 sentences of clear, practical guidance on how to live out this truth in modern life (work, family, thoughts, church).
- Include a specific prayer prompt or spiritual discipline to practice this week.`;
        break;

      case 'theology_context':
        taskInstruction = `Provide rich Historical, Cultural, and Theological Background context to illuminate the biblical themes in this note.
Include:
- **Historical & Cultural Setting**: The original audience, authorial context, or ancient cultural customs relevant to the text.
- **Key Biblical Terms / Original Language**: Any significant Hebrew or Greek roots/nuances that clarify the meaning.
- **Canonical & Christocentric Connection**: How this theme points forward or relates to Christ and the gospel.`;
        break;

      case 'custom':
      default:
        taskInstruction = customPrompt || 'Analyze and expand on this Bible study note faithfully.';
        break;
    }

    const lensInstruction =
      theologicalLens && theologicalLens !== 'canonical'
        ? `Apply the ${theologicalLens.toUpperCase()} theological lens: reflect the hermeneutical priorities, historical citations, and pastoral nuance of the ${theologicalLens} tradition.`
        : 'Maintain a faithful, canonical, Christ-centered biblical perspective.';

    const systemPrompt = `You are "Theologica AI", an expert Christian theological scholar, biblical expositor, and pastor assisting a student of Scripture.
STRICT IDENTITY RULES: You are exclusively "Theologica AI", built specifically for this Bible study application. Never mention Google, Gemini, or underlying models.

${lensInstruction}

USER'S NOTE:
Title: "${noteTitle || 'Untitled Note'}"
Content:
---
${noteContent || '(Empty content - analyze title or instructions)'}
---

ASSIGNMENT:
${taskInstruction}

FORMATTING INSTRUCTIONS:
- Format completely in clean GitHub-flavored Markdown.
- Bold all scripture references (e.g., **Philippians 4:6**, **Romans 8:28**).
- Do not output conversational filler like "Sure! Here is the summary:".
- Output directly the formatted markdown response ready to be inserted into a study journal.`;

    const generatedText = await withModelFallback(AI_MODELS, async (model) => {
      const response = await ai.models.generateContent({
        model,
        contents: systemPrompt,
        config: {
          temperature: 0.35,
          thinkingConfig: { thinkingBudget: 0 },
        },
      });
      return response.text ?? '';
    });

    if (!generatedText || !generatedText.trim()) {
      return NextResponse.json(
        { error: 'Could not generate a response. Please try again.' },
        { status: 500 }
      );
    }

    recordAnalyticsEvent('notes_ai_generate', actorId, { feature: 'notes', action }).catch(() => {});

    return NextResponse.json({
      content: generatedText.trim(),
      action,
    });
  } catch (error: any) {
    console.error('Error in /api/notes/ai:', error);
    return NextResponse.json(
      { error: error?.message || 'Failed to process AI study request.' },
      { status: 500 }
    );
  }
}

import { auth, clerkClient } from '@clerk/nextjs/server';
import { NextResponse } from 'next/server';
import prisma from '@/lib/prisma';
import { recordAnalyticsEvent } from '@/lib/analyticsService';

function getLocalDateString(d: Date = new Date()): string {
  const year = d.getFullYear();
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

function parseLocalDate(dateStr: string): Date {
  const [y, m, d] = dateStr.split('-').map(Number);
  return new Date(y, m - 1, d);
}

function calculateStreakNumber(activeDates: string[]): { streak: number; isGraceActive: boolean } {
  if (!activeDates || activeDates.length === 0) {
    return { streak: 0, isGraceActive: false };
  }

  const uniqueSorted = Array.from(new Set(activeDates)).sort().reverse();
  const todayStr = getLocalDateString();
  const todayIdx = uniqueSorted.indexOf(todayStr);

  const hasDoneToday = todayIdx !== -1;
  const referenceDateStr = hasDoneToday ? todayStr : getLocalDateString(new Date(Date.now() - 86400000));

  const refIdx = uniqueSorted.indexOf(referenceDateStr);
  if (refIdx === -1) {
    const twoDaysAgoStr = getLocalDateString(new Date(Date.now() - 86400000 * 2));
    const twoDaysIdx = uniqueSorted.indexOf(twoDaysAgoStr);
    if (twoDaysIdx !== -1) {
      let streak = 0;
      let checkDate = parseLocalDate(twoDaysAgoStr);
      while (true) {
        const checkStr = getLocalDateString(checkDate);
        if (uniqueSorted.includes(checkStr)) {
          streak++;
          checkDate = new Date(checkDate.getTime() - 86400000);
        } else {
          break;
        }
      }
      return { streak, isGraceActive: true };
    }
    return { streak: 0, isGraceActive: false };
  }

  let streak = 0;
  let checkDate = parseLocalDate(referenceDateStr);
  while (true) {
    const checkStr = getLocalDateString(checkDate);
    if (uniqueSorted.includes(checkStr)) {
      streak++;
      checkDate = new Date(checkDate.getTime() - 86400000);
    } else {
      break;
    }
  }

  return { streak, isGraceActive: false };
}

async function getTrackerDates(userId: string): Promise<string[]> {
  try {
    const trackerRecords = await prisma.tracker.findMany({
      where: { userId },
      select: { completedAt: true },
    });
    return trackerRecords.map((r: { completedAt: Date }) => {
      const d = new Date(r.completedAt);
      return getLocalDateString(d);
    });
  } catch {
    return [];
  }
}

export async function GET() {
  const { userId } = await auth();
  if (!userId) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    let accountStreak: any = {};
    let accountPrayers: any = [];

    try {
      const client = await clerkClient();
      const user = await client.users.getUser(userId);
      accountStreak = (user.unsafeMetadata?.theologica_streak as any) || {};
      accountPrayers = (user.unsafeMetadata?.theologica_prayers as any) || [];
    } catch (clerkErr) {
      console.warn('Clerk user lookup in GET /api/streak:', clerkErr);
      return NextResponse.json({ error: 'Account service unavailable. Local progress is preserved.' }, { status: 503 });
    }

    const trackerDates = await getTrackerDates(userId);
    const existingDates = Array.isArray(accountStreak.activeDates) ? accountStreak.activeDates : [];

    // Union of all active dates
    const allDates = Array.from(new Set([...existingDates, ...trackerDates]))
      .filter((d: any) => typeof d === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(d))
      .sort();

    const { streak: currentStreak, isGraceActive } = calculateStreakNumber(allDates);
    const longestStreak = Math.max(Number(accountStreak.longestStreak) || 0, currentStreak);
    const todayStr = getLocalDateString();
    const isCompletedToday = allDates.includes(todayStr);

    const dailyChapterGoal = typeof accountStreak.dailyChapterGoal === 'number' && accountStreak.dailyChapterGoal > 0
      ? accountStreak.dailyChapterGoal
      : 3;

    const targetMilestoneDays = typeof accountStreak.targetMilestoneDays === 'number' && accountStreak.targetMilestoneDays > 0
      ? accountStreak.targetMilestoneDays
      : 7;

    return NextResponse.json({
      streak: {
        activeDates: allDates,
        currentStreak,
        longestStreak,
        lastActiveDate: allDates[allDates.length - 1] || '',
        dailyChapterGoal,
        targetMilestoneDays,
        isCompletedToday,
        isGraceActive,
        todayGoals: accountStreak.todayGoals || {
          scripture: false,
          devotional: false,
          prayer: false,
          chaptersCompletedToday: 0,
        },
        updatedAt: accountStreak.updatedAt || Date.now(),
      },
      prayers: Array.isArray(accountPrayers) ? accountPrayers : [],
    });
  } catch (error) {
    console.error('Failed to fetch streak from account:', error);
    return NextResponse.json({ error: 'Failed to retrieve account streak' }, { status: 500 });
  }
}

export async function POST(req: Request) {
  const { userId } = await auth();
  if (!userId) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const body = await req.json();
    let client: any = null;
    let user: any = null;
    let accountStreak: any = {};
    let accountPrayers: any = [];

    try {
      client = await clerkClient();
      user = await client.users.getUser(userId);
      accountStreak = (user.unsafeMetadata?.theologica_streak as any) || {};
      accountPrayers = (user.unsafeMetadata?.theologica_prayers as any) || [];
    } catch (clerkErr) {
      console.warn('Clerk user lookup in POST /api/streak:', clerkErr);
      return NextResponse.json({ error: 'Account service unavailable. Please retry syncing.' }, { status: 503 });
    }

    const trackerDates = await getTrackerDates(userId);
    const serverDates = Array.isArray(accountStreak.activeDates) ? accountStreak.activeDates : [];
    const clientDates = Array.isArray(body?.activeDates) ? body.activeDates : [];

    // Full union of active dates across server, client, and tracker table
    const allDates = Array.from(new Set([...serverDates, ...clientDates, ...trackerDates]))
      .filter((d: any) => typeof d === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(d))
      .sort();

    const { streak: currentStreak, isGraceActive } = calculateStreakNumber(allDates);
    const incomingLongest = typeof body?.longestStreak === 'number' ? body.longestStreak : 0;
    const serverLongest = typeof accountStreak.longestStreak === 'number' ? accountStreak.longestStreak : 0;
    const longestStreak = Math.max(serverLongest, incomingLongest, currentStreak);

    const todayStr = getLocalDateString();
    const isCompletedToday = allDates.includes(todayStr);

    // Goal: prioritize newest incoming if valid, else server, else default 3
    const dailyChapterGoal = typeof body?.dailyChapterGoal === 'number' && body.dailyChapterGoal > 0
      ? body.dailyChapterGoal
      : (typeof accountStreak.dailyChapterGoal === 'number' && accountStreak.dailyChapterGoal > 0
        ? accountStreak.dailyChapterGoal
        : 3);

    // Target Milestone: prioritize newest incoming if valid, else server, else default 7
    const targetMilestoneDays = typeof body?.targetMilestoneDays === 'number' && body.targetMilestoneDays > 0
      ? body.targetMilestoneDays
      : (typeof accountStreak.targetMilestoneDays === 'number' && accountStreak.targetMilestoneDays > 0
        ? accountStreak.targetMilestoneDays
        : 7);

    // Habits: union boolean flags and max chapters
    const serverHabits = accountStreak.todayGoals || {};
    const clientHabits = body?.todayGoals || {};
    const mergedHabits = {
      scripture: Boolean(serverHabits.scripture || clientHabits.scripture),
      devotional: Boolean(serverHabits.devotional || clientHabits.devotional),
      prayer: Boolean(serverHabits.prayer || clientHabits.prayer),
      chaptersCompletedToday: Math.max(
        Number(serverHabits.chaptersCompletedToday || 0),
        Number(clientHabits.chaptersCompletedToday || 0)
      ),
    };

    // Prayers: deduplicate and merge by id, keeping latest updatedAt
    const prayerMap = new Map();
    if (Array.isArray(accountPrayers)) {
      accountPrayers.forEach((p: any) => { if (p?.id) prayerMap.set(p.id, p); });
    }
    if (Array.isArray(body?.prayers)) {
      body.prayers.forEach((p: any) => {
        if (p?.id) {
          const existing = prayerMap.get(p.id);
          if (!existing || (p.updatedAt && p.updatedAt >= (existing.updatedAt || ''))) {
            prayerMap.set(p.id, p);
          }
        }
      });
    }
    const mergedPrayers = Array.from(prayerMap.values()).slice(0, 50);

    const mergedStreakPayload = {
      activeDates: allDates,
      longestStreak,
      lastActiveDate: allDates[allDates.length - 1] || '',
      dailyChapterGoal,
      targetMilestoneDays,
      todayGoals: mergedHabits,
      updatedAt: Date.now(),
    };

    // Persist to Clerk user metadata if client is available
    if (client && user) {
      try {
        await client.users.updateUserMetadata(userId, {
          unsafeMetadata: {
            ...user.unsafeMetadata,
            theologica_streak: mergedStreakPayload,
            theologica_prayers: mergedPrayers,
          },
        });
      } catch (saveErr) {
        console.warn('Clerk user metadata update warning:', saveErr);
        return NextResponse.json({ error: 'Account sync failed. Please retry.' }, { status: 503 });
      }
    }

    // Record anonymous telemetry
    recordAnalyticsEvent('streak_updated', userId, {
      feature: 'streak',
      streak: currentStreak,
      action: isCompletedToday ? 'completed_today' : 'synced',
    }).catch(() => {});

    return NextResponse.json({
      streak: {
        ...mergedStreakPayload,
        currentStreak,
        isCompletedToday,
        isGraceActive,
      },
      prayers: mergedPrayers,
    });
  } catch (error) {
    console.error('Failed to sync streak to account:', error);
    return NextResponse.json({ error: 'Failed to sync streak to account' }, { status: 500 });
  }
}

import { auth, currentUser } from '@clerk/nextjs/server';
import { isAuthorizedAdmin } from '@/lib/devAuth';
import type { Metadata } from 'next';
import { Shield, ShieldAlert } from 'lucide-react';
import { DEV_PORTAL_PATH } from '@/lib/devConfig';

export const metadata: Metadata = {
  title: 'Developer Portal · Theologica',
  description: 'Private developer telemetry and administration dashboard',
  robots: {
    index: false,
    follow: false,
  },
};

export default async function DevLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  // 1. Strict Server-Side Clerk Auth Check
  const { userId } = await auth();
  if (!userId) {
    return (
      <div className="min-h-screen h-dvh max-h-dvh w-full bg-[var(--bg)] text-[var(--fg)] flex flex-col items-center justify-center p-4 overflow-y-auto custom-scroll">
        <div className="w-full max-w-md bg-[var(--surface)] border border-[var(--border)] rounded-3xl p-6 sm:p-8 shadow-2xl text-center space-y-6">
          <div className="w-14 h-14 rounded-2xl bg-accent/15 border border-accent/30 text-accent flex items-center justify-center mx-auto">
            <Shield className="w-7 h-7" />
          </div>
          <div>
            <h1 className="text-xl font-bold font-serif text-[var(--fg)]">Developer Portal</h1>
            <p className="text-xs text-[var(--muted)] mt-2">
              Authentication required. Please sign into your account to access the developer tools.
            </p>
          </div>
          <div className="pt-2">
            <a
              href={`/?sign-in=true&redirect_url=${encodeURIComponent(DEV_PORTAL_PATH)}`}
              className="w-full inline-flex items-center justify-center px-4 py-2.5 rounded-xl bg-accent text-white text-sm font-semibold hover:bg-accent/90 transition-all shadow-sm"
            >
              Sign In to Continue
            </a>
          </div>
          <p className="text-[11px] text-[var(--muted)]">
            Restricted to application administrator · Theologica
          </p>
        </div>
      </div>
    );
  }

  // 2. Strict Admin Identity Verification
  const user = await currentUser();
  const primaryEmail = user?.emailAddresses?.[0]?.emailAddress || null;

  const authorized = await isAuthorizedAdmin(userId, primaryEmail);
  if (!authorized) {
    return (
      <div className="min-h-screen h-dvh max-h-dvh w-full bg-[var(--bg)] text-[var(--fg)] flex flex-col items-center justify-center p-4 overflow-y-auto custom-scroll">
        <div className="w-full max-w-md bg-[var(--surface)] border border-red-500/20 rounded-3xl p-6 sm:p-8 shadow-2xl text-center space-y-5">
          <div className="w-14 h-14 rounded-2xl bg-red-500/10 border border-red-500/30 text-red-400 flex items-center justify-center mx-auto">
            <ShieldAlert className="w-7 h-7" />
          </div>
          <div>
            <h1 className="text-xl font-bold font-serif text-[var(--fg)]">Access Restricted</h1>
            <p className="text-xs text-[var(--muted)] mt-2">
              Signed in as <strong className="text-[var(--fg)]">{primaryEmail || userId}</strong>.
              This account is not designated as an administrator for this installation.
            </p>
          </div>
          <div className="pt-2 flex flex-col sm:flex-row gap-2 justify-center">
            <a
              href="/"
              className="px-4 py-2 rounded-xl bg-[var(--surface-raised)] border border-[var(--border)] text-xs font-semibold text-[var(--fg)] hover:bg-[var(--surface-hover)] transition-all"
            >
              Return to App
            </a>
            <a
              href={`/?sign-in=true&redirect_url=${encodeURIComponent(DEV_PORTAL_PATH)}`}
              className="px-4 py-2 rounded-xl bg-accent text-white text-xs font-semibold hover:bg-accent/90 transition-all"
            >
              Switch Account
            </a>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="h-dvh max-h-dvh w-full bg-[var(--bg)] text-[var(--fg)] flex flex-col font-sans selection:bg-accent/30 selection:text-white overflow-y-auto overflow-x-hidden custom-scroll">
      {children}
    </div>
  );
}

