"use client";

import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Target, 
  X, 
  Sparkles, 
  Calendar, 
  Clock, 
  Check, 
  TrendingUp, 
  BookOpen, 
  Plus, 
  Minus,
  Award
} from 'lucide-react';

export interface EditPaceModalProps {
  isOpen: boolean;
  currentGoal: number;
  totalChaptersCompleted: number;
  onSave: (newGoal: number) => void;
  onClose: () => void;
}

interface PacePreset {
  chapters: number;
  title: string;
  badge?: string;
  description: string;
  approxDays: number;
  approxYears: string;
}

const PACE_PRESETS: PacePreset[] = [
  {
    chapters: 1,
    title: '1 Chapter a day',
    description: 'A relaxed pace to read through Scripture at your own speed',
    approxDays: 1189,
    approxYears: '~3.3 years',
  },
  {
    chapters: 2,
    title: '2 Chapters a day',
    description: 'Steady daily reading with good time to reflect',
    approxDays: 595,
    approxYears: '~1.6 years',
  },
  {
    chapters: 3,
    title: '3 Chapters a day',
    badge: 'Popular',
    description: 'Read through the entire Bible in about one year',
    approxDays: 396,
    approxYears: '~1.0 year',
  },
  {
    chapters: 4,
    title: '4 Chapters a day',
    description: 'A quicker pace covering more ground each day',
    approxDays: 297,
    approxYears: '~10 months',
  },
  {
    chapters: 5,
    title: '5 Chapters a day',
    description: 'Finish the Bible in under 8 months',
    approxDays: 238,
    approxYears: '~8 months',
  },
];

export function EditPaceModal({
  isOpen,
  currentGoal,
  totalChaptersCompleted,
  onSave,
  onClose,
}: EditPaceModalProps) {
  const [selectedGoal, setSelectedGoal] = useState<number>(currentGoal || 3);
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);
  const [isCustom, setIsCustom] = useState<boolean>(
    !PACE_PRESETS.some(p => p.chapters === currentGoal)
  );

  useEffect(() => {
    if (isOpen) {
      setSelectedGoal(currentGoal || 3);
      setIsCustom(!PACE_PRESETS.some(p => p.chapters === currentGoal));
    }
  }, [isOpen, currentGoal]);

  if (!isOpen) return null;

  const totalBibleChapters = 1189;
  const remainingChapters = Math.max(0, totalBibleChapters - totalChaptersCompleted);
  const effectiveGoal = Math.max(1, selectedGoal);
  const daysToFinish = Math.max(1, Math.ceil(remainingChapters / effectiveGoal));

  // Compute estimated finish date
  const projectedFinishDate = new Date();
  projectedFinishDate.setDate(projectedFinishDate.getDate() + daysToFinish);
  const finishDateStr = projectedFinishDate.toLocaleDateString(undefined, {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
  });

  const estMinutesPerDay = `${effectiveGoal * 4}–${effectiveGoal * 5}`;
  const overallPercent = Math.min(100, Math.round((totalChaptersCompleted / totalBibleChapters) * 100));

  const handleSelectPreset = (chapters: number) => {
    setSelectedGoal(chapters);
    setIsCustom(false);
  };

  const handleCustomIncrement = (delta: number) => {
    const next = Math.max(1, Math.min(50, selectedGoal + delta));
    setSelectedGoal(next);
    setIsCustom(!PACE_PRESETS.some(p => p.chapters === next));
  };

  const handleSave = () => {
    onSave(effectiveGoal);
    onClose();
  };

  if (!isOpen || !mounted || typeof document === 'undefined') return null;

  return createPortal(
    <AnimatePresence>
      <div 
        className="fixed inset-0 z-[110] flex items-center justify-center modal-safe-overlay bg-black/60 backdrop-blur-sm"
        onClick={onClose}
      >
        <motion.div
          initial={{ opacity: 0, scale: 0.95, y: 12 }}
          animate={{ opacity: 1, scale: 1, y: 0 }}
          exit={{ opacity: 0, scale: 0.95, y: 12 }}
          transition={{ duration: 0.2, ease: "easeOut" }}
          onClick={(e) => e.stopPropagation()}
          className="w-full max-w-xl bg-surface border border-border/80 rounded-3xl shadow-2xl overflow-hidden ring-1 ring-black/10 flex flex-col modal-safe-content"
        >
          {/* Header */}
          <div className="flex items-center justify-between p-5 sm:p-6 border-b border-border/70 shrink-0 bg-surface">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-2xl bg-accent/15 text-accent border border-accent/25 flex items-center justify-center shadow-xs">
                <Target size={22} />
              </div>
              <div>
                <div className="flex items-center gap-2">
                  <h2 className="text-lg sm:text-xl font-display font-bold text-fg tracking-tight">
                    Reading Pace &amp; Goals
                  </h2>
                  <span className="text-[10px] font-bold uppercase tracking-wider px-2 py-0.5 rounded-full bg-accent/10 text-accent border border-accent/20">
                    Daily Goal
                  </span>
                </div>
                <p className="text-xs text-muted mt-0.5">
                  Choose how many chapters you want to read each day.
                </p>
              </div>
            </div>

            <button
              type="button"
              onClick={onClose}
              className="p-1.5 rounded-xl text-muted hover:text-fg hover:bg-surface-warm transition-colors cursor-pointer"
              title="Close modal"
              aria-label="Close"
            >
              <X size={18} />
            </button>
          </div>

          {/* Modal Body */}
          <div className="flex-1 overflow-y-auto custom-scroll p-5 sm:p-6 space-y-6">
            {/* Presets List */}
            <div className="space-y-2.5">
              <label className="text-[11px] font-bold uppercase tracking-wider text-muted block">
                Choose Your Daily Goal
              </label>

              <div className="space-y-2">
                {PACE_PRESETS.map((preset) => {
                  const isSelected = !isCustom && selectedGoal === preset.chapters;
                  return (
                    <button
                      key={preset.chapters}
                      type="button"
                      onClick={() => handleSelectPreset(preset.chapters)}
                      className={`w-full text-left p-3.5 sm:p-4 rounded-2xl border transition-all cursor-pointer flex items-center justify-between gap-3 ${
                        isSelected
                          ? 'bg-accent/10 border-accent/60 ring-2 ring-accent/20 text-fg shadow-xs'
                          : 'bg-bg/60 hover:bg-surface-warm border-border/70 text-fg-2 hover:text-fg'
                      }`}
                    >
                      <div className="flex items-center gap-3 min-w-0">
                        <div className={`w-5 h-5 rounded-full border flex items-center justify-center shrink-0 transition-colors ${
                          isSelected
                            ? 'bg-accent border-accent text-accent-on'
                            : 'border-border-soft bg-surface'
                        }`}>
                          {isSelected && <Check size={12} strokeWidth={3} />}
                        </div>

                        <div className="space-y-0.5 min-w-0">
                          <div className="flex items-center gap-2 flex-wrap">
                            <span className="text-sm font-bold text-fg">
                              {preset.title}
                            </span>
                            {preset.badge && (
                              <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-amber-500/20 text-amber-500 border border-amber-500/30 flex items-center gap-1 shrink-0">
                                <Sparkles size={10} />
                                {preset.badge}
                              </span>
                            )}
                          </div>
                          <p className="text-xs text-muted leading-relaxed mt-0.5 whitespace-normal break-words">
                            {preset.description}
                          </p>
                        </div>
                      </div>

                      <div className="text-right shrink-0">
                        <span className="text-xs font-bold text-accent">
                          {preset.approxYears}
                        </span>
                        <span className="block text-[10px] text-muted">
                          (~{preset.approxDays} days)
                        </span>
                      </div>
                    </button>
                  );
                })}
              </div>

              {/* Custom Pace Option */}
              <div className={`mt-3 p-3.5 sm:p-4 rounded-2xl border transition-all ${
                isCustom 
                  ? 'bg-accent/10 border-accent/60 ring-2 ring-accent/20' 
                  : 'bg-bg/60 border-border/70'
              }`}>
                <div className="flex items-center justify-between gap-3">
                  <div className="space-y-0.5">
                    <span className="text-sm font-bold text-fg flex items-center gap-2">
                      Custom Goal
                    </span>
                    <p className="text-xs text-muted">
                      Set any number of chapters per day (1 to 50)
                    </p>
                  </div>

                  <div className="flex items-center gap-2">
                    <button
                      type="button"
                      onClick={() => handleCustomIncrement(-1)}
                      className="w-8 h-8 rounded-xl bg-surface hover:bg-surface-warm border border-border flex items-center justify-center text-fg transition-colors cursor-pointer"
                      title="Decrease by 1"
                    >
                      <Minus size={14} />
                    </button>

                    <div className="w-14 text-center">
                      <span className="text-lg font-display font-bold text-fg">
                        {selectedGoal}
                      </span>
                      <span className="block text-[10px] text-muted uppercase font-bold tracking-wider">
                        {selectedGoal === 1 ? 'Ch' : 'Chs'}
                      </span>
                    </div>

                    <button
                      type="button"
                      onClick={() => handleCustomIncrement(1)}
                      className="w-8 h-8 rounded-xl bg-surface hover:bg-surface-warm border border-border flex items-center justify-center text-fg transition-colors cursor-pointer"
                      title="Increase by 1"
                    >
                      <Plus size={14} />
                    </button>
                  </div>
                </div>
              </div>
            </div>

            {/* Reading Timeline Summary */}
            <div className="p-4 sm:p-5 rounded-2xl bg-bg border border-border/80 space-y-4">
              <div className="flex items-center justify-between">
                <span className="text-[11px] font-bold uppercase tracking-wider text-muted flex items-center gap-1.5">
                  <TrendingUp size={13} className="text-accent" />
                  At this pace
                </span>
                <span className="text-xs font-semibold text-fg">
                  {effectiveGoal} {effectiveGoal === 1 ? 'chapter' : 'chapters'} a day
                </span>
              </div>

              <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
                <div className="p-3 rounded-xl bg-surface/70 border border-border/60">
                  <span className="text-[10px] font-bold uppercase tracking-wider text-muted block mb-1">
                    Days Left
                  </span>
                  <div className="text-xl font-display font-bold text-fg">
                    ~{daysToFinish}
                  </div>
                  <span className="text-[10px] text-muted">
                    {remainingChapters} chapters to go
                  </span>
                </div>

                <div className="p-3 rounded-xl bg-surface/70 border border-border/60">
                  <span className="text-[10px] font-bold uppercase tracking-wider text-muted block mb-1">
                    Finish By
                  </span>
                  <div className="text-sm font-bold text-accent mt-1 whitespace-normal break-words">
                    {finishDateStr}
                  </div>
                  <span className="text-[10px] text-muted">
                    Whole Bible (1,189 chs)
                  </span>
                </div>

                <div className="p-3 rounded-xl bg-surface/70 border border-border/60 col-span-2 sm:col-span-1">
                  <span className="text-[10px] font-bold uppercase tracking-wider text-muted block mb-1">
                    Estimated Time
                  </span>
                  <div className="text-xl font-display font-bold text-fg">
                    ~{estMinutesPerDay}
                  </div>
                  <span className="text-[10px] text-muted">
                    Minutes per day
                  </span>
                </div>
              </div>

              {/* Progress Summary */}
              <div className="pt-2 border-t border-border/50 flex items-center justify-between text-xs text-muted">
                <span>Completed so far: <strong className="text-fg">{totalChaptersCompleted}</strong> / 1,189</span>
                <strong className="text-accent">{overallPercent}% Done</strong>
              </div>
            </div>
          </div>

          {/* Footer Actions */}
          <div className="p-4 sm:p-5 bg-surface border-t border-border flex items-center justify-end gap-2.5 shrink-0">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2.5 rounded-xl text-xs font-semibold text-fg-2 hover:text-fg hover:bg-surface-warm transition-colors cursor-pointer"
            >
              Cancel
            </button>
            <button
              type="button"
              onClick={handleSave}
              className="flex items-center gap-1.5 px-5 py-2.5 rounded-xl bg-accent text-accent-on text-xs sm:text-sm font-semibold hover:opacity-90 active:scale-95 transition-all shadow-xs cursor-pointer"
            >
              <Check size={16} />
              <span>Save Goal</span>
            </button>
          </div>
        </motion.div>
      </div>
    </AnimatePresence>,
    document.body
  );
}

"use client";

import React, { useState } from 'react';
import { InterlinearWord } from '@/lib/interlinearData';
import { NodeCategory } from '@/types/canvas';
import { Sparkles, Check, BookOpen, Volume2, Plus, ExternalLink, X } from 'lucide-react';

interface InterlinearHoverCardProps {
  word: InterlinearWord;
  onClose: () => void;
  onSendToCanvas?: (nodePayload: {
    title: string;
    content: string;
    category: NodeCategory;
  }) => void;
  theme: 'dark' | 'light';
  positionStyle?: React.CSSProperties;
}

export function InterlinearHoverCard({
  word,
  onClose,
  onSendToCanvas,
  theme,
  positionStyle,
}: InterlinearHoverCardProps) {
  const isDark = theme === 'dark';
  const [hasAddedToCanvas, setHasAddedToCanvas] = useState(false);
  const [isPlayingAudio, setIsPlayingAudio] = useState(false);

  const handleSpeakPronunciation = () => {
    if (typeof window === 'undefined' || !window.speechSynthesis) return;
    try {
      setIsPlayingAudio(true);
      const utterance = new SpeechSynthesisUtterance(word.transliteration);
      utterance.rate = 0.85;
      utterance.onend = () => setIsPlayingAudio(false);
      utterance.onerror = () => setIsPlayingAudio(false);
      window.speechSynthesis.speak(utterance);
    } catch {
      setIsPlayingAudio(false);
    }
  };

  const handleAddToCanvas = () => {
    if (!onSendToCanvas) return;
    const markdownContent = `### Original Language Nuance: ${word.transliteration} (${word.lemma})\n\n` +
      `**Strong's**: \`${word.strongs}\` | **Language**: ${word.language} (${word.partOfSpeech})\n` +
      `**Canon Frequency**: Appears **${word.occurrences}×** in the ${word.testament}\n\n` +
      `#### Lexical Definition\n${word.definition}\n\n` +
      `#### Key Passages\n` +
      word.keyVerses.map(v => `- **${v}**`).join('\n');

    onSendToCanvas({
      title: `Word Study: ${word.transliteration} (${word.lemma})`,
      content: markdownContent,
      category: 'word_study',
    });

    setHasAddedToCanvas(true);
    setTimeout(() => {
      setHasAddedToCanvas(false);
      onClose();
    }, 1200);
  };

  return (
    <div
      className={`z-50 w-full max-w-[calc(100vw-32px)] sm:w-96 rounded-2xl shadow-2xl border p-4 backdrop-blur-xl animate-in fade-in zoom-in-95 duration-150 break-words ${
        isDark
          ? 'bg-[#1e1e24]/95 border-zinc-700/80 text-zinc-100 shadow-[0_16px_40px_rgba(0,0,0,0.6)]'
          : 'bg-white/98 border-zinc-200 text-zinc-900 shadow-[0_16px_40px_rgba(0,0,0,0.12)]'
      }`}
      style={positionStyle}
    >
      {/* Header: Lemma, Transliteration & Close */}
      <div className="flex items-start justify-between gap-3 border-b pb-3 mb-3 border-zinc-200 dark:border-zinc-800">
        <div>
          <div className="flex items-center gap-2">
            <span
              className={`text-2xl font-serif font-bold ${
                word.language === 'Hebrew' ? 'text-amber-500 tracking-wider' : 'text-cyan-400'
              }`}
            >
              {word.lemma}
            </span>
            <span className="text-sm font-semibold italic text-zinc-500 dark:text-zinc-400">
              /{word.transliteration}/
            </span>
            <button
              type="button"
              onClick={handleSpeakPronunciation}
              className={`p-1 rounded-full transition-colors cursor-pointer ${
                isPlayingAudio 
                  ? 'text-accent bg-accent/20' 
                  : 'text-zinc-400 hover:text-zinc-200 hover:bg-zinc-700/30'
              }`}
              title={`Listen to pronunciation (${word.pronunciation})`}
            >
              <Volume2 size={14} />
            </button>
          </div>

          <div className="flex items-center gap-1.5 mt-1">
            <span className="text-[10px] font-bold tracking-wider uppercase px-2 py-0.5 rounded-full bg-accent/15 text-accent border border-accent/30">
              {word.strongs}
            </span>
            <span className="text-[11px] text-zinc-400 font-medium">
              {word.language} • {word.partOfSpeech}
            </span>
          </div>
        </div>

        <button
          type="button"
          onClick={onClose}
          className="p-1 rounded-lg text-zinc-400 hover:text-zinc-200 hover:bg-zinc-700/30 transition-colors cursor-pointer"
        >
          <X size={15} />
        </button>
      </div>

      {/* Root & Derivation */}
      {word.derivation && (
        <div className="mb-3 px-2.5 py-1.5 rounded-xl bg-zinc-100/90 dark:bg-zinc-800/50 border border-zinc-200/70 dark:border-zinc-700/50">
          <div className="text-[10px] font-bold text-zinc-500 dark:text-zinc-400 uppercase tracking-wider">
            Root & Derivation
          </div>
          <div className="text-xs text-zinc-800 dark:text-zinc-200 mt-0.5">
            {word.derivation}
          </div>
        </div>
      )}

      {/* Theological Definition */}
      <div className="space-y-2 mb-3.5">
        <div className="text-xs font-semibold text-zinc-500 dark:text-zinc-400 uppercase tracking-wider">
          Theological & Lexical Meaning
        </div>
        <p className="text-xs leading-relaxed text-zinc-700 dark:text-zinc-300 break-words">
          {word.definition}
        </p>
        {word.outline && word.outline !== word.definition && (
          <div className="pt-2 border-t border-zinc-200/60 dark:border-zinc-800">
            <div className="text-[10px] font-bold text-zinc-500 dark:text-zinc-400 uppercase tracking-wider mb-1">
              Biblical Usage
            </div>
            <p className="text-xs leading-relaxed text-zinc-600 dark:text-zinc-400 break-words">
              {word.outline}
            </p>
          </div>
        )}
      </div>

      {/* Frequency & Key Passages */}
      <div className="flex items-center justify-between py-2 px-2.5 rounded-xl bg-zinc-100 dark:bg-zinc-800/60 border border-zinc-200/80 dark:border-zinc-700/50 mb-3.5">
        <div className="flex items-center gap-1.5">
          <BookOpen size={13} className="text-zinc-400" />
          <span className="text-[11px] font-medium text-zinc-600 dark:text-zinc-300">
            Occurs <strong className="text-accent">{word.occurrences}×</strong> in {word.testament}
          </span>
        </div>
        <div className="text-[10px] font-semibold text-zinc-400">
          Pronounce: <span className="text-zinc-300">{word.pronunciation}</span>
        </div>
      </div>

      {/* Key Cross-References */}
      {word.keyVerses.length > 0 && (
        <div className="mb-3.5">
          <div className="text-[11px] font-semibold text-zinc-400 mb-1.5">
            Key Passages:
          </div>
          <div className="flex flex-wrap gap-1">
            {word.keyVerses.map((kv) => (
              <span
                key={kv}
                className="px-2 py-0.5 rounded-md text-[10px] font-medium bg-zinc-200/70 dark:bg-zinc-800 text-zinc-700 dark:text-zinc-300"
              >
                {kv}
              </span>
            ))}
          </div>
        </div>
      )}

      {/* Action Footer: Send Word Study to Canvas */}
      {onSendToCanvas && (
        <button
          type="button"
          onClick={handleAddToCanvas}
          disabled={hasAddedToCanvas}
          className={`w-full flex items-center justify-center gap-2 py-2 px-3 rounded-xl text-xs font-semibold transition-all cursor-pointer shadow-sm ${
            hasAddedToCanvas
              ? 'bg-emerald-600 text-white'
              : 'bg-accent text-white hover:bg-accent/90 active:scale-98'
          }`}
        >
          {hasAddedToCanvas ? (
            <>
              <Check size={14} />
              <span>Added to Canvas Board!</span>
            </>
          ) : (
            <>
              <Plus size={14} />
              <span>Create Word Study Node on Canvas</span>
            </>
          )}
        </button>
      )}
    </div>
  );
}

"use client";

import React from 'react';
import { Languages, Hash, Type, TableProperties, X, Sparkles } from 'lucide-react';

interface InterlinearModeRibbonProps {
  isOldTestament: boolean;
  bookName: string;
  chapter: number;
  showStrongs: boolean;
  onToggleShowStrongs: () => void;
  showTranslit: boolean;
  onToggleShowTranslit: () => void;
  onOpenVerseBreakdown: () => void;
  onDisableInterlinear: () => void;
  theme: 'dark' | 'light';
}

export function InterlinearModeRibbon({
  isOldTestament,
  bookName,
  chapter,
  showStrongs,
  onToggleShowStrongs,
  showTranslit,
  onToggleShowTranslit,
  onOpenVerseBreakdown,
  onDisableInterlinear,
  theme,
}: InterlinearModeRibbonProps) {
  const isDark = theme === 'dark';
  const languageName = isOldTestament ? 'Biblical Hebrew' : 'Koine Greek';
  const testamentTag = isOldTestament ? 'OT Masoretic Text' : 'NT Textus Receptus';

