"use client";

import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Flame, 
  X, 
  ChevronRight, 
  Award, 
  BookOpen, 
  Sun, 
  Check, 
  Sparkles,
  Calendar,
  ShieldCheck,
  ArrowRight,
  Sliders,
  Target
} from 'lucide-react';
import { 
  getStreakData, 
  StreakData, 
  getTodayStreakQuote, 
  getEncouragingMessage,
  setTargetMilestoneDays,
  STREAK_MILESTONES 
} from '@/lib/streakService';
import { SetMilestoneModal } from './SetMilestoneModal';
import { AnimatedStreakFlame } from './AnimatedStreakFlame';
import { DailyVerseModal } from './DailyVerseModal';

export interface StreakPopoverProps {
  onNavigateToTab: (tab: string) => void;
  onNavigateToVerse?: (book: string, chapter: number, verse: number) => void;
}

export function StreakPopover({
  onNavigateToTab,
  onNavigateToVerse,
}: StreakPopoverProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [mounted, setMounted] = useState(false);
  const [streakData, setStreakData] = useState<StreakData>(getStreakData());

  useEffect(() => {
    setMounted(true);
  }, []);
  const [activeTab, setActiveTab] = useState<'rhythm' | 'milestones'>('rhythm');
  const [currentQuote] = useState(getTodayStreakQuote());
  const [encouragementSeed] = useState(0);
  const [isSetMilestoneOpen, setIsSetMilestoneOpen] = useState(false);
  const [isDailyVerseOpen, setIsDailyVerseOpen] = useState(false);

  // Listen to streak changes across the app
  useEffect(() => {
    const handleUpdate = () => {
      setStreakData(getStreakData());
    };
    window.addEventListener('theologica_streak_updated', handleUpdate);
    window.addEventListener('storage', handleUpdate);
    return () => {
      window.removeEventListener('theologica_streak_updated', handleUpdate);
      window.removeEventListener('storage', handleUpdate);
    };
  }, []);

  // Handle ESC key
  useEffect(() => {
    if (!isOpen) return;
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') setIsOpen(false);
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isOpen]);

  const streak = streakData.currentStreak;
  const isGlowing = streakData.isCompletedToday;
  const encouragingMessage = getEncouragingMessage(
    isGlowing,
    streakData.isGraceActive,
    streak,
    encouragementSeed > 0 ? encouragementSeed : undefined
  );

  return (
    <>
      {/* Top Header Flame Pill Button */}
      <button
        type="button"
        onClick={(e) => {
          e.stopPropagation();
          setStreakData(getStreakData());
          setIsOpen(true);
        }}
        className={`flex items-center gap-1.5 px-2.5 py-1.5 min-h-[36px] sm:min-h-0 sm:py-1.5 sm:px-2.5 rounded-full border text-xs font-semibold transition-all cursor-pointer select-none active:scale-95 ${
          isGlowing
            ? 'bg-amber-500/15 border-amber-500/35 text-amber-500 dark:text-amber-400 hover:bg-amber-500/25 shadow-xs shadow-amber-500/10'
            : streak > 0
            ? 'bg-surface border-border text-fg hover:border-amber-500/40 hover:text-amber-500'
            : 'bg-surface border-border/70 text-muted hover:text-fg'
        }`}
        title={`${streak}-day reading streak`}
        aria-label="Daily Reading Streak"
      >
        <div className="relative flex items-center justify-center">
          <AnimatedStreakFlame 
            size={20} 
            streak={streak} 
            isGlowing={isGlowing} 
          />
        </div>
        <span className="tabular-nums font-bold tracking-tight text-xs">
          {streak}
        </span>
        <span className="hidden xl:inline text-[11px] font-medium opacity-80">
          {streak === 1 ? 'day' : 'days'}
        </span>
      </button>

      {/* Streak & Daily Rhythm Drawer / Modal mounted via Portal directly to body */}
      {mounted && typeof document !== 'undefined' && createPortal(
        <AnimatePresence>
          {isOpen && (
            <div 
              className="fixed inset-0 z-[100] flex items-center justify-center modal-safe-overlay bg-black/60 backdrop-blur-sm"
              onClick={(e) => {
                e.stopPropagation();
                setIsOpen(false);
              }}
            >
            <motion.div
              initial={{ opacity: 0, scale: 0.95, y: 10 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.95, y: 10 }}
              transition={{ duration: 0.2, ease: "easeOut" }}
              onClick={(e) => e.stopPropagation()}
              className="w-full max-w-lg bg-surface border border-border/80 rounded-3xl shadow-2xl overflow-hidden ring-1 ring-black/10 flex flex-col modal-safe-content"
            >
              {/* Top Hero Flame Header */}
              <div className="relative p-6 sm:p-8 bg-gradient-to-b from-amber-500/10 via-amber-500/5 to-transparent border-b border-border/60">
                <button
                  type="button"
                  onClick={() => setIsOpen(false)}
                  className="absolute top-4 right-4 min-w-[44px] min-h-[44px] flex items-center justify-center p-2 text-muted hover:text-fg rounded-xl hover:bg-fg/5 transition-colors cursor-pointer"
                  aria-label="Close"
                >
                  <X size={18} />
                </button>

                <div className="flex flex-col items-center text-center">
                  <div className="relative mb-3 flex flex-col items-center">
                    <div className="w-16 h-16 sm:w-20 sm:h-20 rounded-3xl bg-amber-500/15 border border-amber-500/30 flex items-center justify-center shadow-lg shadow-amber-500/15 overflow-hidden">
                      <AnimatedStreakFlame 
                        size={52} 
                        streak={streak} 
                        isGlowing={isGlowing} 
                      />
                    </div>
                  </div>

                  <h2 className="text-2xl sm:text-3xl font-display font-semibold text-fg tracking-tight mb-1">
                    {streak} <span className="text-base sm:text-lg font-sans font-normal text-muted">Day Streak</span>
                  </h2>

                  <p className="text-xs sm:text-sm text-fg-2 max-w-xs leading-relaxed min-h-[36px] flex items-center justify-center">
                    {encouragingMessage}
                  </p>

                  {/* Grace indicator badge */}
                  {streakData.isGraceActive && (
                    <div className="mt-3 inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-blue-500/10 border border-blue-500/25 text-blue-500 dark:text-blue-400 text-xs font-semibold">
                      <ShieldCheck size={14} />
                      <span>Grace Day Applied</span>
                    </div>
                  )}
                </div>

                {/* 7-Day Week Strip */}
                <div className="mt-6 pt-5 border-t border-border/40">
                  <div className="flex items-center justify-between text-center gap-1 sm:gap-2">
                    {streakData.weeklyActivity.map((day) => (
                      <div 
                        key={day.date} 
                        className="flex-1 flex flex-col items-center gap-1.5"
                      >
                        <span className={`text-[11px] font-bold ${
                          day.isToday ? 'text-accent font-extrabold' : 'text-muted'
                        }`}>
                          {day.dayLabel}
                        </span>

                        <div className={`w-8 h-8 sm:w-9 sm:h-9 rounded-2xl flex items-center justify-center transition-all ${
                          day.isCompleted
                            ? 'bg-amber-500 text-white shadow-xs shadow-amber-500/20'
                            : day.isToday
                            ? 'border-2 border-dashed border-accent text-fg bg-surface'
                            : 'bg-bg text-muted border border-border/50'
                        }`}>
                          {day.isCompleted ? (
                            <Flame size={16} className="fill-white" />
                          ) : (
                            <span className="text-[11px] font-semibold opacity-70">
                              {day.dayNumber}
                            </span>
                          )}
                        </div>

                        <div className="h-3 flex items-center justify-center">
                          {day.isToday && (
                            <span className="text-[9px] font-bold text-accent tracking-tighter uppercase">
                              Today
                            </span>
                          )}
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              </div>

              {/* View Switcher Tabs */}
              <div className="flex border-b border-border bg-bg/50 px-6 pt-2">
                <button
                  type="button"
                  onClick={() => setActiveTab('rhythm')}
                  className={`pb-2.5 px-3 text-xs font-semibold border-b-2 transition-all cursor-pointer ${
                    activeTab === 'rhythm'
                      ? 'border-accent text-accent font-bold'
                      : 'border-transparent text-muted hover:text-fg'
                  }`}
                >
                  Today
                </button>
                <button
                  type="button"
                  onClick={() => setActiveTab('milestones')}
                  className={`pb-2.5 px-3 text-xs font-semibold border-b-2 transition-all cursor-pointer flex items-center gap-1.5 ${
                    activeTab === 'milestones'
                      ? 'border-accent text-accent font-bold'
                      : 'border-transparent text-muted hover:text-fg'
                  }`}
                >
                  <Award size={13} />
                  <span>Milestones</span>
                  <span className="text-[10px] px-1.5 py-0.2 rounded-full bg-accent/15 text-accent font-bold">
                    {streakData.earnedMilestones.filter(m => m.isEarned).length}
                  </span>
                </button>
              </div>

              {/* Body Content */}
              <div className="flex-1 overflow-y-auto p-5 sm:p-6 space-y-4 custom-scroll">
                {activeTab === 'rhythm' ? (
                  <>
                    {isGlowing && (
                      <div className="p-3.5 rounded-2xl bg-amber-500/10 border border-amber-500/25 flex items-center gap-2.5 text-xs text-fg animate-in fade-in">
                        <Sparkles size={16} className="text-amber-500 shrink-0" />
                        <span className="font-medium">Congratulations! You spent time in the Word today.</span>
                      </div>
                    )}

                    <div className="space-y-2.5">
                      <div className="flex items-center justify-between">
                        <div className="text-[11px] font-bold uppercase tracking-widest text-muted">
                          Choose an Activity
                        </div>
                        <span className="text-[10px] text-muted">Complete any to build your streak</span>
                      </div>

                      {/* 1. Scripture */}
                      <div className="p-3.5 rounded-2xl bg-bg border border-border flex items-center justify-between gap-3 group hover:border-border-soft transition-all">
                        <div className="flex items-center gap-3">
                          <div className={`w-9 h-9 rounded-xl flex items-center justify-center shrink-0 ${
                            streakData.todayGoals.scripture 
                              ? 'bg-emerald-500/15 text-emerald-500 border border-emerald-500/30'
                              : 'bg-surface text-muted border border-border'
                          }`}>
                            {streakData.todayGoals.scripture ? <Check size={18} /> : <BookOpen size={18} />}
                          </div>
                          <div>
                            <div className="text-xs sm:text-sm font-bold text-fg flex items-center gap-1.5">
                              <span>Read Scripture</span>
                              {streakData.todayGoals.chaptersCompletedToday > 0 && (
                                <span className="text-[10px] px-1.5 py-0.2 rounded-md bg-accent/15 text-accent font-semibold">
                                  {streakData.todayGoals.chaptersCompletedToday} read
                                </span>
                              )}
                            </div>
                            <p className="text-[11px] text-muted">Study a chapter in the reader</p>
                          </div>
                        </div>

                        <button
                          type="button"
                          onClick={() => {
                            setIsOpen(false);
                            onNavigateToTab('study');
                          }}
                          className="px-3 py-1.5 rounded-xl bg-surface hover:bg-surface-hover text-fg text-xs font-semibold border border-border transition-colors cursor-pointer flex items-center gap-1"
                        >
                          <span>{streakData.todayGoals.scripture ? 'Read More' : 'Read'}</span>
                          <ChevronRight size={14} />
                        </button>
                      </div>

                      {/* 2. Devotional */}
                      <div className="p-3.5 rounded-2xl bg-bg border border-border flex items-center justify-between gap-3 group hover:border-border-soft transition-all">
                        <div className="flex items-center gap-3">
                          <div className={`w-9 h-9 rounded-xl flex items-center justify-center shrink-0 ${
                            streakData.todayGoals.devotional 
                              ? 'bg-emerald-500/15 text-emerald-500 border border-emerald-500/30'
                              : 'bg-surface text-muted border border-border'
                          }`}>
                            {streakData.todayGoals.devotional ? <Check size={18} /> : <Sun size={18} />}
                          </div>
                          <div>
                            <div className="text-xs sm:text-sm font-bold text-fg">Daily Devotional</div>
                            <p className="text-[11px] text-muted">Spurgeon’s Morning &amp; Evening</p>
                          </div>
                        </div>

                        <button
                          type="button"
                          onClick={() => {
                            setIsOpen(false);
                            onNavigateToTab('devotional');
                          }}
                          className="px-3 py-1.5 rounded-xl bg-surface hover:bg-surface-hover text-fg text-xs font-semibold border border-border transition-colors cursor-pointer flex items-center gap-1"
                        >
                          <span>{streakData.todayGoals.devotional ? 'Revisit' : 'Open'}</span>
                          <ChevronRight size={14} />
                        </button>
                      </div>
                    </div>

                    {/* Target Milestone Goal Card */}
                    <div className="p-4 rounded-2xl bg-surface border border-border/80 ring-shadow">
                      <div className="flex items-center justify-between mb-2.5">
                        <div className="flex items-center gap-2.5 min-w-0">
                          <span className="text-xl shrink-0 p-1.5 rounded-xl bg-accent/10 border border-accent/20">
                            {streakData.targetMilestone.badge}
                          </span>
                          <div className="min-w-0">
                            <div className="flex items-center gap-2 flex-wrap">
                              <h3 className="text-xs font-bold text-fg whitespace-normal">
                                Milestone: {streakData.targetMilestone.title}
                              </h3>
                              {streakData.targetMilestone.isEarned && (
                                <span className="text-[10px] font-bold px-1.5 py-0.2 rounded-full bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 border border-emerald-500/25">
                                  Achieved! 🎉
                                </span>
                              )}
                            </div>
                            <div className="text-[11px] text-muted leading-relaxed mt-0.5 whitespace-normal break-words">
                              {streakData.targetMilestone.isEarned 
                                ? 'Milestone achieved! Set your next milestone.' 
                                : `${streak} of ${streakData.targetMilestone.days} days completed • ${streakData.targetMilestone.daysRemaining} to go`}
                            </div>
                          </div>
                        </div>

                        <div className="flex items-center gap-2 shrink-0">
                          <button
                            type="button"
                            onClick={() => setIsSetMilestoneOpen(true)}
                            className="px-2.5 py-1 rounded-xl bg-bg hover:bg-surface-warm border border-border/80 text-fg text-xs font-semibold flex items-center gap-1 transition-all shadow-xs cursor-pointer group hover:border-accent/50"
                            title="Set your milestone"
                          >
                            <Sliders size={12} className="text-accent group-hover:scale-110 transition-transform" />
                            <span>Set Milestone</span>
                          </button>
                          <span className="text-xs font-mono font-bold text-accent">
                            {streakData.targetMilestone.progressPercent}%
                          </span>
                        </div>
                      </div>

                      <div className="h-2 w-full bg-bg rounded-full overflow-hidden inset-shadow">
                        <div 
                          className={`h-full transition-all duration-500 rounded-full ${
                            streakData.targetMilestone.isEarned ? 'bg-emerald-500' : 'bg-accent'
                          }`} 
                          style={{ width: `${streakData.targetMilestone.progressPercent}%` }} 
                        />
                      </div>
                    </div>

                    {/* Daily Scripture Quote */}
                    <div 
                      onClick={() => setIsDailyVerseOpen(true)}
                      className="p-3.5 sm:p-4 rounded-2xl bg-surface/60 hover:bg-surface border border-border/60 hover:border-accent/40 space-y-2 relative cursor-pointer transition-all active:scale-[0.99] group/scripture"
                    >
                      <div className="flex items-center justify-between text-muted pb-1 border-b border-border/40">
                        <span className="text-[10px] font-bold uppercase tracking-wider text-muted flex items-center gap-1.5">
                          <Sparkles size={11} className="text-accent" />
                          <span>Words of Scripture</span>
                        </span>
                      </div>
                      <blockquote className="text-center space-y-1.5 pt-0.5">
                        <p className="text-xs sm:text-sm italic text-fg font-serif leading-relaxed whitespace-normal break-words">
                          &ldquo;{currentQuote.text}&rdquo;
                        </p>
                        <cite className="text-[11px] font-semibold text-accent not-italic block">
                          {currentQuote.reference}
                        </cite>
                      </blockquote>
                    </div>
                  </>
                ) : (
                  /* Milestones Tab */
                  <div className="space-y-3">
                    <div className="flex items-center justify-between mb-2">
                      <div className="text-[11px] font-bold uppercase tracking-widest text-muted">
                        Reading Milestones
                      </div>
                      <button
                        type="button"
                        onClick={() => setIsSetMilestoneOpen(true)}
                        className="text-xs font-semibold text-accent hover:underline flex items-center gap-1 cursor-pointer"
                        title="Set a milestone"
                      >
                        <Sliders size={12} />
                        <span>Set Milestone</span>
                      </button>
                    </div>

                    {streakData.earnedMilestones.map((m) => {
                      const isCurrentGoal = streakData.targetMilestone.days === m.days;

                      return (
                        <div 
                          key={m.days} 
                          className={`p-3.5 rounded-2xl border transition-all flex items-center gap-3.5 ${
                            isCurrentGoal
                              ? 'bg-accent/10 border-accent/40 shadow-xs'
                              : m.isEarned 
                              ? 'bg-amber-500/10 border-amber-500/30' 
                              : 'bg-bg border-border opacity-70'
                          }`}
                        >
                          <div className="text-2xl shrink-0 p-1.5 rounded-xl bg-surface border border-border/60">
                            {m.badge}
                          </div>
                          <div className="flex-1 min-w-0">
                            <div className="flex items-center gap-2">
                              <h4 className="text-xs sm:text-sm font-bold text-fg">
                                {m.title}
                              </h4>
                              <span className="text-[10px] font-mono font-bold px-1.5 py-0.2 rounded bg-surface border border-border text-muted">
                                {m.days}d
                              </span>
                              {isCurrentGoal && (
                                <span className="text-[10px] font-bold px-1.5 py-0.2 rounded-full bg-accent/20 text-accent border border-accent/30">
                                  Current Milestone
                                </span>
                              )}
                            </div>
                            <p className="text-[11px] text-muted leading-tight mt-0.5">
                              {m.description}
                            </p>
                          </div>

                          <div className="flex items-center gap-2 shrink-0">
                            {!isCurrentGoal ? (
                              <button
                                type="button"
                                onClick={() => {
                                  setTargetMilestoneDays(m.days);
                                  setStreakData(getStreakData());
                                }}
                                className="px-2.5 py-1 rounded-xl bg-surface hover:bg-surface-hover border border-border text-xs font-semibold text-fg transition-colors cursor-pointer hover:border-accent/40"
                              >
                                Select Milestone
                              </button>
                            ) : null}

                            {m.isEarned && (
                              <div className="p-1 rounded-full bg-emerald-500 text-white shrink-0" title="Milestone earned">
                                <Check size={12} strokeWidth={2.5} />
                              </div>
                            )}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                )}
              </div>

              {/* Footer */}
              <div className="p-4 bg-bg border-t border-border flex items-center justify-between text-xs text-muted">
                <div className="flex items-center gap-3">
                  <span>Best: <strong className="text-fg">{streakData.longestStreak} {streakData.longestStreak === 1 ? 'day' : 'days'}</strong></span>
                  <span>&bull;</span>
                  <span>Total: <strong className="text-fg">{streakData.totalActiveDays} {streakData.totalActiveDays === 1 ? 'day' : 'days'}</strong></span>
                </div>
                <button
                  type="button"
                  onClick={() => {
                    setIsOpen(false);
                    onNavigateToTab('tracker');
                  }}
                  className="font-semibold text-accent hover:underline flex items-center gap-1 cursor-pointer"
                >
                  <span>Open Full Tracker</span>
                  <ArrowRight size={13} />
                </button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>,
      document.body
    )}

      {/* Set Milestone Goal Modal */}
      <SetMilestoneModal
        isOpen={isSetMilestoneOpen}
        currentStreak={streak}
        currentMilestoneDays={streakData.targetMilestone.days}
        onSave={(newDays) => {
          setTargetMilestoneDays(newDays);
          setStreakData(getStreakData());
        }}
        onClose={() => setIsSetMilestoneOpen(false)}
      />

      {/* Daily Scripture Verse Full Modal */}
      <DailyVerseModal
        isOpen={isDailyVerseOpen}
        verseRef={currentQuote.reference}
        initialExcerpt={currentQuote.text}
        onClose={() => setIsDailyVerseOpen(false)}
        onNavigateToVerse={(book, chapter, verse) => {
          setIsDailyVerseOpen(false);
          setIsOpen(false);
          if (onNavigateToVerse) {
            onNavigateToVerse(book, chapter, verse);
          } else {
            onNavigateToTab('reader');
          }
        }}
      />
    </>
  );
}

"use client";

import React, { useState, useEffect, useRef } from 'react';
import { 
  Flame, 
  Award, 
  Target, 
  BookOpen, 
  Sun, 
  Check, 
  Calendar, 
  TrendingUp, 
  ChevronRight, 
  ShieldCheck, 
  Sparkles, 
  Sliders
} from 'lucide-react';
import { 
  getStreakData, 
  StreakData, 
  STREAK_MILESTONES,
  getTodayStreakQuote
} from '@/lib/streakService';
import { AnimatedStreakFlame } from './AnimatedStreakFlame';
import { EditPaceModal } from './EditPaceModal';
import { ReadingCalendarModal } from './ReadingCalendarModal';
import { DailyVerseModal } from './DailyVerseModal';

export interface TrackerStreakHeroProps {
  dailyChapterGoal: number;
  totalChaptersCompleted: number;
  onNavigateToTab: (tab: string) => void;
  onNavigateToVerse?: (book: string, chapter: number, verse: number) => void;
  onUpdateDailyChapterGoal?: (goal: number) => void;
}

export function TrackerStreakHero({
  dailyChapterGoal,
  totalChaptersCompleted,
  onNavigateToTab,
  onNavigateToVerse,
  onUpdateDailyChapterGoal,
}: TrackerStreakHeroProps) {
  const [streakData, setStreakData] = useState<StreakData>(getStreakData());
  const [isEditPaceOpen, setIsEditPaceOpen] = useState(false);
  const [isCalendarOpen, setIsCalendarOpen] = useState(false);
  const [isDailyVerseOpen, setIsDailyVerseOpen] = useState(false);
  const [quote] = useState(getTodayStreakQuote());

  useEffect(() => {
    const handleUpdate = () => setStreakData(getStreakData());
    window.addEventListener('theologica_streak_updated', handleUpdate);
    window.addEventListener('storage', handleUpdate);
    return () => {
      window.removeEventListener('theologica_streak_updated', handleUpdate);
      window.removeEventListener('storage', handleUpdate);
    };
  }, []);

  const totalBibleChapters = 1189;
  const chaptersToday = streakData.todayGoals.chaptersCompletedToday || 0;
  const goalProgressPercent = Math.min(100, Math.round((chaptersToday / Math.max(1, dailyChapterGoal)) * 100));
  const isGoalMet = chaptersToday >= dailyChapterGoal;

  const estimatedDaysLeft = Math.max(1, Math.round((totalBibleChapters - totalChaptersCompleted) / Math.max(1, dailyChapterGoal)));
  const estimatedYearsLeft = (estimatedDaysLeft / 365).toFixed(1);

  return (
    <div className="space-y-6 mb-8 sm:mb-12">
      {/* Top 3-Card Grid: Streak Flame + Today's Chapter Goal + Longest Record */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        {/* Card 1: Streak Card */}
        <div className="p-5 sm:p-6 rounded-3xl bg-gradient-to-br from-amber-500/10 via-surface to-surface border border-border/80 ring-shadow relative overflow-hidden flex flex-col justify-between">
          <div className="flex items-start justify-between">
            <div className="space-y-1">
              <span className="text-[11px] font-bold uppercase tracking-wider text-muted">
                Reading Streak
              </span>
              <div className="flex items-baseline gap-2">
                <span className="text-3xl sm:text-4xl font-display font-bold text-fg">
                  {streakData.currentStreak}
                </span>
                <span className="text-sm font-semibold text-fg-2">
                  {streakData.currentStreak === 1 ? 'Day' : 'Days'}
                </span>
              </div>
            </div>

            <div className={`w-12 h-12 rounded-2xl flex items-center justify-center border shadow-xs ${
              streakData.isCompletedToday
                ? 'bg-amber-500/20 text-amber-500 border-amber-500/40 shadow-amber-500/15'
                : 'bg-surface text-muted border-border'
            }`}>
              <AnimatedStreakFlame size={38} streak={streakData.currentStreak} isGlowing={streakData.isCompletedToday} />
            </div>
          </div>

          <div className="mt-4 pt-3 border-t border-border/50 flex items-center justify-between text-xs">
            <div className="flex items-center gap-1.5 text-muted">
              {streakData.isCompletedToday ? (
                <>
                  <Check size={14} className="text-emerald-500 font-bold" />
                  <span className="text-emerald-500 font-medium">Read today</span>
                </>
              ) : (
                <span>Read today to keep your streak</span>
              )}
            </div>
            {streakData.isGraceActive && (
              <span className="text-[10px] font-bold text-blue-500 bg-blue-500/10 px-2 py-0.5 rounded-full border border-blue-500/20">
                Grace Applied
              </span>
            )}
          </div>
        </div>

        {/* Card 2: Today's Chapter Goal */}
        <div className="p-5 sm:p-6 rounded-3xl bg-surface border border-border/80 ring-shadow flex flex-col justify-between">
          <div className="flex items-start justify-between">
            <div className="space-y-1">
              <span className="text-[11px] font-bold uppercase tracking-wider text-muted">
                Today’s Goal
              </span>
              <div className="flex items-baseline gap-2">
                <span className="text-3xl sm:text-4xl font-display font-bold text-fg">
                  {chaptersToday}
                </span>
                <span className="text-sm font-semibold text-fg-2">
                  / {dailyChapterGoal} {dailyChapterGoal === 1 ? 'Chapter' : 'Chapters'}
                </span>
              </div>
            </div>

            <div className={`w-12 h-12 rounded-2xl flex items-center justify-center border shadow-xs ${
              isGoalMet 
                ? 'bg-emerald-500/15 text-emerald-500 border-emerald-500/30'
                : 'bg-surface text-muted border-border'
            }`}>
              <Target size={24} className={isGoalMet ? 'text-emerald-500' : ''} />
            </div>
          </div>

          {/* Goal Progress bar */}
          <div className="mt-4 pt-3 border-t border-border/50 space-y-1.5">
            <div className="flex justify-between text-[11px] text-muted">
              <span>{goalProgressPercent}% completed</span>
              {isGoalMet && <span className="font-bold text-emerald-500">Goal Reached! 🎉</span>}
            </div>
            <div className="h-2 w-full bg-bg rounded-full overflow-hidden inset-shadow">
              <div 
                className={`h-full transition-all duration-700 rounded-full ${
                  isGoalMet ? 'bg-emerald-500' : 'bg-accent'
                }`}
                style={{ width: `${goalProgressPercent}%` }}
              />
            </div>

            {/* Clean Edit Daily Goal Button */}
            {onUpdateDailyChapterGoal && (
              <button
                type="button"
                onClick={() => setIsEditPaceOpen(true)}
                className="w-full mt-2.5 py-1.5 px-3 rounded-xl bg-bg hover:bg-surface-warm border border-border/80 text-fg text-xs font-semibold flex items-center justify-center gap-1.5 transition-all shadow-xs cursor-pointer group hover:border-accent/50"
                title="Change your daily chapter reading goal"
              >
                <Sliders size={13} className="text-accent group-hover:scale-110 transition-transform" />
                <span>Edit Daily Goal</span>
                <ChevronRight size={13} className="text-muted group-hover:translate-x-0.5 transition-transform" />
              </button>
            )}
          </div>
        </div>

        {/* Card 3: Bible Reading Pace & Timeline */}
        <div className="p-5 sm:p-6 rounded-3xl bg-surface border border-border/80 ring-shadow flex flex-col justify-between">
          <div className="flex items-start justify-between">
            <div className="space-y-1">
              <span className="text-[11px] font-bold uppercase tracking-wider text-muted">
                Reading Pace
              </span>
              <div className="flex items-baseline gap-1.5">
                <span className="text-3xl sm:text-4xl font-display font-bold text-fg">
                  ~{estimatedDaysLeft}
                </span>
                <span className="text-sm font-semibold text-fg-2">Days to Finish</span>
              </div>
            </div>

            <div className="w-12 h-12 rounded-2xl bg-accent/10 text-accent border border-accent/20 flex items-center justify-center shadow-xs">
              <TrendingUp size={24} />
            </div>
          </div>

          <div className="mt-4 pt-3 border-t border-border/50 text-xs text-muted flex items-center justify-between">
            <span>At <strong className="text-fg">{dailyChapterGoal} ch/day</strong></span>
            {onUpdateDailyChapterGoal ? (
              <button
                type="button"
                onClick={() => setIsEditPaceOpen(true)}
                className="text-xs font-semibold text-accent hover:underline flex items-center gap-0.5 cursor-pointer"
                title="Change daily reading goal"
              >
                <span>Edit Goal</span>
                <ChevronRight size={12} />
              </button>
            ) : (
              <span>Approx. <strong className="text-accent">{estimatedYearsLeft} years</strong></span>
            )}
          </div>
        </div>
      </div>

      {/* 7-Day Week Calendar Strip Card */}
      <div className="p-5 sm:p-6 rounded-3xl bg-surface border border-border/80 ring-shadow">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 mb-5">
          <button
            type="button"
            onClick={() => setIsCalendarOpen(true)}
            className="flex items-center gap-2.5 group text-left cursor-pointer p-1 -m-1 rounded-xl hover:bg-surface-hover transition-colors"
            title="Open streak calendar"
          >
            <div className="w-8 h-8 rounded-xl bg-accent/15 border border-accent/30 flex items-center justify-center text-accent group-hover:scale-105 group-hover:bg-accent/25 transition-all shadow-xs">
              <Calendar size={16} />
            </div>
            <div>
              <h3 className="text-sm sm:text-base font-bold text-fg group-hover:text-accent transition-colors flex items-center gap-1.5">
                <span>This Week</span>
                <ChevronRight size={14} className="text-muted group-hover:text-accent group-hover:translate-x-0.5 transition-all" />
              </h3>
            </div>
          </button>

          <div className="flex items-center gap-3 text-xs text-muted">
            <span>Best Streak: <strong className="text-fg">{streakData.longestStreak} {streakData.longestStreak === 1 ? 'day' : 'days'}</strong></span>
            <span>&bull;</span>
            <span>Total Active: <strong className="text-fg">{streakData.totalActiveDays} {streakData.totalActiveDays === 1 ? 'day' : 'days'}</strong></span>
          </div>
        </div>

        {/* 7 Day Indicators */}
        <div className="grid grid-cols-7 gap-1.5 sm:gap-3 text-center">
          {streakData.weeklyActivity.map((day) => (
            <button
              key={day.date}
              type="button"
              onClick={() => setIsCalendarOpen(true)}
              className={`p-2 sm:p-3 rounded-2xl border transition-all flex flex-col items-center gap-1.5 cursor-pointer group hover:scale-[1.02] ${
                day.isToday
                  ? 'bg-accent/10 border-accent/40 shadow-xs'
                  : day.isCompleted
                  ? 'bg-amber-500/10 border-amber-500/30 hover:border-amber-500/50'
                  : 'bg-bg/60 border-border/60 hover:border-border-soft'
              }`}
              title={`View ${day.dayName} in Streak Calendar`}
            >
              <span className={`text-[11px] font-bold ${
                day.isToday ? 'text-accent' : 'text-muted group-hover:text-fg'
              }`}>
                {day.dayName}
              </span>

              <div className={`w-8 h-8 sm:w-10 sm:h-10 rounded-xl flex items-center justify-center transition-all ${
                day.isCompleted
                  ? 'bg-gradient-to-br from-amber-500 to-amber-600 text-white shadow-xs shadow-amber-500/25'
                  : day.isToday
                  ? 'bg-accent/20 border border-accent text-accent font-bold'
                  : 'bg-surface text-muted border border-border/40 group-hover:text-fg'
              }`}>
                {day.isCompleted ? (
                  <Flame size={22} className="fill-white" />
                ) : (
                  <span className="text-xs font-semibold">{day.dayNumber}</span>
                )}
              </div>

              <span className={`text-[10px] font-semibold ${
                day.isCompleted ? 'text-amber-500 font-bold' : day.isToday ? 'text-accent font-bold' : 'text-muted'
              }`}>
                {day.isCompleted ? 'Done' : day.isToday ? 'Today' : '-'}
              </span>
            </button>
          ))}
        </div>

        {/* Quick Spiritual Action Links */}
        <div className="mt-5 pt-4 border-t border-border/60 flex flex-wrap items-center justify-end gap-2.5">
          <button
            type="button"
            onClick={() => onNavigateToTab('study')}
            className="px-4 py-2 rounded-xl bg-accent hover:bg-[#b5583b] text-accent-on text-xs font-semibold shadow-xs hover:shadow transition-all cursor-pointer flex items-center gap-2 active:scale-95"
          >
            <BookOpen size={14} className="text-accent-on" />
            <span>Read Scripture</span>
          </button>

          <button
            type="button"
            onClick={() => onNavigateToTab('devotional')}
            className="px-4 py-2 rounded-xl bg-amber-500/15 hover:bg-amber-500/25 text-amber-500 border border-amber-500/35 text-xs font-semibold shadow-xs hover:shadow transition-all cursor-pointer flex items-center gap-2 active:scale-95"
          >
            <Sun size={14} className="text-amber-500" />
            <span>Today’s Devotional</span>
          </button>
        </div>

        {/* Scripture Encouragement Bar - Full verse displayed at all times */}
        <div 
          onClick={() => setIsDailyVerseOpen(true)}
          className="mt-4 pt-4 border-t border-border/50 flex items-start gap-3 text-xs cursor-pointer hover:opacity-95 transition-opacity group/tracker-quote"
        >
          <div className="w-7 h-7 rounded-xl bg-accent/10 group-hover/tracker-quote:bg-accent/20 border border-accent/20 flex items-center justify-center shrink-0 text-accent transition-colors mt-0.5">
            <Sparkles size={13} />
          </div>
          <div className="min-w-0 flex-1">
            <p className="italic text-fg font-serif text-xs sm:text-sm leading-relaxed whitespace-normal break-words">
              &ldquo;{quote.text}&rdquo;
            </p>
            <div className="mt-1 flex items-center gap-2">
              <span className="text-[11px] font-semibold text-accent not-italic">
                — {quote.reference}
              </span>
            </div>
          </div>
        </div>
      </div>

      {/* Reading Calendar Modal */}
      <ReadingCalendarModal
        isOpen={isCalendarOpen}
        onClose={() => setIsCalendarOpen(false)}
        activeDates={streakData.activeDates}
        currentStreak={streakData.currentStreak}
        longestStreak={streakData.longestStreak}
        totalActiveDays={streakData.totalActiveDays}
      />

      {/* Edit Pace / Goals Modal */}
      {onUpdateDailyChapterGoal && (
        <EditPaceModal
          isOpen={isEditPaceOpen}
          currentGoal={dailyChapterGoal}
          totalChaptersCompleted={totalChaptersCompleted}
          onSave={(newGoal) => {
            onUpdateDailyChapterGoal(newGoal);
          }}
          onClose={() => setIsEditPaceOpen(false)}
        />
      )}

      {/* Daily Scripture Verse Full Modal */}
      <DailyVerseModal
        isOpen={isDailyVerseOpen}
        verseRef={quote.reference}
        initialExcerpt={quote.text}
        onClose={() => setIsDailyVerseOpen(false)}
        onNavigateToVerse={(book, chapter, verse) => {
          setIsDailyVerseOpen(false);
          if (onNavigateToVerse) {
            onNavigateToVerse(book, chapter, verse);
          } else {
            onNavigateToTab('reader');
          }
        }}
      />
    </div>
  );
}

