      }
    }, 150);
  }, [incomingNode, handleCreateBoard, handleSelectBoard, prepareNode, saveBoardImmediate, theme, onNavigateToVerse, handleUpdateNode, handleDuplicateNode, handleDeleteNode, handleResizeNodeEnd, handleConnectTo, handleSpawnCrossReferences, onIncomingNodeHandled, pushSnapshot, fitView, setNodes]);

  // Add card from toolbar or context menu
  const handleAddNode = useCallback((category: NodeCategory, customPos?: { x: number; y: number }) => {
    if (!activeBoardIdRef.current) {
      handleCreateBoard();
    }

    const timestamp = Date.now();
    const newId = `card-${timestamp}`;

    let posX = customPos ? customPos.x : 200;
    let posY = customPos ? customPos.y : 200;

    if (!customPos && nodesRef.current.length > 0) {
      const last = nodesRef.current[nodesRef.current.length - 1];
      posX = last.position.x + 60;
      posY = last.position.y + 60;
    }

    const titles: Record<NodeCategory, string> = {
      scripture: 'Scripture Verse',
      theological_point: 'Theological Definition',
      historical_context: 'Historical Setting',
      illustration: 'Typology / Analogy',
      application: 'Personal Application',
      word_study: 'Original Language Word Study',
      general: 'New Note',
    };

    const cardWidth = isMobile ? 310 : 380;
    const newNode: Node<CanvasNodeData> = {
      id: newId,
      type: 'customCard',
      position: { x: posX, y: posY },
      selected: true,
      style: { width: cardWidth },
      data: {
        title: titles[category],
        content: '',
        category,
        theme,
        onVerseClick: onNavigateToVerse,
        onUpdate: handleUpdateNode,
        onDuplicate: handleDuplicateNode,
        onDelete: handleDeleteNode,
        onResizeEnd: handleResizeNodeEnd,
        onConnectTo: handleConnectTo,
        onSpawnCrossReferences: handleSpawnCrossReferences,
      },
    };

    setNodes((nds) => {
      const next: Node<CanvasNodeData>[] = [
        ...nds.map((n) => ({ ...n, selected: false })),
        newNode,
      ];
      pushSnapshot(next, edgesRef.current);
      return next;
    });
  }, [handleCreateBoard, theme, onNavigateToVerse, handleUpdateNode, handleDuplicateNode, handleDeleteNode, handleResizeNodeEnd, handleConnectTo, handleSpawnCrossReferences, pushSnapshot, setNodes, isMobile]);

  // Connecting edges
  const onConnect = useCallback((connection: Connection) => {
    if (!connection.source || !connection.target) return;
    if (connection.source === connection.target) return; // Prevent self-connections

    setEdges((eds) => {
      const exists = eds.some(
        (e) => e.source === connection.source && e.target === connection.target
      );
      if (exists) return eds;

      const newEdge: Edge = {
        ...connection,
        id: `edge-${Date.now()}-${Math.random().toString(36).substring(2, 6)}`,
        type: 'customEdge',
        label: 'Relates to',
        animated: true,
        data: {
          theme,
          onEdgeDelete: handleEdgeDelete,
          onEdgeLabelChange: handleEdgeLabelChange,
        },
        markerEnd: {
          type: MarkerType.ArrowClosed,
          color: isDark ? '#a1a1aa' : '#71717a',
          width: 16,
          height: 16,
        },
      } as Edge;

      const next = addEdge(newEdge, eds);
      pushSnapshot(nodesRef.current, next);
      return next;
    });
  }, [isDark, theme, handleEdgeDelete, handleEdgeLabelChange, pushSnapshot, setEdges]);

  // Capture drag stop so moving nodes can be undone!
  const onNodeDragStop = useCallback(() => {
    pushSnapshot(nodesRef.current, edgesRef.current);
  }, [pushSnapshot]);

  // Capture node delete
  const onNodesDelete = useCallback((deleted: Node[]) => {
    const deletedIds = new Set(deleted.map((n) => n.id));
    const nextNodes = nodesRef.current.filter((n) => !deletedIds.has(n.id));
    const nextEdges = edgesRef.current.filter(
      (e) => !deletedIds.has(e.source) && !deletedIds.has(e.target)
    );
    pushSnapshot(nextNodes, nextEdges);
  }, [pushSnapshot]);

  // Capture edge delete
  const onEdgesDelete = useCallback((deleted: Edge[]) => {
    const deletedIds = new Set(deleted.map((e) => e.id));
    const nextEdges = edgesRef.current.filter((e) => !deletedIds.has(e.id));
    pushSnapshot(nodesRef.current, nextEdges);
  }, [pushSnapshot]);

  // UNDO implementation
  const handleUndo = useCallback(() => {
    if (historyIndexRef.current <= 0) return;

    isUndoRedoActive.current = true;
    historyIndexRef.current -= 1;
    const snapshot = historyRef.current[historyIndexRef.current];

    if (!snapshot) return;

    const restoredNodes = snapshot.nodes.map(prepareNode);
    const restoredEdges = snapshot.edges.map(prepareEdge);

    isDirtyRef.current = true;
    setNodes(restoredNodes);
    setEdges(restoredEdges);
    updateHistoryState();
  }, [prepareEdge, prepareNode, setEdges, setNodes, updateHistoryState]);

  // REDO implementation
  const handleRedo = useCallback(() => {
    if (historyIndexRef.current >= historyRef.current.length - 1) return;

    isUndoRedoActive.current = true;
    historyIndexRef.current += 1;
    const snapshot = historyRef.current[historyIndexRef.current];

    if (!snapshot) return;

    const restoredNodes = snapshot.nodes.map(prepareNode);
    const restoredEdges = snapshot.edges.map(prepareEdge);

    isDirtyRef.current = true;
    setNodes(restoredNodes);
    setEdges(restoredEdges);
    updateHistoryState();
  }, [prepareEdge, prepareNode, setEdges, setNodes, updateHistoryState]);

  // Global Keyboard Shortcuts (Cmd+Z, Cmd+Shift+Z, Cmd+S, Delete)
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement;
      if (
        target.tagName === 'INPUT' ||
        target.tagName === 'TEXTAREA' ||
        target.isContentEditable
      ) {
        return;
      }

      if ((e.metaKey || e.ctrlKey) && !e.shiftKey && e.key.toLowerCase() === 's') {
        e.preventDefault();
        handleManualSave();
      } else if ((e.metaKey || e.ctrlKey) && !e.shiftKey && e.key.toLowerCase() === 'z') {
        e.preventDefault();
        handleUndo();
      } else if (
        (e.metaKey || e.ctrlKey) &&
        (e.shiftKey || e.key.toLowerCase() === 'y') &&
        (e.key.toLowerCase() === 'z' || e.key.toLowerCase() === 'y')
      ) {
        e.preventDefault();
        handleRedo();
      } else if (e.key === 'Delete' || e.key === 'Backspace') {
        const selectedNodes = nodesRef.current.filter((n) => n.selected);
        const selectedEdges = edgesRef.current.filter((ed) => ed.selected);

        if (selectedNodes.length === 0 && selectedEdges.length === 0) return;

        const selectedNodeIds = new Set(selectedNodes.map((n) => n.id));
        const selectedEdgeIds = new Set(selectedEdges.map((e) => e.id));

        const nextNodes = nodesRef.current.filter((n) => !selectedNodeIds.has(n.id));
        const nextEdges = edgesRef.current.filter(
          (e) => !selectedEdgeIds.has(e.id) && !selectedNodeIds.has(e.source) && !selectedNodeIds.has(e.target)
        );

        setNodes(nextNodes);
        setEdges(nextEdges);
        pushSnapshot(nextNodes, nextEdges);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleUndo, handleRedo, handleManualSave, pushSnapshot, setEdges, setNodes]);

  // Clear Canvas
  const handleClear = useCallback(() => {
    if (nodes.length === 0) return;
    setIsClearConfirmOpen(true);
  }, [nodes.length]);

  const confirmClearBoard = useCallback(() => {
    setNodes([]);
    setEdges([]);
    pushSnapshot([], []);
    setIsClearConfirmOpen(false);
  }, [pushSnapshot, setEdges, setNodes]);

  // Apply updates from Theologica AI
  const handleApplyAiGraph = useCallback((
    newNodes: SerializableNode[],
    newEdges: SerializableEdge[],
    explanation: string,
    suggestedBoardTitle?: string,
    mode?: 'generate' | 'expand' | 'synthesize' | 'discourse'
  ) => {
    const cleanTitle = (typeof suggestedBoardTitle === 'string' && suggestedBoardTitle.trim())
      ? suggestedBoardTitle.trim()
      : '';

    // 1. If no board is active, create a new board with the AI's title
    if (!activeBoardIdRef.current) {
      handleCreateBoard(cleanTitle || 'Theologica Study Canvas');
    } else if (cleanTitle) {
      // 2. If board is active, automatically rename the canvas if:
      //    - mode is 'generate' (user asked AI to generate a study canvas)
      //    - or the board is empty (brand new blank board)
      //    - or the board still has a default placeholder title
      const currentTitle = (boardTitleRef.current || '').trim().toLowerCase();
      const isDefaultPlaceholder = !currentTitle || 
        ['new canvas', 'untitled canvas', 'untitled', 'theologica study canvas', 'new canvas board'].includes(currentTitle);
      const isCleanBoard = nodesRef.current.length === 0;

      if (mode === 'generate' || isCleanBoard || isDefaultPlaceholder) {
        handleRenameBoard(activeBoardIdRef.current, cleanTitle);
      }
    }

    const preparedNewNodes = newNodes.map(prepareNode);
    const preparedNewEdges = newEdges.map(prepareEdge);

    const nextNodes: Node<CanvasNodeData>[] = [
      ...nodesRef.current.map((n) => ({ ...n, selected: false })),
      ...preparedNewNodes.map((n) => ({ ...n, selected: true })),
    ];
    const nextEdges = edgesRef.current.concat(preparedNewEdges);

    // Automatically organize into clean, collision-free topological columns with optimal edge handles!
    const { arrangedNodes, arrangedEdges } = arrangeGraph(nextNodes, nextEdges);

    setNodes(arrangedNodes);
    setEdges(arrangedEdges);
    pushSnapshot(arrangedNodes, arrangedEdges);

    if (!isMobile) {
      const toastMessage = explanation || (cleanTitle 
        ? `Theologica AI generated "${cleanTitle}" with ${newNodes.length} cards.`
        : `Theologica AI added ${newNodes.length} cards to your canvas.`);

      setAiToast({
        message: toastMessage,
        count: newNodes.length,
      });
      setTimeout(() => setAiToast(null), 6000);
    }

    setTimeout(() => {
      if (containerRef.current && containerRef.current.clientWidth > 100) {
        fitView({ padding: 0.28, duration: 800, minZoom: 0.35, maxZoom: 1.1 });
      }
    }, 150);
  }, [arrangeGraph, fitView, handleCreateBoard, handleRenameBoard, prepareEdge, prepareNode, pushSnapshot, setEdges, setNodes, isMobile]);

  // Target selected node for AI expansion
  const selectedNode = useMemo(() => {
    const selected = nodes.filter((n) => n.selected);
    if (selected.length === 1) {
      const s = selected[0];
      return {
        id: s.id,
        type: 'customCard' as const,
        position: s.position,
        data: s.data,
      };
    }
    return null;
  }, [nodes]);

  const currentGraphPayload = useMemo((): CanvasStatePayload => {
    return {
      nodes: toSerializableNodes(nodes),
      edges: toSerializableEdges(edges),
    };
  }, [nodes, edges, toSerializableNodes, toSerializableEdges]);

  // Start Page: Generate new canvas from prompt
  const handleGenerateFromStartPage = useCallback(async (
    promptText: string,
    mode: 'generate' | 'discourse' | 'synthesize',
    lens: string
  ) => {
    setIsStartPageGenerating(true);
    setStartPageGeneratingStep(0);

    const controller = new AbortController();
    startPageAbortControllerRef.current = controller;

    const t1 = setTimeout(() => setStartPageGeneratingStep(1), 4000);
    const t2 = setTimeout(() => setStartPageGeneratingStep(2), 9000);
    const t3 = setTimeout(() => setStartPageGeneratingStep(3), 14000);

    try {
      const res = await fetch('/api/canvas/ai', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        signal: controller.signal,
        body: JSON.stringify({
          prompt: promptText,
          currentGraph: { nodes: [], edges: [] },
          mode,
          theologicalLens: lens,
        }),
      });

      const data = await res.json();
      if (!res.ok) {
        throw new Error(data.error || "Failed to architect canvas board.");
      }

      const cleanTitle = (data.boardTitle || '').trim() || (promptText.length > 35 ? promptText.slice(0, 35) + '...' : promptText);

      // 1. Create a fresh canvas board
      handleCreateBoard(cleanTitle);

      // 2. Populate graph with generated cards
      if (Array.isArray(data.nodes) && data.nodes.length > 0) {
        handleApplyAiGraph(data.nodes, data.edges || [], data.explanation, cleanTitle, mode);
      }

      // 3. Close start page and display board
      setIsCreatePageActive(false);
      setAiToast({ message: `Architected canvas: "${cleanTitle}"`, count: data.nodes?.length || 0 });

      setTimeout(() => {
        spawnToCards(500);
      }, 200);
    } catch (err: any) {
      if (err.name === 'AbortError') return;
      console.error('Failed to generate canvas from start page:', err);
      alert(err.message || 'Failed to architect canvas. Please try again.');
    } finally {
      clearTimeout(t1);
      clearTimeout(t2);
      clearTimeout(t3);
      setIsStartPageGenerating(false);
      startPageAbortControllerRef.current = null;
    }
  }, [handleCreateBoard, handleApplyAiGraph, spawnToCards]);

  // Import shared canvas success handler
  const handleImportSuccess = useCallback((imported: {
    id: string;
    title: string;
    nodes: any[];
    edges: any[];
    viewport?: any;
  }) => {
    const pNodes = (imported.nodes || []).map(prepareNode);
    const pEdges = (imported.edges || []).map(prepareEdge);

    try {
      localStorage.setItem(`${STORAGE_KEY_BOARD_PREFIX}${imported.id}`, JSON.stringify({
        id: imported.id,
        title: imported.title,
        nodes: imported.nodes || [],
        edges: imported.edges || [],
        viewport: imported.viewport || undefined,
        updatedAt: new Date().toISOString(),
      }));

      const existingList = JSON.parse(localStorage.getItem(STORAGE_KEY_BOARDS_LIST) || '[]');
      const metaItem = {
        id: imported.id,
        title: imported.title,
        updatedAt: new Date().toISOString(),
        nodeCount: pNodes.length,
      };
      const updatedList = [metaItem, ...existingList.filter((b: any) => b.id !== imported.id)];
      localStorage.setItem(STORAGE_KEY_BOARDS_LIST, JSON.stringify(updatedList));
      localStorage.setItem(STORAGE_KEY_ACTIVE_BOARD, imported.id);
    } catch (e) {
      console.warn('Local storage write failed for imported canvas:', e);
    }

    setBoards((prev) => [
      { id: imported.id, title: imported.title, updatedAt: new Date().toISOString(), nodeCount: pNodes.length },
      ...prev.filter((b) => b.id !== imported.id)
    ]);

    setActiveBoardId(imported.id);
    activeBoardIdRef.current = imported.id;
    setBoardTitle(imported.title);
    boardTitleRef.current = imported.title;
    setNodes(pNodes);
    setEdges(pEdges);
    nodesRef.current = pNodes;
    edgesRef.current = pEdges;

    historyRef.current = [{ nodes: toSerializableNodes(pNodes), edges: toSerializableEdges(pEdges) }];
    historyIndexRef.current = 0;
    updateHistoryState();

    setIsCreatePageActive(false);
    setAiToast({ message: `Imported canvas: "${imported.title}"`, count: pNodes.length });

    setTimeout(() => {
      fitView({ padding: 0.25, duration: 600 });
    }, 150);
  }, [prepareEdge, prepareNode, toSerializableEdges, toSerializableNodes, updateHistoryState, fitView, setNodes, setEdges]);

  // Open Create with Theologica AI start page whenever clicking the Canvas tab in navigation
  useEffect(() => {
    if (isInitialMountRef.current) {
      isInitialMountRef.current = false;
      try {
        const localList = localStorage.getItem(STORAGE_KEY_BOARDS_LIST);
        if (!localList || localList === '[]') {
          setIsCreatePageActive(true);
        }
      } catch {}
      return;
    }

    if (isActiveTab) {
      if (!incomingNode) {
        try {
          const localList = localStorage.getItem(STORAGE_KEY_BOARDS_LIST);
          if (!localList || localList === '[]') {
            setIsCreatePageActive(true);
          }
        } catch {}
      }
      if (typeof window !== 'undefined' && window.innerWidth >= 768) {
        setIsSidebarOpen(true);
      }
    }
  }, [focusTrigger, isActiveTab, incomingNode]);

  // Support ?importCanvas=... parameter and ?imported=1
  useEffect(() => {
    if (typeof window === 'undefined') return;
    try {
      const params = new URLSearchParams(window.location.search);
      const importCode = params.get('importCanvas');
      if (importCode) {
        fetch('/api/canvas/import', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ code: importCode }),
        })
          .then((res) => res.json())
          .then((data) => {
            if (data.board) {
              handleImportSuccess(data.board);
              window.history.replaceState({}, '', window.location.pathname + '?tab=canvas');
            }
          })
          .catch((err) => console.warn('Auto-import from URL parameter failed:', err));
      } else if (params.get('imported') === '1') {
        setIsCreatePageActive(false);
        window.history.replaceState({}, '', window.location.pathname + '?tab=canvas');
      }
    } catch {}
  }, [handleImportSuccess]);

  // Node & Edge types
  const nodeTypes = useMemo(() => ({ customCard: CustomCanvasNode }), []);
  const edgeTypes = useMemo(() => ({ customEdge: CustomCanvasEdge }), []);

  const nodesSummaryKey = useMemo(
    () => nodes.map((n) => `${n.id}:${n.data.title || ''}:${n.data.category || 'general'}`).join('|'),
    [nodes]
  );

  const nodesSummary = useMemo(
    () =>
      nodes.map((n) => ({
        id: n.id,
        title: n.data.title || 'Untitled Card',
        category: (n.data.category || 'general') as NodeCategory,
      })),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [nodesSummaryKey]
  );

  const nodeEnrichCacheRef = useRef<
    Map<
      string,
      {
        rawNode: Node<CanvasNodeData>;
        rawData: CanvasNodeData;
        summary: typeof nodesSummary;
        theme: string;
        enrichedData: CanvasNodeData;
        enrichedNode: Node<CanvasNodeData>;
      }
    >
  >(new Map());

  // Enrich live nodes with otherNodes summary list and callbacks while preserving object references during drag frames
  const displayNodes = useMemo(() => {
    const cache = nodeEnrichCacheRef.current;
    const nextCache = new Map<string, (typeof cache extends Map<string, infer V> ? V : never)>();

    const result = nodes.map((n) => {
      const cached = cache.get(n.id);
      const canReuseData =
        cached &&
        cached.rawData === n.data &&
        cached.summary === nodesSummary &&
        cached.theme === theme &&
        cached.enrichedData.onUpdate === handleUpdateNode &&
        cached.enrichedData.onDuplicate === handleDuplicateNode &&
        cached.enrichedData.onDelete === handleDeleteNode &&
        cached.enrichedData.onResizeEnd === handleResizeNodeEnd &&
        cached.enrichedData.onConnectTo === handleConnectTo &&
        cached.enrichedData.onSpawnCrossReferences === handleSpawnCrossReferences &&
        cached.enrichedData.onVerseClick === onNavigateToVerse;

      const enrichedData: CanvasNodeData = canReuseData
        ? cached.enrichedData
        : {
            ...n.data,
            theme,
            onUpdate: handleUpdateNode,
            onDuplicate: handleDuplicateNode,
            onDelete: handleDeleteNode,
            onResizeEnd: handleResizeNodeEnd,
            onConnectTo: handleConnectTo,
            onSpawnCrossReferences: handleSpawnCrossReferences,
            onVerseClick: onNavigateToVerse,
            otherNodes: nodesSummary.filter((s) => s.id !== n.id),
          };

      if (canReuseData && cached.rawNode === n) {
        nextCache.set(n.id, cached);
        return cached.enrichedNode;
      }

      const enrichedNode: Node<CanvasNodeData> = {
        ...n,
        style: n.style?.width
          ? n.style
          : {
              width: 380,
              ...n.style,
            },
        data: enrichedData,
      };

      nextCache.set(n.id, {
        rawNode: n,
        rawData: n.data,
        summary: nodesSummary,
        theme,
        enrichedData,
        enrichedNode,
      });

      return enrichedNode;
    });

    nodeEnrichCacheRef.current = nextCache;
    return result;
  }, [
    nodes,
    nodesSummary,
    theme,
    handleUpdateNode,
    handleDuplicateNode,
    handleDeleteNode,
    handleResizeNodeEnd,
    handleConnectTo,
    handleSpawnCrossReferences,
    onNavigateToVerse,
  ]);

  return (
    <div 
      ref={containerRef}
      className="relative w-full h-full overflow-hidden select-none flex flex-row bg-bg text-fg transition-colors duration-200"
      style={{
        backgroundColor: 'var(--bg)',
      }}
    >
      {/* Canvases Sidebar */}
      <CanvasSidebar
        isOpen={isSidebarOpen}
        onToggle={() => setIsSidebarOpen(!isSidebarOpen)}
        boards={boards}
        activeBoardId={activeBoardId}
        onSelectBoard={(id) => {
          handleSelectBoard(id);
          setIsCreatePageActive(false);
          if (typeof window !== 'undefined' && window.innerWidth < 1024) setIsSidebarOpen(false);
        }}
        onCreateBoard={() => {
          setIsCreatePageActive(true);
          if (typeof window !== 'undefined' && window.innerWidth < 1024) setIsSidebarOpen(false);
        }}
        onCreateFromScratch={() => {
          handleCreateBoard();
          setIsCreatePageActive(false);
          if (typeof window !== 'undefined' && window.innerWidth < 1024) setIsSidebarOpen(false);
        }}
        onRenameBoard={handleRenameBoard}
        onDeleteBoard={handleDeleteBoard}
        onOpenImportModal={() => {
          setIsImportModalOpen(true);
          if (typeof window !== 'undefined' && window.innerWidth < 1024) setIsSidebarOpen(false);
        }}
        theme={theme}
      />

      {/* Main Content Area */}
      <div
        ref={canvasWrapperRef}
        onTouchStart={handleTouchStartWrapper}
        onTouchMove={handleTouchMoveWrapper}
        onTouchEnd={handleTouchEndWrapper}
        onMouseDown={(e) => {
          if (e.button === 2) {
            rightClickStartPosRef.current = { x: e.clientX, y: e.clientY };
            isDraggingCanvasRef.current = false;
          } else if (e.button === 0) {
            if (paneContextMenu && contextMenuRef.current && !contextMenuRef.current.contains(e.target as HTMLElement)) {
              setPaneContextMenu(null);
            }
          }
        }}
        onMouseMove={(e) => {
          if (rightClickStartPosRef.current) {
            const dx = Math.abs(e.clientX - rightClickStartPosRef.current.x);
            const dy = Math.abs(e.clientY - rightClickStartPosRef.current.y);
            if (dx > 4 || dy > 4) {
              isDraggingCanvasRef.current = true;
              if (paneContextMenu) {
                setPaneContextMenu(null);
              }
            }
          }
        }}
        onMouseUp={(e) => {
          if (e.button === 2) {
            rightClickStartPosRef.current = null;
            setTimeout(() => {
              isDraggingCanvasRef.current = false;
            }, 100);
          }
        }}
        onContextMenu={(e) => {
          e.preventDefault();
          const target = e.target as HTMLElement;
          if (
            target.closest('.react-flow') &&
            !target.closest('.react-flow__node') &&
            !target.closest('.react-flow__edge') &&
            !target.closest('.react-flow__controls') &&
            !target.closest('.react-flow__minimap')
          ) {
            triggerPaneContextMenu(e.clientX, e.clientY);
          }
        }}
        className="flex-1 h-full relative overflow-hidden flex flex-col min-w-0"
      >
        {isCreatePageActive || (boards.length === 0 && !activeBoardId) ? (
          <CanvasStartPage
            onGenerateCanvas={handleGenerateFromStartPage}
            onCreateBlankCanvas={() => {
              handleCreateBoard();
              setIsCreatePageActive(false);
            }}
            onOpenImportModal={() => setIsImportModalOpen(true)}
            onSelectBoard={(id) => {
              handleSelectBoard(id);
              setIsCreatePageActive(false);
            }}
            onResumeActiveBoard={
              activeBoardId && nodes.length > 0
                ? () => setIsCreatePageActive(false)
                : undefined
            }
            activeBoard={
              activeBoardId
                ? { id: activeBoardId, title: boardTitle, nodeCount: nodes.length }
                : null
            }
            onOpenSidebar={() => setIsSidebarOpen(true)}
            isSidebarOpen={isSidebarOpen}
            isGenerating={isStartPageGenerating}
            generatingStep={startPageGeneratingStep}
            onCancelGeneration={() => {
              if (startPageAbortControllerRef.current) {
                startPageAbortControllerRef.current.abort();
                startPageAbortControllerRef.current = null;
              }
              setIsStartPageGenerating(false);
            }}
            theme={theme}
          />
        ) : (
          <>
          {/* Top Action Toolbar */}
          <CanvasToolbar
            boardTitle={boardTitle}
            onTitleChange={(t) => handleRenameBoard(activeBoardId, t)}
            onAddNode={handleAddNode}
            onOpenAi={() => setIsAiModalOpen(true)}
            onNewCanvas={() => setIsCreatePageActive(true)}
            onCreateFromScratch={() => {
              handleCreateBoard();
              setIsCreatePageActive(false);
            }}
            onCreateWithAi={() => {
              setIsCreatePageActive(true);
            }}
            onExportStudyGuide={() => setIsExportGuideOpen(true)}
            onShareBoard={() => setIsShareModalOpen(true)}
            onUndo={handleUndo}
            onRedo={handleRedo}
            canUndo={canUndo}
            canRedo={canRedo}
            onFitView={() => {
              if (containerRef.current && containerRef.current.clientWidth > 100) {
                fitView({ padding: 0.2, duration: 600, minZoom: 0.35, maxZoom: 1.1 });
              }
            }}
            onAutoArrange={handleAutoArrange}
            onClear={handleClear}
            isSidebarOpen={isSidebarOpen}
            onToggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)}
            saveStatus={saveStatus}
            onSave={handleManualSave}
            theme={theme}
            nodeCount={nodes.length}
            hasActiveBoard={Boolean(activeBoardId && boards.length > 0)}
            onCreateBoard={() => setIsCreatePageActive(true)}
          />

      {/* React Flow Canvas Engine */}
      <ReactFlow<Node<CanvasNodeData>, Edge>
        nodes={displayNodes}
        edges={edges}
        onNodesChange={onNodesChange}
        onEdgesChange={onEdgesChange}
        onConnect={onConnect}
        onNodeDragStart={() => {
          if (paneContextMenu) setPaneContextMenu(null);
        }}
        onNodeDragStop={onNodeDragStop}
        onNodesDelete={onNodesDelete}
        onEdgesDelete={onEdgesDelete}
        onMoveStart={() => {
          isDraggingCanvasRef.current = true;
          if (paneContextMenu) setPaneContextMenu(null);
        }}
        onMove={() => {
          isDraggingCanvasRef.current = true;
          if (paneContextMenu) setPaneContextMenu(null);
        }}
        onPaneContextMenu={(event) => {
          event.preventDefault();
          triggerPaneContextMenu(event.clientX, event.clientY);
        }}
        onSelectionContextMenu={(event) => {
          event.preventDefault();
          triggerPaneContextMenu(event.clientX, event.clientY);
        }}
        onPaneClick={() => {
          if (paneContextMenu) setPaneContextMenu(null);
        }}
        onMoveEnd={(event, viewport) => {
          if (viewport && typeof viewport.zoom === 'number' && viewport.zoom >= 0.2) {
            currentViewportRef.current = viewport;
          }
          setTimeout(() => {
            isDraggingCanvasRef.current = false;
          }, 100);
        }}
        nodeTypes={nodeTypes}
        edgeTypes={edgeTypes}
        minZoom={0.2}
        maxZoom={2.0}
        defaultViewport={{ x: isMobile ? 20 : 80, y: isMobile ? 40 : 60, zoom: isMobile ? 0.7 : 0.85 }}
        selectionMode={SelectionMode.Partial}
        panOnScroll={false}
        selectionOnDrag={false}
        selectionKeyCode="Shift"
        panOnDrag={true}
        zoomOnPinch={true}
        zoomOnScroll={true}
        zoomOnDoubleClick={false}
        preventScrolling={true}
        autoPanOnNodeDrag={true}
        autoPanOnConnect={true}
        proOptions={{ hideAttribution: true }}
        defaultEdgeOptions={{
          type: 'customEdge',
          animated: true,
        }}
        className="w-full h-full touch-none"
      >
        {/* Dot Grid */}
        <Background
          variant={BackgroundVariant.Dots}
          gap={20}
          size={1.5}
          color={isDark ? 'rgba(255, 255, 255, 0.12)' : 'rgba(0, 0, 0, 0.12)'}
        />

        {/* MiniMap - hidden on mobile to maximize touch canvas workspace */}
        {!isMobile && boards.length > 0 && nodes.length > 0 && (
          <MiniMap
            position="bottom-right"
            nodeStrokeWidth={3}
            nodeColor={(node) => {
              const cat = (node.data as any)?.category as NodeCategory;
              switch (cat) {
                case 'scripture': return '#F59E0B';
                case 'theological_point': return '#06B6D4';
                case 'historical_context': return '#8B5CF6';
                case 'illustration': return '#10B981';
                case 'application': return '#F43F5E';
                default: return isDark ? '#87867f' : '#b0aea5';
              }
            }}
            maskColor={isDark ? 'rgba(20, 20, 19, 0.75)' : 'rgba(250, 249, 245, 0.75)'}
            className="!rounded-xl !border !border-border shadow-xl !overflow-hidden !bg-surface"
            style={{ width: 160, height: 110 }}
          />
        )}

        {/* Zoom Controls */}
        {boards.length > 0 && (
          <Controls
            position="bottom-left"
            showInteractive={false}
            className="!rounded-xl !border !border-border shadow-xl !overflow-hidden mb-2 sm:mb-0 !bg-surface !text-fg [&>button]:!border-border [&>button]:!bg-surface [&>button]:!fill-fg hover:[&>button]:!bg-surface-hover hover:[&>button]:!text-fg"
          />
        )}
      </ReactFlow>

      {/* Canvas Pane Right-Click Context Menu */}
      {paneContextMenu && (
        <div
          ref={contextMenuRef}
          style={{ 
            left: isMobile && typeof window !== 'undefined' 
              ? Math.max(16, (window.innerWidth - 270) / 2)
              : Math.min(paneContextMenu.x, (typeof window !== 'undefined' ? window.innerWidth : 1200) - 270), 
            top: isMobile && typeof window !== 'undefined'
              ? Math.max(70, Math.min(paneContextMenu.y - 100, window.innerHeight - 380))
              : Math.min(paneContextMenu.y, (typeof window !== 'undefined' ? window.innerHeight : 800) - 400) 
          }}
          className="fixed z-50 w-64 rounded-2xl shadow-2xl border border-border p-2 animate-in fade-in-50 zoom-in-95 backdrop-blur-md select-none bg-surface/95 text-fg ring-1 ring-border/50"
          onClick={(e) => e.stopPropagation()}
        >
          <div className="text-xs font-bold text-muted uppercase tracking-wider px-3 py-1.5">
            Canvas Options
          </div>

          {boards.length === 0 ? (
            <div className="space-y-1">
              <button
                type="button"
                onClick={() => {
                  setPaneContextMenu(null);
                  handleCreateBoard();
                }}
                className="w-full flex items-center gap-2.5 px-3 py-2 rounded-xl text-sm font-medium transition-colors cursor-pointer hover:bg-surface-hover text-accent"
              >
                <Plus size={16} className="shrink-0" />
                <span>New Canvas Board</span>
              </button>

              <button
                type="button"
                onClick={() => {
                  setPaneContextMenu(null);
                  setIsAiModalOpen(true);
                }}
                className="w-full flex items-center gap-2.5 px-3 py-2 rounded-xl text-sm font-medium transition-colors cursor-pointer hover:bg-surface-hover text-accent"
              >
                <Sparkles size={16} className="text-accent shrink-0" />
                <span>Theologica AI</span>
              </button>
            </div>
          ) : (
            <>
              {/* Add Card Submenu */}
              <div>
                <button
                  type="button"
                  onClick={() => setPaneAddSubmenuOpen(!paneAddSubmenuOpen)}
                  className="w-full flex items-center justify-between px-3 py-2 rounded-xl text-sm font-medium transition-colors cursor-pointer hover:bg-surface-hover text-fg"
                >
                  <div className="flex items-center gap-2.5">
                    <Plus size={16} className="text-accent" />
                    <span>Add Card...</span>
                  </div>
                  <ChevronRight size={15} className={`text-muted transition-transform duration-150 ${paneAddSubmenuOpen ? 'rotate-90' : ''}`} />
                </button>

                {paneAddSubmenuOpen && (
                  <div className="my-1.5 py-1.5 pl-3 border-l-2 border-border space-y-1">
                    {(Object.keys(CATEGORY_METADATA) as NodeCategory[]).map((cat) => {
                      const meta = CATEGORY_METADATA[cat];
                      return (
                        <button
                          key={cat}
                          type="button"
                          onClick={() => {
                            const flowPos = screenToFlowPosition({ x: paneContextMenu.x, y: paneContextMenu.y });
                            handleAddNode(cat, flowPos);
                            setPaneContextMenu(null);
                          }}
                          className="w-full flex items-center gap-2.5 px-2.5 py-1.5 rounded-lg text-xs sm:text-sm font-medium transition-colors cursor-pointer text-left hover:bg-surface-hover text-fg"
                        >
                          <span className="w-2.5 h-2.5 rounded-full shrink-0 shadow-sm" style={{ backgroundColor: meta.accent }} />
                          <span>{meta.label}</span>
                        </button>
                      );
                    })}
                  </div>
                )}
              </div>

          {/* Theologica AI */}
          <button
            type="button"
            onClick={() => {
              setPaneContextMenu(null);
              setIsAiModalOpen(true);
            }}
            className="w-full flex items-center gap-2.5 px-3 py-2 rounded-xl text-sm font-medium transition-colors cursor-pointer hover:bg-surface-hover text-accent"
          >
            <Sparkles size={16} className="text-accent shrink-0" />
            <span>Theologica AI</span>
          </button>

          <div className="border-t my-1.5 border-border" />

          {/* Auto Arrange */}
          <button
            type="button"
            onClick={() => {
              setPaneContextMenu(null);
              handleAutoArrange();
            }}
            className="w-full flex items-center gap-2.5 px-3 py-2 rounded-xl text-sm font-medium transition-colors cursor-pointer hover:bg-surface-hover text-fg"
          >
            <LayoutGrid size={16} className="shrink-0 text-muted" />
            <span>Auto Arrange</span>
          </button>

          {/* Fit View */}
          <button
            type="button"
            onClick={() => {
              setPaneContextMenu(null);
              if (containerRef.current && containerRef.current.clientWidth > 100) {
                fitView({ padding: 0.2, duration: 600, minZoom: 0.35, maxZoom: 1.1 });
              }
            }}
            className="w-full flex items-center gap-2.5 px-3 py-2 rounded-xl text-sm font-medium transition-colors cursor-pointer hover:bg-surface-hover text-fg"
          >
            <Maximize2 size={16} className="shrink-0 text-muted" />
            <span>Fit to View</span>
          </button>

          <div className="border-t my-1.5 border-border" />

          {/* Undo */}
          <button
            type="button"
            disabled={!canUndo}
            onClick={() => {
              setPaneContextMenu(null);
              handleUndo();
            }}
            className={`w-full flex items-center justify-between px-3 py-2 rounded-xl text-sm font-medium transition-colors ${
              canUndo 
                ? 'hover:bg-surface-hover text-fg cursor-pointer'
                : 'opacity-40 cursor-not-allowed text-muted'
            }`}
          >
            <div className="flex items-center gap-2.5">
              <Undo2 size={16} className="shrink-0" />
              <span>Undo</span>
            </div>
            <span className="text-xs text-muted font-mono hidden sm:inline">{mod.symbol}Z</span>
          </button>

          {/* Redo */}
          <button
            type="button"
            disabled={!canRedo}
            onClick={() => {
              setPaneContextMenu(null);
              handleRedo();
            }}
            className={`w-full flex items-center justify-between px-3 py-2 rounded-xl text-sm font-medium transition-colors ${
              canRedo 
                ? 'hover:bg-surface-hover text-fg cursor-pointer'
                : 'opacity-40 cursor-not-allowed text-muted'
            }`}
          >
            <div className="flex items-center gap-2.5">
              <Redo2 size={16} className="shrink-0" />
              <span>Redo</span>
            </div>
            <span className="text-xs text-muted font-mono hidden sm:inline">{mod.symbol}{mod.shift}Z</span>
          </button>
        </>
      )}
    </div>
  )}

      {/* Floating Theologica AI Success Toast (Desktop only) */}
      {aiToast && !isMobile && (
        <div className="hidden sm:flex absolute bottom-6 left-1/2 -translate-x-1/2 z-40 items-center gap-3 px-4 py-2.5 rounded-2xl bg-surface/95 border border-accent/40 shadow-2xl text-xs text-fg backdrop-blur-md animate-in fade-in slide-in-from-bottom-3">
          <Sparkles size={15} className="text-accent shrink-0" />
          <span className="font-medium">{aiToast.message}</span>
          <button
            type="button"
            onClick={() => {
              handleUndo();
              setAiToast(null);
            }}
            className="flex items-center gap-1 px-2.5 py-1 rounded-lg bg-surface-warm hover:bg-border text-muted hover:text-fg transition-colors cursor-pointer text-xs font-medium border border-border"
          >
            <Undo2 size={12} />
            <span>Undo</span>
          </button>
        </div>
      )}
        </>
      )}
      </div>

      {/* Theologica AI Canvas Architect Modal */}
      <TheologicaAiCanvasModal
        isOpen={isAiModalOpen}
        onClose={() => setIsAiModalOpen(false)}
        currentGraph={currentGraphPayload}
        selectedNode={selectedNode}
        onApplyGraphUpdate={handleApplyAiGraph}
        theme={theme}
      />

      {/* Export Study Guide & Sermon Outline Modal */}
      <ExportStudyGuideModal
        isOpen={isExportGuideOpen}
        onClose={() => setIsExportGuideOpen(false)}
        boardTitle={boardTitle}
        nodes={nodes.map((n) => ({
          id: n.id,
          type: 'customCard',
          position: n.position,
          data: n.data,
          style: n.style,
        }))}
        edges={edges.map((e) => ({
          id: e.id,
          source: e.source,
          target: e.target,
          label: typeof e.label === 'string' ? e.label : undefined,
          animated: Boolean(e.animated),
        }))}
        theme={theme}
      />

      {/* Share Board Modal */}
      <ShareCanvasModal
        isOpen={isShareModalOpen}
        onClose={() => setIsShareModalOpen(false)}
        boardId={activeBoardId}
        boardTitle={boardTitle}
        nodeCount={nodes.length}
        theme={theme}
      />

      {/* Import Shared Canvas Modal */}
      <ImportCanvasModal
        isOpen={isImportModalOpen}
        onClose={() => setIsImportModalOpen(false)}
        onImportSuccess={handleImportSuccess}
        theme={theme}
      />

      {/* Clear Canvas Confirmation Modal */}
      <ConfirmModal
        isOpen={isClearConfirmOpen}
        title="Clear All Cards?"
        message="Are you sure you want to clear all cards on this board? You can undo this action with Cmd+Z / Ctrl+Z."
        confirmLabel="Clear Board"
        variant="danger"
        icon="trash"
        onConfirm={confirmClearBoard}
        onCancel={() => setIsClearConfirmOpen(false)}
      />
    </div>
  );
}

export function CanvasBoard(props: CanvasBoardProps) {
  return (
    <ReactFlowProvider>
      <InnerCanvasBoard {...props} />
    </ReactFlowProvider>
  );
}

"use client";

import React, { useState, useRef, useEffect } from 'react';
import { 
  Plus, 
  Workflow, 
  Trash2, 
  Edit2, 
  Check, 
  X, 
  Search, 
  PanelLeftClose, 
  Layers, 
  Clock, 
  ChevronRight,
  Download,
  ChevronDown,
  Sparkles
} from 'lucide-react';
import { CanvasBoardMetadata } from '@/types/canvas';
import { ConfirmModal } from '@/components/ui/ConfirmModal';

interface CanvasSidebarProps {
  isOpen: boolean;
  onToggle: () => void;
  boards: CanvasBoardMetadata[];
  activeBoardId: string;
  onSelectBoard: (id: string) => void;
  onCreateBoard: () => void;
  onCreateFromScratch?: () => void;
  onRenameBoard: (id: string, newTitle: string) => void;
  onDeleteBoard: (id: string) => void;
  onOpenImportModal?: () => void;
  theme: 'dark' | 'light';
}

export function CanvasSidebar({
  isOpen,
  onToggle,
  boards,
  activeBoardId,
  onSelectBoard,
  onCreateBoard,
  onCreateFromScratch,
  onRenameBoard,
  onDeleteBoard,
  onOpenImportModal,
  theme,
}: CanvasSidebarProps) {
  const [searchQuery, setSearchQuery] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editTitle, setEditTitle] = useState('');
  const [boardToDelete, setBoardToDelete] = useState<CanvasBoardMetadata | null>(null);
  const [isNewBoardMenuOpen, setIsNewBoardMenuOpen] = useState(false);
  const newBoardMenuRef = useRef<HTMLDivElement>(null);

  const isDark = theme === 'dark';

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (newBoardMenuRef.current && !newBoardMenuRef.current.contains(e.target as Node)) {
        setIsNewBoardMenuOpen(false);
      }
    };
    if (isNewBoardMenuOpen) {
      document.addEventListener('mousedown', handleClickOutside);
    }
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [isNewBoardMenuOpen]);

  const filteredBoards = boards.filter((b) =>
    (b.title || 'Untitled Canvas').toLowerCase().includes(searchQuery.toLowerCase())
  );

  const startRename = (b: CanvasBoardMetadata, e: React.MouseEvent) => {
    e.stopPropagation();
    setEditingId(b.id);
    setEditTitle(b.title);
  };

  const commitRename = (id: string) => {
    if (editTitle.trim()) {
      onRenameBoard(id, editTitle.trim());
    }
    setEditingId(null);
  };

  const formatTimestamp = (dateStr: string) => {
    try {
      const d = new Date(dateStr);
      if (isNaN(d.getTime())) return '';
      const now = new Date();
      const diffMs = now.getTime() - d.getTime();
      const diffMins = Math.floor(diffMs / 60000);
      const diffHours = Math.floor(diffMins / 60);
      const diffDays = Math.floor(diffHours / 24);

      if (diffMins < 2) return 'Just now';
      if (diffMins < 60) return `${diffMins}m ago`;
      if (diffHours < 24) return `${diffHours}h ago`;
      if (diffDays === 1) return 'Yesterday';
      if (diffDays < 7) return `${diffDays}d ago`;
      return d.toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
    } catch {
      return '';
    }
  };

  const touchStartXRef = useRef<number | null>(null);
  const touchStartYRef = useRef<number | null>(null);

  const handleTouchStart = (e: React.TouchEvent) => {
    if (e.touches.length === 1) {
      touchStartXRef.current = e.touches[0].clientX;
      touchStartYRef.current = e.touches[0].clientY;
    }
  };

  const handleTouchEnd = (e: React.TouchEvent) => {
    if (touchStartXRef.current === null || touchStartYRef.current === null) return;
    const deltaX = e.changedTouches[0].clientX - touchStartXRef.current;
    const deltaY = e.changedTouches[0].clientY - touchStartYRef.current;

    // Swiping right-to-left (towards the left edge) closes the left sidebar
    if (deltaX < -45 && Math.abs(deltaX) > Math.abs(deltaY) * 1.2) {
      onToggle();
    }
    touchStartXRef.current = null;
    touchStartYRef.current = null;
  };

  if (!isOpen) return null;

  return (
    <>
      {/* Mobile & Tablet backdrop overlay to tap-dismiss */}
      <div 
        onClick={onToggle}
        className="fixed inset-0 bg-black/50 z-30 lg:hidden animate-in fade-in duration-300"
        aria-hidden="true"
      />
      <aside 
        onTouchStart={handleTouchStart}
        onTouchEnd={handleTouchEnd}
        className="fixed lg:relative inset-y-0 left-0 z-40 lg:z-20 w-72 lg:w-[320px] h-full shrink-0 flex flex-col border-r lg:border-r border-border/80 bg-surface lg:bg-surface/20 lg:backdrop-blur-sm text-fg shadow-2xl lg:shadow-none transition-transform duration-300 ease-out animate-in slide-in-from-left"
      >
      {/* Sidebar Header */}
      <div className="min-h-[48px] lg:min-h-[56px] flex items-center justify-between px-3.5 sm:px-4 border-b border-border/70 bg-surface/30 backdrop-blur-sm shrink-0">
        <div className="flex items-center gap-2">
          <div className="w-7 h-7 rounded-lg bg-accent/15 text-accent border border-accent/20 flex items-center justify-center shadow-2xs">
            <Workflow size={15} />
          </div>
          <span className="text-xs sm:text-sm font-bold tracking-tight text-fg">Your Canvases</span>
        </div>
        <button
          type="button"
          onClick={onToggle}
          className="p-1.5 rounded-lg text-muted hover:text-fg hover:bg-surface/60 transition-colors cursor-pointer"
          title="Close Sidebar"
        >
          <PanelLeftClose size={16} />
        </button>
      </div>

      {/* Action Bar: New Board, Import & Search */}
      <div className="p-3 space-y-2 shrink-0 bg-surface/10">
        <div className="flex items-center gap-1.5 relative" ref={newBoardMenuRef}>
          <button
            type="button"
            onClick={() => setIsNewBoardMenuOpen(!isNewBoardMenuOpen)}
            className="flex-1 flex items-center justify-center gap-1.5 py-2 px-3 rounded-xl bg-accent text-accent-on text-xs font-semibold hover:opacity-90 active:scale-[0.98] transition-all shadow-xs cursor-pointer"
          >
            <Plus size={15} />
            <span>New Canvas</span>
            <ChevronDown size={13} className={`transition-transform duration-200 ${isNewBoardMenuOpen ? 'rotate-180' : ''}`} />
          </button>
          {onOpenImportModal && (
            <button
              type="button"
              onClick={onOpenImportModal}
              className="p-2 rounded-xl border border-border bg-bg/80 text-fg-2 hover:text-fg hover:bg-surface-hover text-xs font-semibold transition-all cursor-pointer shadow-xs"
              title="Import Shared Canvas by Link or Code"
            >
              <Download size={15} />
            </button>
          )}

          {isNewBoardMenuOpen && (
            <div className="absolute left-0 top-full mt-1.5 w-full rounded-2xl shadow-2xl border border-border bg-surface text-fg p-2 z-50 animate-in fade-in-50 zoom-in-95 ring-1 ring-border/50">
              <div className="text-[10px] font-bold text-muted uppercase tracking-wider px-2 py-1">
                New Canvas
              </div>
              <div className="space-y-1">
                <button
                  type="button"
                  onClick={() => {
                    setIsNewBoardMenuOpen(false);
                    if (onCreateFromScratch) onCreateFromScratch();
                    else onCreateBoard();
                  }}
                  className="w-full flex items-start gap-2 px-2.5 py-2 rounded-xl text-left hover:bg-surface-hover text-fg transition-colors cursor-pointer group"
                >
                  <div className="w-6 h-6 rounded-lg bg-surface border border-border flex items-center justify-center shrink-0 mt-0.5 text-muted group-hover:text-accent group-hover:border-accent/40 transition-colors">
                    <Plus size={13} />
                  </div>
                  <div className="min-w-0">
                    <div className="text-xs font-semibold text-fg">Make from Scratch</div>
                    <div className="text-[10px] text-muted leading-tight mt-0.5">Start with a blank canvas</div>
                  </div>
                </button>

                <button
                  type="button"
                  onClick={() => {
                    setIsNewBoardMenuOpen(false);
                    onCreateBoard();
                  }}
                  className="w-full flex items-start gap-2 px-2.5 py-2 rounded-xl text-left hover:bg-surface-hover text-fg transition-colors cursor-pointer group"
                >
                  <div className="w-6 h-6 rounded-lg bg-accent/15 border border-accent/30 flex items-center justify-center shrink-0 mt-0.5 text-accent shadow-xs">
                    <Sparkles size={13} />
                  </div>
                  <div className="min-w-0">
                    <div className="text-xs font-semibold text-fg flex items-center gap-1">
                      <span>Make with Theologica AI</span>
                      <span className="text-[8px] bg-accent/15 text-accent font-bold px-1 rounded-full">AI</span>
                    </div>
                    <div className="text-[10px] text-muted leading-tight mt-0.5">Generate study canvas from scripture</div>
                  </div>
                </button>
              </div>
            </div>
          )}
        </div>

        {/* Search */}
        <div className="flex items-center gap-2 px-2.5 py-1.5 rounded-xl border border-border bg-bg text-xs">
          <Search size={13} className="text-muted shrink-0" />
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="Search canvases..."
            className="bg-transparent focus:outline-none w-full placeholder:text-muted text-fg text-xs"
          />
          {searchQuery && (
            <button 
              type="button" 
              onClick={() => setSearchQuery('')}
              className="text-muted hover:text-fg cursor-pointer"
            >
              <X size={12} />
            </button>
          )}
        </div>
      </div>

      {/* Boards List */}
      <div className="flex-1 overflow-y-auto px-2 py-1 space-y-1 custom-scroll">
        <div className="px-2 py-1 text-[10px] font-bold text-zinc-400 uppercase tracking-wider flex items-center justify-between">
          <span>All Boards ({filteredBoards.length})</span>
        </div>

        {filteredBoards.length === 0 ? (
          searchQuery ? (
            <div className="py-8 text-center text-xs text-zinc-500 px-4">
              No boards matching &quot;{searchQuery}&quot;.
            </div>
          ) : (
            <div className="py-10 flex flex-col items-center justify-center text-center px-4 space-y-3">
              <div className="w-10 h-10 rounded-xl bg-accent/15 text-accent flex items-center justify-center">
                <Workflow size={20} />
              </div>
              <div>
                <p className="text-xs font-semibold text-fg">No canvas boards yet</p>
                <p className="text-[11px] text-muted mt-1">Start fresh with a blank canvas.</p>
              </div>
              <button
                type="button"
                onClick={() => onCreateBoard()}
                className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-accent text-accent-on text-xs font-semibold hover:opacity-90 transition-all cursor-pointer shadow-xs active:scale-95"
              >
                <Plus size={13} />
                <span>Create Canvas</span>
              </button>
            </div>
          )
        ) : (
          filteredBoards.map((board) => {
            const isActive = board.id === activeBoardId;
            const isEditing = editingId === board.id;

            return (
              <div
                key={board.id}
                onClick={() => {
                  if (!isEditing) onSelectBoard(board.id);
                }}
                className={`group relative flex flex-col px-3 py-2.5 rounded-xl border text-xs transition-all cursor-pointer ${
                  isActive
                    ? 'bg-surface-warm/90 border-accent/60 shadow-xs ring-1 ring-accent/30 text-fg font-medium'
                    : 'border-transparent hover:bg-surface-hover text-fg-2 hover:text-fg'
                }`}
              >
                {/* Active strip indicator */}
                {isActive && (
                  <div className="absolute left-0 top-2.5 bottom-2.5 w-1 rounded-r-full bg-accent" />
                )}

                <div className="flex items-center justify-between gap-2">
                  <div className="flex items-center gap-2 flex-1 min-w-0">
                    <Workflow 
                      size={14} 
                      className={`shrink-0 ${isActive ? 'text-accent' : 'text-muted'}`} 
                    />

                    {isEditing ? (
                      <div className="flex items-center gap-1 flex-1" onClick={(e) => e.stopPropagation()}>
                        <input
                          type="text"
                          value={editTitle}
                          onChange={(e) => setEditTitle(e.target.value)}
                          onKeyDown={(e) => {
                            if (e.key === 'Enter') commitRename(board.id);
                            if (e.key === 'Escape') setEditingId(null);
                          }}
                          autoFocus
                          className="w-full px-1.5 py-0.5 rounded border border-border bg-bg text-fg text-xs font-semibold focus:outline-none focus:ring-1 focus:ring-accent"
                        />
                        <button
                          type="button"
                          onClick={() => commitRename(board.id)}
                          className="p-1 rounded bg-accent text-accent-on hover:opacity-90"
                        >
                          <Check size={11} />
                        </button>
                      </div>
                    ) : (
                      <span className="font-semibold truncate text-[13px] text-fg">
                        {board.title || 'Untitled Canvas'}
                      </span>
                    )}
                  </div>

                  {/* Actions on hover/active */}
                  {!isEditing && (
                    <div className="flex items-center gap-1 opacity-80 sm:opacity-0 group-hover:opacity-100 transition-opacity shrink-0">
                      <button
                        type="button"
                        onClick={(e) => startRename(board, e)}
                        className="p-1 rounded hover:bg-surface-warm text-muted hover:text-fg transition-colors"
                        title="Rename canvas"
                      >
                        <Edit2 size={12} />
                      </button>
                      <button
                        type="button"
                        onClick={(e) => {
                          e.stopPropagation();
                          setBoardToDelete(board);
                        }}
                        className="p-1 rounded hover:bg-rose-500/20 text-muted hover:text-rose-400 cursor-pointer transition-colors"
                        title="Delete canvas"
                      >
                        <Trash2 size={12} />
                      </button>
                    </div>
                  )}
                </div>

                {/* Subtitle / Metadata */}
                <div className="flex items-center justify-between text-[11px] text-muted mt-1 pl-5">
                  <div className="flex items-center gap-1">
                    <Layers size={11} />
                    <span>{board.nodeCount ?? 0} {board.nodeCount === 1 ? 'card' : 'cards'}</span>
                  </div>
                  {board.updatedAt && (
                    <span className="text-[10px] text-muted font-mono">
                      {formatTimestamp(board.updatedAt)}
                    </span>
                  )}
                </div>
              </div>
            );
          })
        )}
      </div>

      {/* Footer info */}
      <div className="p-3 border-t border-border/70 bg-surface/25 text-[11px] text-muted flex items-center justify-between shrink-0">
        <span>Canvas Workspace</span>
        <span className="font-mono text-[10px] text-meta">{boards.length} {boards.length === 1 ? 'Board' : 'Boards'}</span>
      </div>
    </aside>

    {/* Delete Canvas Confirmation Modal */}
    <ConfirmModal
      isOpen={boardToDelete !== null}
      title="Delete Canvas Board?"
      message={`Are you sure you want to delete "${boardToDelete?.title || 'Untitled Canvas'}"? All cards and connections on this board will be removed.`}
      confirmLabel="Delete Canvas"
      variant="danger"
      icon="trash"
      onConfirm={() => {
        if (boardToDelete) {
          onDeleteBoard(boardToDelete.id);
          setBoardToDelete(null);
        }
      }}
      onCancel={() => setBoardToDelete(null)}
    />
  </>
  );
}

"use client";

import React, { useState, useRef, useEffect } from 'react';
import TextareaAutosize from 'react-textarea-autosize';
import { 
  Sparkles, 
  Workflow, 
  Network, 
  FileText, 
  BookOpen, 
  Plus, 
  Download, 
  ArrowRight, 
  PanelLeft,
  CheckCircle2, 
  Loader2, 
  X, 
  AlertCircle,
  Lightbulb
} from 'lucide-react';
import { validateBiblePrompt } from '@/lib/bibleValidation';

export type CanvasMode = 'generate' | 'discourse' | 'synthesize';

interface CanvasStartPageProps {
  onGenerateCanvas: (prompt: string, mode: CanvasMode, lens: string) => Promise<void>;
  onCreateBlankCanvas: () => void;
  onOpenImportModal: () => void;
  onSelectBoard: (boardId: string) => void;
  onResumeActiveBoard?: () => void;
  activeBoard?: { id: string; title: string; nodeCount: number } | null;
  onOpenSidebar: () => void;
  isSidebarOpen?: boolean;
  isGenerating: boolean;
  generatingStep: number;
  onCancelGeneration: () => void;
  theme: 'dark' | 'light';
}

const PRESET_IDEAS = [
  { label: "Romans 8:28-30 (Golden Chain)", query: "Map Romans 8:28-30 (The Golden Chain of Redemption) with scripture, doctrinal implications, and applications" },
  { label: "Covenant of Grace", query: "Theological structure and biblical progression of the Covenant of Grace across the Old and New Testaments" },
  { label: "Beatitudes in Matthew 5", query: "Mind-map of the Beatitudes in Matthew 5 with kingdom virtues and modern Christian applications" },
  { label: "Philippians 2:5-11 (Christ Hymn)", query: "Logic diagram of Philippians 2:5-11 from humiliation to exaltation" },
];

const DISCOURSE_IDEAS = [
  { label: "Romans 8:28-39 (Sovereignty to Glory)", query: "Discourse analysis of Romans 8:28-39 diagramming Paul's logical chain from foreknowledge to eternal security" },
  { label: "Ephesians 2:1-10 (Grace & Calling)", query: "Argument flowchart of Ephesians 2:1-10 diagramming condition of sin, divine intervention ('But God'), and grace unto good works" },
  { label: "Galatians 3:1-14 (Faith vs Law)", query: "Discourse tree of Paul's argument in Galatians 3 contrasting works of the law with the promise to Abraham" },
];

export function CanvasStartPage({
  onGenerateCanvas,
  onCreateBlankCanvas,
  onOpenImportModal,
  onResumeActiveBoard,
  activeBoard,
  onOpenSidebar,
  isSidebarOpen = true,
  isGenerating,
  generatingStep,
  onCancelGeneration,
  theme,
}: CanvasStartPageProps) {
  const isDark = theme === 'dark';
  const [prompt, setPrompt] = useState('');
  const [mode, setMode] = useState<CanvasMode>('generate');
  const [selectedLens, setSelectedLens] = useState<'standard' | 'canonical' | 'patristic' | 'reformation' | 'scholarly' | 'contemplative'>('standard');
  const [validationError, setValidationError] = useState<string | null>(null);
  const textareaRef = useRef<HTMLTextAreaElement | null>(null);

  useEffect(() => {
    // Only auto-focus on desktop devices to avoid opening the virtual keyboard or triggering mobileTyping focus handlers on mobile
    if (!isGenerating && typeof window !== 'undefined' && window.innerWidth >= 1024) {
      const timer = setTimeout(() => {
        textareaRef.current?.focus();
      }, 100);
      return () => clearTimeout(timer);
    }
  }, [isGenerating, mode]);

  const handleStartSubmit = (overridePrompt?: string) => {
    const finalPrompt = (overridePrompt || prompt).trim();
    if (!finalPrompt || isGenerating) return;

    const validation = validateBiblePrompt(finalPrompt, mode);
    if (!validation.isValid) {
      setValidationError(validation.error || 'Please enter a topic, question, or passage related to Scripture.');
      return;
    }

    setValidationError(null);
    onGenerateCanvas(finalPrompt, mode, selectedLens);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      if (e.nativeEvent.isComposing || (e as any).keyCode === 229) {
        return;
      }
      handleStartSubmit();
    }
  };

  const MILESTONES = [
    "Searching Scripture passages & context...",
    "Finding cross-references & key verses...",
    "Creating study cards...",
    "Arranging cards on your board...",
  ];

  return (
    <div 
      className="w-full h-full overflow-y-auto custom-scroll flex flex-col justify-between p-4 sm:p-6 md:p-8 select-none animate-in fade-in duration-200 bg-bg text-fg pt-3 lg:pt-6"
      style={{
        backgroundColor: 'var(--bg)',
      }}
    >
      {/* Top Bar Navigation */}
      <div className="w-full flex items-center justify-between shrink-0 mb-4">
        {/* Toggle Canvases Sidebar (if collapsed or mobile) */}
        {!isSidebarOpen ? (
          <button
            type="button"
            onClick={onOpenSidebar}
            className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl border border-border bg-surface text-fg-2 hover:text-fg hover:bg-surface-hover text-xs font-semibold transition-all cursor-pointer shadow-xs"
            title="Open Canvases Sidebar"
          >
            <PanelLeft size={14} className="text-accent" />
            <span>Your Canvases</span>
          </button>
        ) : (
          <div />
        )}

        {/* Return to Open Canvas (if active) */}
        {activeBoard && activeBoard.nodeCount > 0 && onResumeActiveBoard && !isGenerating && (
          <button
            type="button"
            onClick={onResumeActiveBoard}
            className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl border border-accent/40 bg-accent/10 text-accent hover:bg-accent/20 text-xs font-semibold transition-all cursor-pointer shadow-xs ml-auto"
          >
            <Workflow size={13} className="text-accent shrink-0" />
            <span className="truncate max-w-[180px] sm:max-w-xs">Return to &quot;{activeBoard.title}&quot;</span>
            <ArrowRight size={12} className="shrink-0" />
          </button>
        )}
      </div>

      {/* Main Center Area */}
      <div className="w-full max-w-2xl mx-auto my-auto flex flex-col items-center space-y-6">
        {isGenerating ? (
          /* HUD GENERATION STATE */
          <div 
            className="w-full max-w-lg rounded-2xl border border-border bg-surface text-fg p-6 sm:p-8 flex flex-col items-center text-center space-y-6 shadow-2xl backdrop-blur-md animate-in fade-in zoom-in-95"
          >
            <div className="relative flex items-center justify-center w-16 h-16">
              <div className="absolute inset-0 rounded-2xl bg-accent/15 border border-accent/30 animate-pulse" />
              <div className="w-10 h-10 rounded-xl bg-accent/20 text-accent border border-accent/40 flex items-center justify-center shadow-xs">
                <Sparkles size={20} className="animate-pulse text-accent" />
              </div>
            </div>

            <div className="space-y-1">
              <h3 className="text-base font-bold tracking-tight">
                Building Your Canvas
              </h3>
              <p className="text-xs text-accent font-medium">
                {MILESTONES[generatingStep] || 'Finalizing cards and connections...'}
              </p>
            </div>

            <div className={`w-full p-3.5 rounded-xl border text-xs text-left space-y-2.5 ${
              isDark ? 'bg-zinc-900/60 border-zinc-800' : 'bg-zinc-50 border-zinc-200'
            }`}>
              {MILESTONES.map((m, idx) => {
                const isDone = idx < generatingStep;
                const isCurrent = idx === generatingStep;
                return (
                  <div 
                    key={idx} 
                    className={`flex items-center gap-2.5 transition-all duration-300 ${
                      isDone ? 'text-emerald-500 font-medium' : isCurrent ? 'text-accent font-semibold' : 'text-zinc-500'
                    }`}
                  >
                    {isDone ? (
                      <CheckCircle2 size={14} className="shrink-0 text-emerald-500" />
                    ) : isCurrent ? (
                      <Loader2 size={14} className="shrink-0 animate-spin text-accent" />
                    ) : (
                      <div className="w-3.5 h-3.5 rounded-full border border-zinc-400 dark:border-zinc-700 shrink-0 ml-0.5" />
                    )}
                    <span className="truncate">{m}</span>
                  </div>
                );
              })}
            </div>

            <button
              type="button"
              onClick={onCancelGeneration}
              className="px-3.5 py-1.5 rounded-xl text-xs font-semibold text-zinc-400 hover:text-zinc-100 hover:bg-zinc-800 border border-zinc-700 transition-all flex items-center gap-1.5 cursor-pointer shadow-xs active:scale-95"
            >
              <X size={13} />
              <span>Cancel</span>
            </button>
          </div>
        ) : (
          /* CLEAN START VIEW */
          <>
            {/* Hero Header */}
            <div className="flex flex-col items-center text-center space-y-2 px-2">
              <div className="w-11 h-11 rounded-2xl bg-accent/15 border border-accent/30 text-accent flex items-center justify-center shadow-xs">
                <Sparkles size={20} className="text-accent" />
              </div>
              <h1 className="text-xl sm:text-2xl font-bold tracking-tight text-fg">
                Create a Study Board
              </h1>
              <p className="text-xs sm:text-sm text-muted max-w-md leading-relaxed">
                Explore Scripture passages, themes, and study notes on a visual whiteboard.
              </p>
            </div>

            {/* Unified Input Card */}
            <div 
              className="w-full rounded-2xl border border-border bg-surface text-fg focus-within:border-accent/80 focus-within:ring-2 focus-within:ring-accent/15 shadow-xl p-3.5 sm:p-4 space-y-3 transition-all duration-200"
            >
              {/* Architecture Mode Selector Pills */}
              <div className="space-y-2 pb-2.5 border-b border-border-soft/60">
                <div className="flex items-center gap-1.5 overflow-x-auto no-scrollbar">
                  {[
                    { id: 'generate', label: 'Mind-Map', icon: Network },
                    { id: 'discourse', label: 'Logic Flowchart', icon: Workflow },
                    { id: 'synthesize', label: 'Topic Synthesis', icon: FileText },
                  ].map((m) => {
                    const Icon = m.icon;
                    const isSelected = mode === m.id;
                    return (
                      <button
                        key={m.id}
                        type="button"
                        onClick={() => setMode(m.id as CanvasMode)}
                        className={`flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-medium transition-all cursor-pointer whitespace-nowrap ${
                          isSelected
                            ? 'bg-accent text-accent-on font-semibold shadow-xs'
                            : 'text-fg-2 hover:text-fg hover:bg-surface-hover bg-surface/40 border border-border/40'
                        }`}
                      >
                        <Icon size={13} />
                        <span>{m.label}</span>
                      </button>
                    );
                  })}
                </div>

                {/* Clear 1-sentence mode explainer */}
                <p className="text-[11.5px] text-muted leading-relaxed px-0.5">
                  {mode === 'generate' && 'Mind-Map: Explores central passages, theological connections, and practical study applications.'}
                  {mode === 'discourse' && 'Logic Flowchart: Traces the step-by-step biblical arguments, conditional logic, and doctrinal progressions.'}
                  {mode === 'synthesize' && 'Topic Synthesis: Gathers multiple biblical passages to synthesize key doctrines, historic context, and takeaways.'}
                </p>
              </div>

              {/* Study Prompt Textarea */}
              <TextareaAutosize
                ref={textareaRef}
                minRows={3}
                maxRows={6}
                value={prompt}
                onChange={(e) => {
                  setPrompt(e.target.value);
                  if (validationError) setValidationError(null);
                }}
                onKeyDown={handleKeyDown}
                placeholder={
                  mode === 'discourse'
                    ? "e.g. Diagram the logical argument and flow of Romans 8:28-39 or Galatians 3:1-14..."
                    : mode === 'synthesize'
                    ? "e.g. Synthesize the key doctrines and study takeaways on the Covenant of Grace..."
                    : "e.g. Map Romans 8:28-30 (The Golden Chain) with scripture, doctrinal implications, and applications..."
                }
                className="w-full bg-transparent text-sm text-fg placeholder:text-muted focus:outline-none resize-none leading-relaxed block"
              />

              {/* Bottom Row inside Card */}
              <div className="flex items-center justify-between pt-2 border-t border-border-soft/60 gap-2 flex-wrap">
                {/* Tradition Lens Selector Dropdown */}
                <div className="flex items-center gap-1.5 text-xs text-muted">
                  <BookOpen size={13} className="text-accent shrink-0" />
                  <span className="hidden sm:inline font-medium">Tradition:</span>
                  <select
                    value={selectedLens}
                    onChange={(e) => setSelectedLens(e.target.value as any)}
                    className="text-xs font-medium px-2 py-1 rounded-lg border border-border text-fg bg-surface-warm focus:outline-none cursor-pointer"
                  >
                    <option value="standard">General (Balanced)</option>
                    <option value="canonical">Canonical Biblical</option>
                    <option value="patristic">Patristic & Early Church</option>
                    <option value="reformation">Reformed & Protestant</option>
                    <option value="scholarly">Scholarly & Exegetical</option>
                    <option value="contemplative">Devotional & Formational</option>
                  </select>
                </div>

                {/* Submit button & shortcut */}
                <div className="flex items-center gap-2">
                  <span className="text-[11px] text-muted hidden sm:inline">Press ↵ Enter</span>
                  <button
                    type="button"
                    onClick={() => handleStartSubmit()}
                    disabled={!prompt.trim()}
                    className="flex items-center gap-2 px-5 py-2.5 rounded-xl bg-accent text-accent-on text-xs font-bold hover:opacity-95 disabled:opacity-40 disabled:hover:opacity-40 active:scale-95 transition-all shadow-md cursor-pointer"
                  >
                    <Sparkles size={15} />
                    <span>Create Board</span>
                  </button>
                </div>
              </div>
            </div>

            {/* Validation Error Message */}
            {validationError && (
              <div className="w-full flex items-center gap-2 p-3 rounded-xl bg-rose-500/10 border border-rose-500/30 text-rose-400 text-xs">
                <AlertCircle size={14} className="shrink-0" />
                <span>{validationError}</span>
              </div>
            )}

            {/* Sample Inspiration Chips */}
            <div className="flex flex-wrap items-center justify-center gap-1.5 max-w-xl">
              <span className="text-[11px] text-muted mr-1 flex items-center gap-1">
                <Lightbulb size={12} className="text-amber-500" /> Ideas:
              </span>
              {(mode === 'discourse' ? DISCOURSE_IDEAS : PRESET_IDEAS).map((item, idx) => (
                <button
                  key={idx}
                  type="button"
                  onClick={() => {
                    setPrompt(item.query);
                    handleStartSubmit(item.query);
                  }}
                  className="text-[11px] px-2.5 py-1 rounded-full border border-border bg-surface text-fg-2 hover:border-accent/60 hover:text-accent transition-all cursor-pointer shadow-2xs"
                >
                  {item.label}
                </button>
              ))}
            </div>

            {/* Subtle Secondary Actions */}
            <div className="flex items-center justify-center gap-3 pt-1 text-xs text-muted">
              <button
                type="button"
                onClick={onCreateBlankCanvas}
                className="flex items-center gap-1.5 hover:text-accent transition-colors cursor-pointer"
              >
                <Plus size={13} />
                <span>Blank Canvas</span>
              </button>
              <span>·</span>
              <button
                type="button"
                onClick={onOpenImportModal}
                className="flex items-center gap-1.5 hover:text-accent transition-colors cursor-pointer"
              >
                <Download size={13} />
                <span>Import Shared Canvas</span>
              </button>
            </div>
          </>
        )}
      </div>

      {/* Empty bottom spacer for symmetrical vertical centering */}
      <div className="shrink-0 h-4" />
    </div>
  );
}

