            <Plus size={16} />
            {showAddCardText && <span>Add Card</span>}
            <ChevronDown size={13} className={`transition-transform duration-200 ${isAddMenuOpen ? 'rotate-180' : ''}`} />
          </button>

          {isAddMenuOpen && (
