                      className="w-full flex items-center justify-between px-3.5 py-2.5 min-h-[44px] rounded-xl text-sm font-medium transition-colors cursor-pointer hover:bg-surface-hover text-fg"
                    >
                      <div className="flex items-center gap-2.5">
                        <span 
                          className="w-3 h-3 rounded-full shrink-0 shadow-sm" 
                          style={{ backgroundColor: meta.accent }}
                        />
                        <span>{cat === 'scripture' ? 'Scripture Verse...' : meta.label}</span>
                      </div>
                      <Icon size={15} className="text-muted shrink-0" />
                    </button>
                  );
                })}
              </div>
            </div>
          )}
        </div>

        {/* New Canvas Dropdown Button (Shown in bar when space allows) */}
        {showNewCanvasInBar && (
          <div className="relative" ref={newCanvasMenuRef}>
            <button
