                <div className="space-y-1">
                  {/* Make from Scratch */}
                  <button
                    type="button"
                    onClick={() => {
                      setIsNewCanvasMenuOpen(false);
                      if (onCreateFromScratch) onCreateFromScratch();
                      else if (onCreateBoard) onCreateBoard();
