                {/* Export Study Guide (when collapsed from bar) */}
                {!showStudyGuideInBar && hasExportStudyGuide && (
                  <button
                    type="button"
                    onClick={() => {
                      setIsMoreMenuOpen(false);
                      onExportStudyGuide?.();
