                    <span>Export Study Guide</span>
                  </button>
                )}

                {/* Share Canvas (when collapsed from bar) */}
                {!showShareInBar && hasShareBoard && (
                  <button
                    type="button"
                    onClick={() => {
                      setIsMoreMenuOpen(false);
                      onShareBoard?.();
                    }}
