                    className={`w-full flex items-center gap-2.5 px-3 py-2 rounded-xl text-xs font-medium transition-colors ${
                      hasActiveBoard 
                        ? 'hover:bg-surface-hover text-fg cursor-pointer'
                        : 'opacity-30 cursor-not-allowed text-muted'
