"use client";

import React, { useState, useEffect } from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { 
  X, 
  Sparkles, 
  Copy, 
  Check, 
  Download, 
  Printer, 
  Loader2, 
  FileText, 
  Users, 
  Scroll, 
  Edit3, 
  Eye,
  BookOpen
} from 'lucide-react';
import { SerializableNode, SerializableEdge } from '@/types/canvas';

interface ExportStudyGuideModalProps {
  isOpen: boolean;
  onClose: () => void;
  boardTitle: string;
  nodes: SerializableNode[];
  edges?: SerializableEdge[];
  theme: 'dark' | 'light';
}

type GuideFormat = 'sermon' | 'small_group' | 'exegetical';
type LensType = 'canonical' | 'patristic' | 'reformation' | 'scholarly' | 'contemplative';

const FORMAT_OPTIONS: { id: GuideFormat; label: string; icon: React.ElementType; description: string }[] = [
  {
    id: 'sermon',
    label: 'Expository Sermon',
    icon: FileText,
    description: 'Title, big idea, homiletical points (I, II, III), illustrations, and practical call to action.',
  },
  {
    id: 'small_group',
    label: 'Small Group Discussion',
    icon: Users,
    description: 'Icebreaker, scripture reading, observation, interpretation questions, and prayer focus.',
  },
  {
    id: 'exegetical',
    label: 'Exegetical Brief',
    icon: Scroll,
    description: 'Original languages, grammatical flow of thought, and doctrinal synthesis.',
  },
];

const LENS_OPTIONS: { id: LensType; label: string; icon: string }[] = [
  { id: 'canonical', label: 'Canonical / Balanced', icon: '🕊️' },
  { id: 'patristic', label: 'Early Church Fathers', icon: '🏛️' },
  { id: 'reformation', label: 'Reformation Heritage', icon: '📜' },
  { id: 'scholarly', label: 'Modern Scholarly', icon: '🔍' },
  { id: 'contemplative', label: 'Contemplative Prayer', icon: '🌿' },
];

export function ExportStudyGuideModal({
  isOpen,
  onClose,
  boardTitle,
  nodes,
  edges,
  theme,
}: ExportStudyGuideModalProps) {
  const isDark = theme === 'dark';
  const [selectedFormat, setSelectedFormat] = useState<GuideFormat>('sermon');
  const [selectedLens, setSelectedLens] = useState<LensType>('canonical');
  const [generatedMarkdown, setGeneratedMarkdown] = useState<string>('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [copied, setCopied] = useState(false);

  // Auto-generate initial guide on modal open if empty
  useEffect(() => {
    if (isOpen && !generatedMarkdown && nodes.length > 0) {
      handleGenerate();
    }
  }, [isOpen]);

  if (!isOpen) return null;

  const handleGenerate = async (format = selectedFormat, lens = selectedLens) => {
    setIsGenerating(true);
    try {
      const res = await fetch('/api/canvas/export-guide', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          boardTitle,
          nodes,
          edges,
          format,
          theologicalLens: lens,
        }),
      });

      if (!res.ok) {
        throw new Error('Failed to generate study guide');
      }

      const data = await res.json();
      setGeneratedMarkdown(data.content || '');
    } catch (err) {
      console.error(err);
    } finally {
      setIsGenerating(false);
    }
  };

  const handleCopy = () => {
    if (!generatedMarkdown) return;
    navigator.clipboard.writeText(generatedMarkdown);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleDownload = () => {
    if (!generatedMarkdown) return;
    const blob = new Blob([generatedMarkdown], { type: 'text/markdown;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    const safeName = (boardTitle || 'theologica-study-guide')
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/(^-|-$)/g, '');
    link.href = url;
    link.download = `${safeName}-${selectedFormat}.md`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center modal-safe-overlay bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
      <div 
        className="w-full max-w-4xl max-h-[90vh] flex flex-col rounded-2xl shadow-2xl border border-border bg-surface text-fg overflow-hidden backdrop-blur-xl transition-all"
      >
        {/* Header */}
        <div className="flex items-center justify-between px-5 py-4 border-b border-border">
          <div className="flex items-center gap-2.5">
            <div className="p-2 rounded-xl bg-accent/15 text-accent border border-accent/20">
              <FileText size={18} />
            </div>
            <div>
              <h2 className="text-base sm:text-lg font-bold leading-tight flex items-center gap-2 text-fg">
                Export Study Guide &amp; Sermon Outline
                <span className="text-xs px-2 py-0.5 rounded-full font-semibold bg-emerald-500/15 text-emerald-500 border border-emerald-500/30">
                  {nodes.length} Cards
                </span>
              </h2>
              <p className="text-xs text-muted">
                Turn your study cards into a clean study guide, sermon outline, or discussion sheet.
              </p>
            </div>
          </div>

          <button
            type="button"
            onClick={onClose}
            className="p-1.5 rounded-lg text-muted hover:text-fg hover:bg-surface-hover transition-colors cursor-pointer"
          >
            <X size={18} />
          </button>
        </div>

        {/* Configuration Bar */}
        <div className="px-5 py-3 border-b border-border bg-surface-warm/40 flex flex-wrap items-center justify-between gap-3">
          {/* Format Selector Pills */}
          <div className="flex items-center flex-wrap gap-1.5">
            {FORMAT_OPTIONS.map((fmt) => {
              const Icon = fmt.icon;
              const isSelected = selectedFormat === fmt.id;
              return (
                <button
                  key={fmt.id}
                  type="button"
                  onClick={() => {
                    setSelectedFormat(fmt.id);
                    handleGenerate(fmt.id, selectedLens);
                  }}
                  className={`flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-semibold transition-all cursor-pointer border ${
                    isSelected
                      ? 'bg-accent text-accent-on border-accent shadow-xs'
                      : 'bg-surface border-border text-muted hover:bg-surface-hover hover:text-fg'
                  }`}
                  title={fmt.description}
                >
                  <Icon size={14} />
                  <span>{fmt.label}</span>
                </button>
              );
            })}
          </div>

          {/* Lens Selector */}
          <div className="flex items-center gap-2">
            <span className="text-xs text-muted font-medium">Lens:</span>
            <select
              value={selectedLens}
              onChange={(e) => {
                const lens = e.target.value as LensType;
                setSelectedLens(lens);
                handleGenerate(selectedFormat, lens);
              }}
              className="text-xs font-medium rounded-lg px-2.5 py-1.5 border border-border bg-surface text-fg focus:outline-none focus:ring-1 focus:ring-accent cursor-pointer"
            >
              {LENS_OPTIONS.map((l) => (
                <option key={l.id} value={l.id}>
                  {l.icon} {l.label}
                </option>
              ))}
            </select>

            <button
              type="button"
              onClick={() => handleGenerate(selectedFormat, selectedLens)}
              disabled={isGenerating}
              className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-surface border border-border hover:bg-surface-hover text-fg text-xs font-semibold transition-colors cursor-pointer"
              title="Regenerate guide"
            >
              {isGenerating ? <Loader2 size={13} className="animate-spin" /> : <Sparkles size={13} className="text-accent" />}
              <span>Regenerate</span>
            </button>
          </div>
        </div>

        {/* Content Area */}
        <div className="flex-1 overflow-y-auto p-5 sm:p-6 custom-scroll">
          {isGenerating ? (
            <div className="h-64 flex flex-col items-center justify-center gap-3">
              <Loader2 size={32} className="animate-spin text-accent" />
              <p className="text-sm font-medium text-muted animate-pulse">
                Writing {selectedFormat.replace('_', ' ')} from your {nodes.length} cards...
              </p>
            </div>
          ) : isEditing ? (
            <textarea
              value={generatedMarkdown}
              onChange={(e) => setGeneratedMarkdown(e.target.value)}
              className="w-full h-96 p-4 rounded-xl font-sans text-sm leading-relaxed focus:outline-none focus:ring-1 focus:ring-accent resize-none bg-bg border border-border text-fg"
              placeholder="Edit study guide directly..."
            />
          ) : (
            <div className={`prose max-w-none break-words text-fg ${isDark ? 'prose-invert' : ''}`}>
              <ReactMarkdown remarkPlugins={[remarkGfm]}>
                {generatedMarkdown || '# No content generated yet.\nClick **Regenerate** above.'}
              </ReactMarkdown>
            </div>
          )}
        </div>

        {/* Footer Actions */}
        <div className="flex items-center justify-between flex-wrap gap-2 px-5 py-3.5 border-t border-border bg-surface-warm/30">
          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={() => setIsEditing(!isEditing)}
              className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-medium transition-colors cursor-pointer border ${
                isEditing
                  ? 'bg-accent/15 border-accent/30 text-accent font-semibold'
                  : 'border-border text-muted hover:text-fg hover:bg-surface-hover'
              }`}
            >
              {isEditing ? <Eye size={14} /> : <Edit3 size={14} />}
              <span>{isEditing ? 'Preview' : 'Edit Text'}</span>
            </button>
          </div>

          <div className="flex items-center flex-wrap gap-2">
            <button
              type="button"
              onClick={handlePrint}
              disabled={!generatedMarkdown || isGenerating}
              className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl border border-border text-muted hover:text-fg hover:bg-surface-hover text-xs font-semibold transition-colors cursor-pointer"
              title="Print or export as clean PDF"
            >
              <Printer size={14} />
              <span className="hidden sm:inline">Print / PDF</span>
            </button>

            <button
              type="button"
              onClick={handleDownload}
              disabled={!generatedMarkdown || isGenerating}
              className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl border border-border text-muted hover:text-fg hover:bg-surface-hover text-xs font-semibold transition-colors cursor-pointer"
              title="Download as .md file"
            >
              <Download size={14} />
              <span className="hidden sm:inline">Download</span>
            </button>

            <button
              type="button"
              onClick={handleCopy}
              disabled={!generatedMarkdown || isGenerating}
              className={`flex items-center gap-1.5 px-4 py-1.5 rounded-xl text-xs font-semibold transition-all cursor-pointer shadow-sm ${
                copied
                  ? 'bg-emerald-600 text-white'
                  : 'bg-accent text-accent-on hover:opacity-90 active:scale-95'
              }`}
            >
              {copied ? <Check size={14} /> : <Copy size={14} />}
              <span>{copied ? 'Copied!' : 'Copy'}</span>
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import React, { useState } from 'react';
import { 
  X, 
  Download, 
  Loader2, 
  AlertCircle, 
  Check, 
  Clipboard, 
  Globe, 
  Workflow 
} from 'lucide-react';

interface ImportCanvasModalProps {
  isOpen: boolean;
  onClose: () => void;
  onImportSuccess: (board: {
    id: string;
    title: string;
    nodes: any[];
    edges: any[];
    viewport?: any;
  }) => void;
  theme: 'dark' | 'light';
}

export function ImportCanvasModal({
  isOpen,
  onClose,
  onImportSuccess,
  theme,
}: ImportCanvasModalProps) {
  const [codeOrLink, setCodeOrLink] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  if (!isOpen) return null;

  const isDark = theme === 'dark';

  const handlePaste = async () => {
    try {
      const text = await navigator.clipboard.readText();
      if (text) {
        setCodeOrLink(text.trim());
        setError(null);
      }
    } catch {
      // Clipboard read permission denied or unavailable
    }
  };

  const handleImport = async () => {
    const raw = codeOrLink.trim();
    if (!raw || isLoading) return;

    setIsLoading(true);
    setError(null);

    try {
      const res = await fetch('/api/canvas/import', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ code: raw }),
      });

      const data = await res.json();

      if (!res.ok) {
        throw new Error(data.error || 'Failed to import canvas board.');
      }

      if (!data.board) {
        throw new Error('Canvas board data was not returned by server.');
      }

      onImportSuccess(data.board);
      onClose();
    } catch (err: any) {
      console.error('Import canvas failed:', err);
      setError(err?.message || 'Could not find or import canvas board. Please verify the link or code.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center modal-safe-overlay bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
      <div 
        className="w-full max-w-md rounded-2xl shadow-2xl border border-border bg-surface text-fg p-5 sm:p-6 backdrop-blur-xl transition-all"
      >
        {/* Header */}
        <div className="flex items-start justify-between gap-3 mb-4">
          <div className="flex items-center gap-2.5">
            <div className="p-2 rounded-xl bg-accent/15 text-accent border border-accent/20">
              <Download size={18} />
            </div>
            <div>
              <h2 className="text-base sm:text-lg font-bold text-fg">
                Import Shared Canvas
              </h2>
              <p className="text-xs text-muted">
                Save an interactive study canvas from a link or code into your account.
              </p>
            </div>
          </div>

          <button
            type="button"
            onClick={onClose}
            className="p-1.5 rounded-lg text-muted hover:text-fg hover:bg-surface-hover transition-colors cursor-pointer"
          >
            <X size={17} />
          </button>
        </div>

        {/* Form Body */}
        <div className="space-y-3.5 mb-5">
          <div className="space-y-1.5">
            <label className="text-xs font-semibold text-muted flex items-center justify-between">
              <span>Canvas Link or Share Code:</span>
              <button
                type="button"
                onClick={handlePaste}
                className="text-[11px] text-accent hover:underline flex items-center gap-1 cursor-pointer"
              >
                <Clipboard size={12} />
                <span>Paste from Clipboard</span>
              </button>
            </label>
            <div className="relative flex items-center">
              <input
                type="text"
                value={codeOrLink}
                onChange={(e) => {
                  setCodeOrLink(e.target.value);
                  if (error) setError(null);
                }}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') {
                    e.preventDefault();
                    handleImport();
                  }
                }}
                placeholder="e.g. board-1727458291024 or https://.../share/canvas/..."
                className="w-full px-3.5 py-2.5 rounded-xl border border-border bg-bg text-fg text-xs font-mono focus:outline-none focus:ring-2 focus:ring-accent/40 focus:border-accent transition-all placeholder:text-muted"
                autoFocus
              />
            </div>
          </div>

          {error && (
            <div className="flex items-center gap-2 p-3 rounded-xl bg-rose-500/10 border border-rose-500/30 text-rose-400 text-xs">
              <AlertCircle size={15} className="shrink-0" />
              <span>{error}</span>
            </div>
          )}

          <div className="p-3 rounded-xl bg-surface-warm/40 border border-border text-[11px] text-muted space-y-1">
            <p>• Creates an independent, editable copy on your canvas board.</p>
            <p>• Your personal edits will not alter the original shared canvas.</p>
          </div>
        </div>

        {/* Footer Actions */}
        <div className="flex items-center justify-end gap-2 pt-2 border-t border-border">
          <button
            type="button"
            onClick={onClose}
            className="px-4 py-2 rounded-xl text-xs font-medium text-muted hover:text-fg hover:bg-surface-hover transition-colors cursor-pointer"
          >
            Cancel
          </button>
          <button
            type="button"
            onClick={handleImport}
            disabled={!codeOrLink.trim() || isLoading}
            className="flex items-center gap-1.5 px-5 py-2 rounded-xl bg-accent text-accent-on text-xs font-semibold hover:opacity-90 disabled:opacity-40 disabled:hover:opacity-40 active:scale-95 transition-all shadow-xs cursor-pointer"
          >
            {isLoading ? (
              <>
                <Loader2 size={14} className="animate-spin" />
                <span>Importing Canvas...</span>
              </>
            ) : (
              <>
                <Download size={14} />
                <span>Import Canvas</span>
              </>
            )}
          </button>
        </div>
      </div>
    </div>
  );
}

"use client";

import React, { useState } from 'react';
import { 
  X, 
  Share2, 
  Copy, 
  Check, 
  ExternalLink, 
  Globe, 
  Code2, 
  Lock, 
  Sparkles,
  Layers
} from 'lucide-react';

interface ShareCanvasModalProps {
  isOpen: boolean;
  onClose: () => void;
  boardId: string;
  boardTitle: string;
  nodeCount: number;
  theme: 'dark' | 'light';
}

export function ShareCanvasModal({
  isOpen,
  onClose,
  boardId,
  boardTitle,
  nodeCount,
  theme,
}: ShareCanvasModalProps) {
  const isDark = theme === 'dark';
  const [copiedLink, setCopiedLink] = useState(false);
  const [copiedCode, setCopiedCode] = useState(false);
  const [copiedEmbed, setCopiedEmbed] = useState(false);

  React.useEffect(() => {
    if (isOpen && boardId) {
      fetch('/api/canvas', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id: boardId, isPublic: true }),
      }).catch(() => {});
    }
  }, [isOpen, boardId]);

  if (!isOpen) return null;

  const origin = typeof window !== 'undefined' ? window.location.origin : '';
  const shareUrl = `${origin}/share/canvas/${boardId}`;
  const embedSnippet = `<iframe src="${shareUrl}" width="100%" height="600" frameborder="0" allowfullscreen></iframe>`;

  const handleCopyLink = () => {
    navigator.clipboard.writeText(shareUrl);
    setCopiedLink(true);
    setTimeout(() => setCopiedLink(false), 2000);
  };

  const handleCopyCode = () => {
    navigator.clipboard.writeText(boardId);
    setCopiedCode(true);
    setTimeout(() => setCopiedCode(false), 2000);
  };

  const handleNativeShare = async () => {
    if (typeof navigator !== 'undefined' && navigator.share) {
      try {
        await navigator.share({
          title: `Theologica Canvas: ${boardTitle}`,
          text: `Check out this visual scripture study board "${boardTitle}" on Theologica:`,
          url: shareUrl,
        });
      } catch (err) {
        // User dismissed share
      }
    } else {
      handleCopyLink();
    }
  };

  const handleCopyEmbed = () => {
    navigator.clipboard.writeText(embedSnippet);
    setCopiedEmbed(true);
    setTimeout(() => setCopiedEmbed(false), 2000);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center modal-safe-overlay bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
      <div 
        className="w-full max-w-lg rounded-2xl shadow-2xl border border-border bg-surface text-fg p-5 sm:p-6 backdrop-blur-xl transition-all"
      >
        {/* Header */}
        <div className="flex items-start justify-between gap-3 mb-4">
          <div className="flex items-center gap-2.5">
            <div className="p-2 rounded-xl bg-accent/15 text-accent border border-accent/20">
              <Share2 size={18} />
            </div>
            <div>
              <h2 className="text-base sm:text-lg font-bold text-fg">
                Share Canvas Board
              </h2>
              <p className="text-xs text-muted">
                Share your visual scripture study with your congregation, class, or small group.
              </p>
            </div>
          </div>

          <button
            type="button"
            onClick={onClose}
            className="p-1.5 rounded-lg text-muted hover:text-fg hover:bg-surface-hover transition-colors cursor-pointer"
          >
            <X size={17} />
          </button>
        </div>

        {/* Board Meta Badge */}
        <div className="p-3 rounded-xl bg-surface-warm/50 border border-border mb-5 flex items-center justify-between">
          <div className="flex items-center gap-2 min-w-0">
            <Layers size={16} className="text-accent shrink-0" />
            <span className="text-sm font-semibold truncate text-fg">{boardTitle || 'Untitled Canvas'}</span>
          </div>
          <span className="text-[11px] font-semibold px-2 py-0.5 rounded-full bg-accent/15 text-accent border border-accent/30 shrink-0">
            {nodeCount} Cards
          </span>
        </div>

        {/* Shareable Link Input */}
        <div className="space-y-1.5 mb-3.5">
          <div className="flex items-center justify-between">
            <label className="text-xs font-semibold text-muted flex items-center gap-1.5">
              <Globe size={13} className="text-accent" />
              <span>Shareable Canvas Link</span>
            </label>
            <span className="text-[11px] text-muted">Recipients can view & import</span>
          </div>
          <div className="flex items-center gap-2">
            <input
              type="text"
              readOnly
              value={shareUrl}
              className="flex-1 px-3 py-2 text-xs font-mono rounded-xl border border-border bg-bg text-fg focus:outline-none select-all"
            />
            <button
              type="button"
              onClick={handleCopyLink}
              className={`px-3 py-2 rounded-xl text-xs font-semibold flex items-center gap-1.5 transition-all cursor-pointer shadow-sm shrink-0 ${
                copiedLink 
                  ? 'bg-emerald-600 text-white' 
                  : 'bg-accent text-accent-on hover:opacity-90 active:scale-95'
              }`}
            >
              {copiedLink ? <Check size={14} /> : <Copy size={14} />}
              <span>{copiedLink ? 'Copied Link!' : 'Copy Link'}</span>
            </button>
            <button
              type="button"
              onClick={handleNativeShare}
              className="p-2 rounded-xl text-xs font-semibold border border-border hover:bg-surface-hover text-fg transition-colors flex items-center gap-1 cursor-pointer shrink-0"
              title="Share via device options..."
            >
              <Share2 size={14} />
            </button>
          </div>
        </div>

        {/* Share Code Section */}
        <div className="space-y-1.5 mb-4 p-3 rounded-xl bg-surface-warm/40 border border-border">
          <div className="flex items-center justify-between">
            <span className="text-[11px] font-semibold text-muted">Canvas Share Code:</span>
            <span className="text-[11px] text-emerald-500 font-medium">Use in Canvas &gt; Import</span>
          </div>
          <div className="flex items-center justify-between gap-2 mt-1">
            <code className="text-xs font-mono font-bold text-accent px-2 py-1 rounded-md bg-accent/10 border border-accent/20 truncate">
              {boardId}
            </code>
            <button
              type="button"
              onClick={handleCopyCode}
              className="px-2.5 py-1 rounded-lg text-xs font-medium border border-border hover:bg-surface-hover text-fg transition-colors flex items-center gap-1 cursor-pointer shrink-0"
            >
              {copiedCode ? <Check size={12} className="text-emerald-500" /> : <Copy size={12} />}
              <span>{copiedCode ? 'Copied' : 'Copy Code'}</span>
            </button>
          </div>
          <p className="text-[11px] text-muted mt-1">
            Other users can paste this code or link to save this canvas directly to their own account.
          </p>
        </div>

        {/* Embed Snippet */}
        <div className="space-y-1.5 mb-4">
          <label className="text-xs font-semibold text-muted flex items-center gap-1.5">
            <Code2 size={13} />
            <span>Embed on Website or Blog (iFrame)</span>
          </label>
          <div className="flex items-center gap-2">
            <input
              type="text"
              readOnly
              value={embedSnippet}
              className="flex-1 px-3 py-2 text-xs font-mono rounded-xl border border-border bg-bg text-fg focus:outline-none select-all"
            />
            <button
              type="button"
              onClick={handleCopyEmbed}
              className="px-3 py-2 rounded-xl text-xs font-semibold border border-border hover:bg-surface-hover text-fg transition-colors flex items-center gap-1.5 cursor-pointer shrink-0"
            >
              {copiedEmbed ? <Check size={14} className="text-emerald-500" /> : <Copy size={14} />}
              <span>{copiedEmbed ? 'Copied!' : 'Copy'}</span>
            </button>
          </div>
        </div>

        {/* Footer Info */}
        <div className="pt-3 border-t border-border flex items-center justify-between flex-wrap gap-2 text-xs text-muted">
          <div className="flex items-center gap-1.5">
            <Globe size={13} className="text-emerald-500 shrink-0" />
            <span className="break-words">Anyone with the link can explore this board.</span>
          </div>

          <a
            href={shareUrl}
            target="_blank"
            rel="noreferrer"
            className="flex items-center gap-1 text-accent hover:underline font-semibold shrink-0"
          >
            <span>Open Preview</span>
            <ExternalLink size={12} />
          </a>
        </div>
      </div>
    </div>
  );
}

