"use client";

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Sparkles, 
  BookOpen, 
  Scroll, 
  Heart, 
  Palette, 
  Languages, 
  Cross,
  Compass,
  ArrowRight
} from 'lucide-react';
import { TheologicalLensType, THEOLOGICAL_LENS_OPTIONS } from './TheologicalLensSelector';

