  activeBook?: { name: string; chapters: number };
  activeChapter?: number;
  translation?: string;
  theologicalLens?: TheologicalLensType;
  onSelectPrompt: (promptText: string) => void;
  onSelectLens?: (lens: TheologicalLensType) => void;
  isCompact?: boolean;
}

interface QuestionItem {
  prompt: string;
  subtitle: string;
  icon?: string;
}

