                    <h4 className="text-[11.5px] font-medium text-fg group-hover:text-accent leading-snug line-clamp-1 transition-colors">
                      {item.title}
                    </h4>

                    {/* Contextual Snippet */}
                    <p className="text-[10px] text-muted/75 leading-relaxed line-clamp-2 mt-0.5">
                      {item.snippet}
                    </p>
                  </div>
                </a>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
};

