        </div>

        {/* Continuous Linear Progress Bar (Smooth Animated Accent) */}
        <div className="w-full h-1.5 bg-bg/80 relative overflow-hidden border-b border-border/60">
          <div 
            className="h-full bg-accent transition-all duration-500 ease-out shadow-[0_0_8px_rgba(201,100,66,0.6)]"
            style={{ width: `${progressPercent}%` }}
          />
        </div>

        {/* Segmented Clickable Step Pills */}
        <div className="px-5 pt-3 pb-1 bg-surface/40 border-b border-border/40 flex items-center gap-1.5 overflow-x-auto no-scrollbar">
          {TUTORIAL_STEPS.map((s, idx) => {
            const isCurrent = currentStep === idx;
            const isPast = currentStep > idx;
            return (
              <button
                key={idx}
                type="button"
                onClick={() => setCurrentStep(idx)}
                className={`flex-1 min-w-[70px] py-1 px-1.5 rounded-lg text-center text-[10.5px] font-semibold transition-all cursor-pointer flex items-center justify-center gap-1 border ${
                  isCurrent
                    ? 'bg-accent text-accent-on border-accent shadow-xs'
                    : isPast
                    ? 'bg-accent/10 text-accent border-accent/25 hover:bg-accent/20'
                    : 'bg-surface/60 text-muted border-border/60 hover:text-fg hover:bg-surface'
                }`}
                title={`Jump to Step ${idx + 1}: ${s.title}`}
              >
                {isPast ? (
                  <Check size={11} className="stroke-[2.5]" />
                ) : (
                  <span>{idx + 1}.</span>
                )}
                <span className="truncate">{s.shortLabel}</span>
              </button>
            );
          })}
        </div>

        {/* Step Content with Smooth Animation */}
        <div 
          key={currentStep}
          className="p-6 space-y-5 overflow-y-auto max-h-[calc(85vh-160px)] custom-scroll animate-in fade-in slide-in-from-right-3 duration-300"
        >
          {/* Mockup Preview Area */}
          <div className="w-full">
            {step.mockup}
          </div>

          {/* Step Description */}
          <div className="space-y-2">
            <div className="flex items-center gap-2">
              {step.icon}
              <h3 className="text-base sm:text-lg font-bold text-fg font-serif">
                {step.title}
              </h3>
            </div>
            <p className="text-xs sm:text-[13px] text-meta leading-relaxed">
              {step.content}
            </p>
          </div>

          {/* Quick Tips Box */}
          <div className="p-3.5 rounded-2xl bg-surface-warm/30 border border-border/60 space-y-2">
            <span className="text-[10.5px] font-bold uppercase tracking-wider text-accent">
              Pro-Tips &amp; Shortcuts:
            </span>
            <ul className="space-y-1 text-xs text-fg/90">
              {step.tips.map((tip, idx) => (
                <li key={idx} className="flex items-center gap-2">
                  <CheckCircle2 size={12} className="text-emerald-500 shrink-0" />
                  <span>{tip}</span>
                </li>
              ))}
            </ul>
          </div>
        </div>

        {/* Footer Navigation Bar */}
        <div className="px-5 sm:px-6 py-3.5 border-t border-border/70 flex items-center justify-between bg-surface/60">
          {/* Step Counter Indicator */}
          <div className="text-xs text-muted font-medium flex items-center gap-1.5">
            <span>Step</span>
            <span className="font-bold text-fg">{currentStep + 1}</span>
            <span>of</span>
            <span className="font-bold text-fg">{TUTORIAL_STEPS.length}</span>
          </div>

          {/* Navigation Buttons */}
          <div className="flex items-center gap-2">
            {currentStep > 0 && (
              <button
                type="button"
                onClick={() => setCurrentStep((prev) => Math.max(prev - 1, 0))}
                className="inline-flex items-center gap-1 px-3.5 py-1.5 rounded-xl bg-surface border border-border text-xs font-semibold text-fg hover:text-accent hover:border-accent/40 active:scale-95 transition-all cursor-pointer"
              >
                <ChevronLeft size={14} />
                <span>Back</span>
              </button>
            )}

            {currentStep < TUTORIAL_STEPS.length - 1 ? (
              <button
                type="button"
                onClick={() => setCurrentStep((prev) => Math.min(prev + 1, TUTORIAL_STEPS.length - 1))}
                className="inline-flex items-center gap-1.5 px-4 py-1.5 rounded-xl bg-accent text-accent-on text-xs font-semibold hover:opacity-95 active:scale-95 transition-all shadow-xs cursor-pointer"
              >
                <span>Next Step</span>
                <ChevronRight size={14} />
              </button>
            ) : (
              <button
                type="button"
                onClick={onClose}
                className="inline-flex items-center gap-1.5 px-4 py-1.5 rounded-xl bg-accent text-accent-on text-xs font-semibold hover:opacity-95 active:scale-95 transition-all shadow-xs cursor-pointer"
              >
                <span>Got It! Start Studying</span>
                <ArrowRight size={14} />
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import React, { useState, useEffect } from 'react';
import { 
  X, 
  BookOpen, 
  Copy, 
  Check, 
  ExternalLink, 
  Loader2 
} from 'lucide-react';
import { getPassage } from '@/lib/bibleProvider';

interface VersePreviewPopupProps {
  reference: {
    book: string;
    chapter: number;
    verse: number;
    raw?: string;
  } | null;
  onClose: () => void;
  onNavigateToBible: (book: string, chapter: number, verse: number) => void;
  defaultTranslation?: string;
}

export function VersePreviewPopup({
  reference,
  onClose,
  onNavigateToBible,
  defaultTranslation = 'bsb',
}: VersePreviewPopupProps) {
  const [translation, setTranslation] = useState(defaultTranslation);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [passageText, setPassageText] = useState<string>('');
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    if (!reference) return;

    let isMounted = true;
    async function loadVerse() {
      if (!reference) return;
      setLoading(true);
      setError(null);
      try {
        const result = await getPassage(translation, reference.book, reference.chapter, reference.verse);
        if (!isMounted) return;

        if (result.verse) {
          setPassageText(result.verse.text.replace(/\[\d+\]/g, '').replace(/\{[^}]+\}/g, '').trim());
        } else if (result.chapter && result.chapter.verses.length > 0) {
          const v = result.chapter.verses.find(item => item.verse === reference.verse) || result.chapter.verses[0];
          setPassageText(v.text.replace(/\[\d+\]/g, '').replace(/\{[^}]+\}/g, '').trim());
        } else {
          setError('Scripture text not found.');
        }
      } catch (err: any) {
        if (!isMounted) return;
        console.warn('VersePreviewPopup error:', err);
        setError(`Could not load ${reference.book} ${reference.chapter}:${reference.verse}`);
      } finally {
        if (isMounted) setLoading(false);
      }
    }

    loadVerse();
    return () => { isMounted = false; };
  }, [reference, translation]);

  if (!reference) return null;

  const displayRef = `${reference.book} ${reference.chapter}:${reference.verse}`;

  const handleCopy = () => {
    const textToCopy = `"${passageText}" — ${displayRef} (${translation.toUpperCase()})`;
    navigator.clipboard.writeText(textToCopy);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div 
      className="fixed inset-0 z-50 flex items-center justify-center modal-safe-overlay bg-black/60 backdrop-blur-sm animate-in fade-in duration-200"
      onClick={onClose}
    >
      <div 
        className="bg-bg border border-border rounded-2xl w-full max-w-lg shadow-2xl overflow-hidden flex flex-col"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <header className="px-5 py-3.5 border-b border-border flex items-center justify-between bg-surface/40">
          <div className="flex items-center gap-2.5">
            <div className="w-8 h-8 rounded-lg bg-accent/10 border border-accent/20 flex items-center justify-center text-accent">
              <BookOpen size={16} />
            </div>
            <div>
              <h3 className="text-[15px] font-semibold text-fg flex items-center gap-2">
                <span>{displayRef}</span>
              </h3>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <select
              value={translation}
              onChange={(e) => setTranslation(e.target.value)}
              className="bg-surface border border-border/80 px-2 py-1 rounded-lg text-[12px] font-semibold text-fg focus:outline-none cursor-pointer"
            >
              <option value="bsb">BSB</option>
              <option value="kjv">KJV</option>
              <option value="web">WEB</option>
            </select>
            <button
              onClick={onClose}
              className="p-1.5 text-muted hover:text-fg hover:bg-surface rounded-lg transition-colors cursor-pointer"
            >
              <X size={16} />
            </button>
          </div>
        </header>

        {/* Content */}
        <div className="p-6 overflow-y-auto max-h-[300px] custom-scroll">
          {loading && (
            <div className="py-8 flex flex-col items-center justify-center text-muted gap-2">
              <Loader2 size={20} className="animate-spin text-accent" />
              <p className="text-[12px]">Loading Scripture...</p>
            </div>
          )}

          {error && !loading && (
            <p className="text-rose-500 text-[13px] bg-rose-500/10 border border-rose-500/30 p-3 rounded-lg">
              {error}
            </p>
          )}

          {!loading && !error && passageText && (
            <div className="space-y-3">
              <blockquote className="border-l-[3px] border-accent pl-4 py-1 italic text-fg text-[16px] leading-[1.8] font-serif">
                "{passageText}"
              </blockquote>
              <div className="text-right text-[12px] font-medium text-meta">
                — {displayRef} ({translation.toUpperCase()})
              </div>
            </div>
          )}
        </div>

        {/* Footer */}
        <footer className="px-5 py-3 border-t border-border flex items-center justify-between bg-surface/30">
          <button
            onClick={handleCopy}
            className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-[12px] font-medium text-fg-hover hover:bg-surface border border-border transition-colors cursor-pointer"
          >
            {copied ? <Check size={14} className="text-emerald-500" /> : <Copy size={14} />}
            <span>{copied ? 'Copied' : 'Copy'}</span>
          </button>

          <button
            onClick={() => {
              onNavigateToBible(reference.book, reference.chapter, reference.verse);
              onClose();
            }}
            className="flex items-center gap-1.5 px-3.5 py-1.5 rounded-lg text-[12px] font-semibold text-white bg-accent hover:opacity-90 transition-all shadow-xs cursor-pointer"
          >
            <span>Open in Bible Reader</span>
            <ExternalLink size={13} />
          </button>
        </footer>
      </div>
    </div>
  );
}

"use client";

// Client-side analytics tracker
// Strict Privacy: Only operational eventType and high-level safe tags are transmitted.
// ZERO user text, personal notes, or chat messages are EVER tracked.

export function getClientAnonId(): string {
  if (typeof window === 'undefined') return 'anon';
  try {
    // 1. Check persistent cookie first
    const match = document.cookie.match(/(^|;)\s*th_vid=([^;]+)/);
    if (match && match[2] && match[2].length > 4) {
      return decodeURIComponent(match[2]);
    }

    // 2. Check localStorage
    let id = localStorage.getItem('th_anon_id');
    if (!id || id.length < 5) {
      id = 'vid_' + Math.random().toString(36).substring(2, 10) + Date.now().toString(36);
      localStorage.setItem('th_anon_id', id);
    }

    // Ensure 1-year cookie is synced
    try {
      document.cookie = `th_vid=${encodeURIComponent(id)}; path=/; max-age=31536000; SameSite=Lax`;
    } catch {
      // Ignore cookie errors
    }

    return id;
  } catch {
    return 'anon';
  }
}

export function trackClientEvent(
  eventType: string,
  metadata?: Record<string, any>,
  userId?: string | null
) {
  if (typeof window === 'undefined') return;

  try {
    const payload = {
      eventType,
      anonymousId: getClientAnonId(),
      userId: userId || undefined,
      metadata,
    };

    const jsonStr = JSON.stringify(payload);

    // Prefer fetch with keepalive to guarantee headers and cookies are sent
    fetch('/api/analytics/track', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: jsonStr,
      keepalive: true,
      credentials: 'same-origin',
    }).catch(() => {
      if (navigator.sendBeacon) {
        const blob = new Blob([jsonStr], { type: 'application/json' });
        navigator.sendBeacon('/api/analytics/track', blob);
      }
    });
  } catch {
    // Telemetry must never crash or affect user experience
  }
}

/**
 * Initializes session tracking once per browser tab session.
 */
export function initSessionTracking(userId?: string | null) {
  if (typeof window === 'undefined') return;
  try {
    const hasTrackedSession = sessionStorage.getItem('th_session_started');
    if (!hasTrackedSession) {
      sessionStorage.setItem('th_session_started', 'true');
      trackClientEvent(
        'session_start',
        {
          platform: window.innerWidth < 768 ? 'mobile' : 'desktop',
        },
        userId
      );
    }
  } catch {
    // Ignore storage errors
  }
}

import crypto from 'crypto';
import prisma from '@/lib/prisma';

export interface RawAnalyticsEvent {
  id: string;
  eventType: string;
  anonymousId: string;
  metadata?: any;
  timestamp: Date;
}

// In-memory ring buffer for fallback when DB is unreachable or during development
const MAX_MEMORY_EVENTS = 2000;
const memoryEvents: RawAnalyticsEvent[] = [];

/**
 * Anonymize user identifier deterministically to ensure zero PII is stored
 * while preserving consistent unique-visitor counting (1 visitor across multiple sessions).
 */
export function anonymizeIdentifier(rawId: string): string {
  const cleanId = (rawId || 'unknown_guest').trim();
  const salt = process.env.ANALYTICS_SALT || 'theologica_analytics_anonymizer_salt';
  return 'usr_' + crypto.createHash('sha256').update(cleanId + salt).digest('hex').substring(0, 12);
}

/**
 * Record an anonymized operational event.
 * Strictly strips any potential user text/content.
 */
export async function recordAnalyticsEvent(
  eventType: string,
  rawAnonymousId: string,
  metadata?: Record<string, any>
): Promise<void> {
  // Privacy Guardrail: Ensure no personal content keys exist
  const safeMetadata: Record<string, any> = {};
  if (metadata && typeof metadata === 'object') {
    // Only allow specific approved operational flags
    const allowedKeys = ['feature', 'screen', 'action', 'mode', 'translation', 'platform', 'path', 'book', 'chapter', 'streak', 'habit'];
    for (const key of allowedKeys) {
      if (metadata[key] !== undefined && typeof metadata[key] !== 'object') {
        safeMetadata[key] = String(metadata[key]).substring(0, 50); // limit string length
      }
    }
  }

  const anonymousId = anonymizeIdentifier(rawAnonymousId);
  const now = new Date();

  const eventRecord: RawAnalyticsEvent = {
    id: 'evt_' + Math.random().toString(36).substring(2, 9),
    eventType,
    anonymousId,
    metadata: safeMetadata,
    timestamp: now,
  };

  // Add to memory ring buffer
  memoryEvents.unshift(eventRecord);
  if (memoryEvents.length > MAX_MEMORY_EVENTS) {
    memoryEvents.pop();
  }

  // Persist to Postgres via Prisma
  try {
    await prisma.analyticsEvent.create({
      data: {
        eventType,
        anonymousId,
        metadata: safeMetadata,
        timestamp: now,
      },
    });
  } catch (err) {
    // Fail silently to in-memory store so app never errors on telemetry
    console.warn('Analytics event db save skipped/failed:', (err as any)?.message || err);
  }
}

/**
 * Fetch aggregated statistics for the developer dashboard.
 */
export async function getAnalyticsDashboardStats(rangeDays: number = 7) {
  const now = new Date();
  const startDate = new Date();
  startDate.setDate(startDate.getDate() - rangeDays);
  startDate.setHours(0, 0, 0, 0);

  const todayStart = new Date();
  todayStart.setHours(0, 0, 0, 0);

  const yesterdayStart = new Date(todayStart);
  yesterdayStart.setDate(yesterdayStart.getDate() - 1);

  let events: RawAnalyticsEvent[] = [];

  try {
    const dbEvents = await prisma.analyticsEvent.findMany({
      where: {
        timestamp: { gte: startDate },
      },
      orderBy: { timestamp: 'asc' },
    });
    if (dbEvents && dbEvents.length > 0) {
      events = dbEvents.map(e => ({
        id: e.id,
        eventType: e.eventType,
        anonymousId: e.anonymousId,
        metadata: e.metadata,
        timestamp: e.timestamp,
      }));
    }
  } catch (err) {
    console.warn('Prisma analytics query failed, using memory store:', (err as any)?.message || err);
  }

  // If DB returned nothing or failed, use in-memory events filtered by date
  if (events.length === 0 && memoryEvents.length > 0) {
    events = memoryEvents.filter(e => e.timestamp >= startDate);
    events.reverse(); // put into ascending order
  }

  // Feature engagement counts
  const featureCounts: Record<string, number> = {
    session_start: 0,
    page_view: 0,
    scripture_read: 0,
    streak_updated: 0,
    streak_calendar_opened: 0,
    devotional_read: 0,
    prayer_checked: 0,
    ai_chat_prompt: 0,
    ai_chat_opened: 0,
    chat_file_upload: 0,
    canvas_opened: 0,
    canvas_created: 0,
    canvas_ai_generate: 0,
    canvas_shared: 0,
    canvas_imported: 0,
    note_created: 0,
    notes_ai_generate: 0,
    highlight_created: 0,
    highlight_deleted: 0,
    lectio_started: 0,
    reading_tracker_updated: 0,
    interlinear_opened: 0,
    rate_limit_blocked: 0,
  };

  // Daily map initialization
  const dailyMap: Record<string, { sessions: number; activeUsers: Set<string>; events: number }> = {};
  for (let d = 0; d <= rangeDays; d++) {
    const dateObj = new Date(startDate);
    dateObj.setDate(dateObj.getDate() + d);
    const key = dateObj.toISOString().split('T')[0];
    dailyMap[key] = { sessions: 0, activeUsers: new Set(), events: 0 };
  }

  // Hourly distribution: 24 buckets
  const hourlyDistribution = new Array(24).fill(0);

  // Today & Yesterday counters
  let totalSessionsToday = 0;
  let totalSessionsYesterday = 0;
  const dauTodaySet = new Set<string>();
  const dauYesterdaySet = new Set<string>();
  const activeUsersTotalSet = new Set<string>();

  for (const event of events) {
    const time = new Date(event.timestamp);
    const dateKey = time.toISOString().split('T')[0];
    const hour = time.getHours();

    hourlyDistribution[hour]++;
    activeUsersTotalSet.add(event.anonymousId);

    if (featureCounts[event.eventType] !== undefined) {
      featureCounts[event.eventType]++;
    } else {
      featureCounts[event.eventType] = (featureCounts[event.eventType] || 0) + 1;
    }

    if (dailyMap[dateKey]) {
      dailyMap[dateKey].events++;
      dailyMap[dateKey].activeUsers.add(event.anonymousId);
      if (event.eventType === 'session_start') {
        dailyMap[dateKey].sessions++;
      }
    }

    if (time >= todayStart) {
      dauTodaySet.add(event.anonymousId);
      if (event.eventType === 'session_start') totalSessionsToday++;
    } else if (time >= yesterdayStart && time < todayStart) {
      dauYesterdaySet.add(event.anonymousId);
      if (event.eventType === 'session_start') totalSessionsYesterday++;
    }
  }

  // Format daily trends
  const dailyTrends = Object.entries(dailyMap).map(([date, data]) => ({
    date,
    dayLabel: new Date(date + 'T12:00:00Z').toLocaleDateString('en-US', { weekday: 'short', month: 'numeric', day: 'numeric' }),
    sessions: data.sessions,
    activeUsers: data.activeUsers.size,
    totalEvents: data.events,
  }));

  // Identify busiest and quietest days
  let busiestDay = dailyTrends[0] || null;
  let quietestDay = dailyTrends[0] || null;

  for (const day of dailyTrends) {
    if (day.totalEvents > (busiestDay?.totalEvents || 0)) {
      busiestDay = day;
    }
    if (day.totalEvents < (quietestDay?.totalEvents ?? Infinity)) {
      quietestDay = day;
    }
  }

  return {
    periodDays: rangeDays,
    totalEvents: events.length,
    totalSessionsToday,
    sessionsYesterday: totalSessionsYesterday,
    dauToday: dauTodaySet.size,
    dauYesterday: dauYesterdaySet.size,
    activeUsersPeriod: activeUsersTotalSet.size,
    featureCounts,
    dailyTrends,
    hourlyDistribution,
    busiestDay: busiestDay ? { date: busiestDay.date, events: busiestDay.totalEvents } : null,
    quietestDay: quietestDay ? { date: quietestDay.date, events: quietestDay.totalEvents } : null,
  };
}

/**
 * Fetch the recent chronological stream of anonymous events.
 */
export async function getRecentAnonymousEvents(limit: number = 50): Promise<RawAnalyticsEvent[]> {
  try {
    const dbEvents = await prisma.analyticsEvent.findMany({
      take: limit,
      orderBy: { timestamp: 'desc' },
    });
    if (dbEvents && dbEvents.length > 0) {
      return dbEvents.map(e => ({
        id: e.id,
        eventType: e.eventType,
        anonymousId: e.anonymousId,
        metadata: e.metadata,
        timestamp: e.timestamp,
      }));
    }
  } catch (err) {
    console.warn('Prisma recent events query failed, using memory store:', err);
  }

  return memoryEvents.slice(0, limit);
}

/**
 * Clear all recorded telemetry events (admin maintenance / reset).
 */
export async function clearAllAnalyticsEvents(): Promise<void> {
  memoryEvents.length = 0;
  try {
    await prisma.analyticsEvent.deleteMany({});
  } catch (err) {
    console.warn('Prisma clear events error:', err);
  }
}

import { findCanonicalBook } from './bibleCanon';
import { getTranslation } from './bibleTranslations';
import { BibleChapter, BibleVerse, BibleBookData } from '@/types/bible';

// Tier 1: Fast In-Memory Cache
const MEMORY_CACHE = new Map<string, BibleChapter>();
// Book-level in-memory cache for local translations
const BOOK_MEMORY_CACHE = new Map<string, BibleBookData>();

const CACHE_PREFIX = 'theologica_bible_v1:';
const MAX_PERSISTENT_ITEMS = 80;

/**
 * Read from persistent client cache (localStorage)
 */
function getFromPersistentCache(key: string): BibleChapter | null {
  if (typeof window === 'undefined') return null;
  try {
    const raw = localStorage.getItem(CACHE_PREFIX + key);
    if (!raw) return null;
    return JSON.parse(raw) as BibleChapter;
  } catch {
    return null;
  }
}

/**
 * Save to persistent client cache (localStorage) with quota-safe eviction
 */
function saveToPersistentCache(key: string, data: BibleChapter) {
  if (typeof window === 'undefined') return;
  try {
    localStorage.setItem(CACHE_PREFIX + key, JSON.stringify(data));
  } catch (e) {
    // Evict oldest cached chapters if quota exceeded
    try {
      const keysToRemove: string[] = [];
      for (let i = 0; i < localStorage.length; i++) {
        const k = localStorage.key(i);
        if (k && k.startsWith(CACHE_PREFIX)) {
          keysToRemove.push(k);
          if (keysToRemove.length >= 20) break;
        }
      }
      keysToRemove.forEach((k) => localStorage.removeItem(k));
      localStorage.setItem(CACHE_PREFIX + key, JSON.stringify(data));
    } catch {
      // Ignore if localStorage completely full
    }
  }
}

export interface GetPassageResult {
  chapter: BibleChapter;
  verse?: BibleVerse;
}

/**
 * Unified Bible passage fetcher supporting local open translations and dynamic fallback.
 *
 * @param version - Translation abbreviation (e.g. "bsb", "web", "kjv", "asv", "esv")
 * @param book - Book name, abbreviation, or canonical code (e.g. "Genesis", "Gen", "GEN", "John", "1 Cor")
 * @param chapter - Chapter number (1-based)
 * @param verse - Optional verse number (1-based)
 */
export async function getPassage(
  version: string,
  book: string,
  chapter: number,
  verse?: number
): Promise<GetPassageResult> {
  const versionKey = (version || 'bsb').toLowerCase().trim();
  const bookMeta = findCanonicalBook(book);

  if (!bookMeta) {
    throw new Error(`Invalid Bible book reference: "${book}"`);
  }

  if (!Number.isInteger(chapter) || chapter < 1 || chapter > bookMeta.chapters) {
    throw new Error(`Invalid chapter for ${bookMeta.name}: ${chapter}`);
  }

  const bookCode = bookMeta.code;
  const translation = getTranslation(versionKey);
  const copyright = translation?.copyrightNotice;
  const cacheKey = `${versionKey}:${bookCode}:${chapter}`;

  // 1. Tier 1: Check Memory Cache (0ms)
  if (MEMORY_CACHE.has(cacheKey)) {
    const chapterData = MEMORY_CACHE.get(cacheKey)!;
    const singleVerse = verse ? chapterData.verses.find((v) => v.verse === verse) : undefined;
    return { chapter: chapterData, verse: singleVerse };
  }

  // 2. Tier 2: Check Persistent Local Storage (0ms)
  const persisted = getFromPersistentCache(cacheKey);
  if (persisted) {
    MEMORY_CACHE.set(cacheKey, persisted);
    const singleVerse = verse ? persisted.verses.find((v) => v.verse === verse) : undefined;
    return { chapter: persisted, verse: singleVerse };
  }

  // 3. Local Translations (BSB, WEB, KJV, KJV_STRONGS)
  const localDir = translation?.source.type === 'local' ? translation.source.dir : versionKey === 'kjv_strongs' ? 'kjv_strongs' : null;
  const isLocal = Boolean(localDir);
  if (isLocal) {
    const bookCacheKey = `${versionKey}:${bookCode}`;
    let bookData: BibleBookData | undefined = BOOK_MEMORY_CACHE.get(bookCacheKey);

    if (!bookData) {
      // Fetch the full book JSON (~30-60KB). This loads all chapters in this book in a single request!
      const res = await fetch(`/bibles/${localDir}/${bookCode}.json`);
      if (!res.ok) {
        throw new Error(`Failed to load local scripture data for ${versionKey.toUpperCase()} ${bookMeta.name}`);
      }
      bookData = (await res.json()) as BibleBookData;
      BOOK_MEMORY_CACHE.set(bookCacheKey, bookData);

      // Pre-warm memory cache for all chapters in this book for instant navigation
      for (const [chNum, chVerses] of Object.entries(bookData.chapters)) {
        const chPayload: BibleChapter = {
          book: bookCode,
          bookName: bookMeta.name,
          chapter: Number(chNum),
          translation: versionKey.toUpperCase(),
          verses: chVerses,
          copyright,
        };
        const itemKey = `${versionKey}:${bookCode}:${chNum}`;
        MEMORY_CACHE.set(itemKey, chPayload);
      }
    }

    const chapterVerses = bookData.chapters[String(chapter)] || [];
    const chapterPayload: BibleChapter = {
      book: bookCode,
      bookName: bookMeta.name,
      chapter,
      translation: versionKey.toUpperCase(),
      verses: chapterVerses,
      copyright,
    };

    MEMORY_CACHE.set(cacheKey, chapterPayload);
    saveToPersistentCache(cacheKey, chapterPayload);

    const singleVerse = verse ? chapterPayload.verses.find((v) => v.verse === verse) : undefined;
    return { chapter: chapterPayload, verse: singleVerse };
  }

  // 4. Dynamic Fallback: Query internal API route (/api/bible/[version]/[book]/[chapter])
  const apiUrl = `/api/bible/${versionKey}/${bookCode}/${chapter}`;
  const apiRes = await fetch(apiUrl);
  if (!apiRes.ok) {
    const errJson = await apiRes.json().catch(() => ({}));
    const message = errJson.message || errJson.error || `HTTP ${apiRes.status}: Failed to fetch scripture`;
    throw new Error(message);
  }

  const remoteChapter = (await apiRes.json()) as BibleChapter;
  MEMORY_CACHE.set(cacheKey, remoteChapter);
  saveToPersistentCache(cacheKey, remoteChapter);

  const singleVerse = verse ? remoteChapter.verses.find((v) => v.verse === verse) : undefined;
  return { chapter: remoteChapter, verse: singleVerse };
}

/**
 * Convenience method to get exact verse text
 */
export async function getVerseText(
  version: string,
  book: string,
  chapter: number,
  verse: number
): Promise<string | undefined> {
  try {
    const result = await getPassage(version, book, chapter, verse);
    return result.verse?.text;
  } catch {
    return undefined;
  }
}

/**
 * Fetch Strong's tagged KJV passage for exact interlinear alignment
 */
export async function getStrongsPassage(
  book: string,
  chapter: number
): Promise<BibleChapter | null> {
  try {
    const result = await getPassage('kjv_strongs', book, chapter);
    return result.chapter;
  } catch (err) {
    console.warn(`Could not load Strong's tagged passage for ${book} ${chapter}:`, err);
    return null;
  }
}

